const RECIPE_DB = {
"Spaghetti Carbonara":{"name":"Spaghetti Carbonara","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Fresh_made_pasta_noodles.jpg/800px-Fresh_made_pasta_noodles.jpg","country":"Italy","description":"A rich Roman pasta of eggs, Pecorino Romano and guanciale. No cream — ever. The silky sauce forms from residual heat alone.","prepTime":"10 mins","cookTime":"15 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"spaghetti"},{"amount":"200g","item":"guanciale or pancetta, diced"},{"amount":"4 large","item":"eggs"},{"amount":"2","item":"egg yolks"},{"amount":"100g","item":"Pecorino Romano, finely grated"},{"amount":"50g","item":"Parmesan, finely grated"},{"amount":"2 tsp","item":"freshly cracked black pepper"}],"steps":["Bring a large pot of heavily salted water to a boil. Cook spaghetti until al dente, reserving 200ml pasta water before draining.","Fry guanciale in a cold pan over medium heat until fat renders and edges crisp, about 8 minutes. Remove from heat.","Whisk eggs, egg yolks, Pecorino and Parmesan in a bowl. Season generously with black pepper.","Add drained pasta to the guanciale pan. Toss to coat in the fat.","Remove pan from heat completely. Pour egg mixture over pasta, tossing vigorously and adding pasta water a splash at a time until a glossy sauce forms.","Serve immediately with extra Pecorino and black pepper."],"tip":"Take the pan fully off the heat before adding eggs. Any residual heat will cook them — too much and you get scrambled eggs.","story":"Carbonara emerged in Rome in the mid-20th century. The authentic version uses only guanciale, Pecorino, eggs and black pepper."},
"Risotto alla Milanese":{"name":"Risotto alla Milanese","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Risotto_alla_milanese.jpg/800px-Risotto_alla_milanese.jpg","country":"Italy","description":"Milan's golden saffron risotto, slow-stirred to a flowing wave consistency the Milanese call all'onda.","prepTime":"10 mins","cookTime":"30 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"320g","item":"Carnaroli or Arborio rice"},{"amount":"1.2L","item":"hot chicken stock"},{"amount":"1 large","item":"white onion, finely diced"},{"amount":"150ml","item":"dry white wine"},{"amount":"generous pinch","item":"saffron threads"},{"amount":"80g","item":"cold unsalted butter, cubed"},{"amount":"80g","item":"Parmesan, finely grated"}],"steps":["Warm stock and steep saffron in 2 tbsp hot stock. Keep stock at a gentle simmer throughout.","Soften onion in olive oil and half the butter over low heat for 10 minutes. Do not brown.","Add rice and toast 2 minutes until edges turn translucent. Pour in wine and stir until absorbed.","Add stock one ladle at a time, stirring constantly and waiting until each ladle is absorbed. Add saffron liquid after 10 minutes.","After 18-20 minutes the rice should be al dente. Remove from heat.","Stir in cold butter and Parmesan vigorously. Cover and rest 2 minutes before serving."],"tip":"Cold butter at the mantecatura stage is essential — it emulsifies into the starchy liquid to create the glossy finish.","story":"Risotto alla Milanese has been made in Milan since the 16th century, when a Flemish glazier working on the Duomo added saffron to his rice on a whim."},
"Tiramisu":{"name":"Tiramisu","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Tiramisu_with_blueberries.jpg/800px-Tiramisu_with_blueberries.jpg","country":"Italy","description":"Italy's most famous dessert — espresso-soaked ladyfingers layered with mascarpone cream and dusted with bitter cocoa. Ethereally light yet deeply rich.","prepTime":"25 mins","cookTime":"0 mins","serves":8,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"mascarpone cheese"},{"amount":"6","item":"eggs, separated"},{"amount":"120g","item":"caster sugar"},{"amount":"300ml","item":"strong espresso, cooled"},{"amount":"4 tbsp","item":"Marsala wine or dark rum"},{"amount":"300g","item":"savoiardi (ladyfinger biscuits)"},{"amount":"3 tbsp","item":"cocoa powder, for dusting"}],"steps":["Beat egg yolks with sugar until pale and thick, about 5 minutes. Beat in mascarpone until smooth.","Whisk egg whites to stiff peaks. Fold gently into the mascarpone mixture in three additions.","Mix espresso and Marsala in a shallow dish. Quickly dip each ladyfinger — 1 second per side, no more.","Arrange a layer of soaked ladyfingers in a dish. Spread half the mascarpone cream over. Repeat layers.","Refrigerate at least 4 hours, ideally overnight. Dust generously with cocoa just before serving."],"tip":"The dipping time is critical — one second per side. Over-soaked biscuits will make the whole dessert collapse and turn soggy.","story":"Tiramisu was created in the 1960s at Le Beccherie restaurant in Treviso, though its origin is still hotly disputed by restaurants across the Veneto."},
"Butter Chicken":{"name":"Butter Chicken","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Chicken_makhani.jpg/800px-Chicken_makhani.jpg","country":"India","description":"The world's most beloved Indian curry — tandoor-roasted chicken in a velvety tomato sauce enriched with cream and butter. Mellow, aromatic and deeply satisfying.","prepTime":"20 mins","cookTime":"40 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"chicken thighs, boneless and skinless"},{"amount":"200g","item":"full-fat yoghurt"},{"amount":"2 tbsp","item":"tandoori masala"},{"amount":"2 tbsp","item":"ginger-garlic paste"},{"amount":"400g","item":"tinned chopped tomatoes"},{"amount":"1 large","item":"onion, finely sliced"},{"amount":"3 tbsp","item":"unsalted butter"},{"amount":"150ml","item":"double cream"},{"amount":"2 tsp each","item":"ground cumin and ground coriander"},{"amount":"1 tsp each","item":"garam masala and kashmiri chilli powder"},{"amount":"1 tbsp","item":"honey"}],"steps":["Mix yoghurt, tandoori masala, half the ginger-garlic paste and salt. Coat chicken and marinate 2 hours.","Grill marinated chicken over high heat until charred and cooked through. Set aside.","Melt butter. Cook onions until deep golden, 20 minutes. Add remaining ginger-garlic paste and cook 2 minutes.","Add spices, stir 30 seconds, then add tomatoes. Cook 15 minutes until thick.","Blend sauce until completely smooth. Return to pan, stir in cream, garam masala and honey. Simmer 5 minutes.","Add grilled chicken. Simmer 5 minutes. Serve with naan or basmati rice."],"tip":"Blending the sauce until perfectly smooth is what gives butter chicken its signature velvety texture. Don't skip this step.","story":"Butter chicken was invented by accident at Moti Mahal restaurant in Delhi in the 1950s, when leftover tandoori chicken was reheated in a tomato-cream sauce."},
"Biryani":{"name":"Chicken Biryani","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Biryani_South_India_style.jpg/800px-Biryani_South_India_style.jpg","country":"India","description":"The crown jewel of Indian rice dishes — fragrant basmati layered with spiced chicken and sealed with dough to steam. Every mouthful is a different combination of flavour.","prepTime":"30 mins","cookTime":"1 hr","serves":6,"difficulty":"Hard","ingredients":[{"amount":"1kg","item":"chicken pieces, bone-in"},{"amount":"500g","item":"basmati rice, soaked 30 mins"},{"amount":"300g","item":"full-fat yoghurt"},{"amount":"3 large","item":"onions, thinly sliced"},{"amount":"2 tbsp","item":"ginger-garlic paste"},{"amount":"1 tsp each","item":"turmeric, chilli powder, garam masala"},{"amount":"large pinch","item":"saffron, steeped in 4 tbsp warm milk"},{"amount":"4 tbsp","item":"ghee"},{"amount":"handful","item":"fresh mint and coriander leaves"}],"steps":["Marinate chicken in yoghurt, ginger-garlic paste and spices for at least 2 hours.","Fry onions in ghee until deep golden and crispy. Reserve half for garnish.","Cook marinated chicken with half the onions until almost done, about 20 minutes.","Par-cook rice until 70% done (still has a bite). Drain.","Layer in a heavy pot: chicken, rice, saffron milk, fried onions, mint and coriander. Seal with foil and lid.","Cook on high heat for 5 minutes then lowest heat for 25 minutes. Rest 10 minutes before opening."],"tip":"The dum (slow steam) cooking is the soul of biryani. Don't be tempted to open the pot early — the steam is what cooks the rice through and infuses everything with fragrance.","story":"Biryani arrived in India with Mughal emperors in the 16th century. Each region developed its own version — Hyderabadi, Lucknowi, Kolkata — all distinct and all contested as the best."},
"Samosas":{"name":"Samosas","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Samosachutney.jpg/800px-Samosachutney.jpg","country":"India","description":"Crispy pastry parcels filled with spiced potato and peas. India's greatest street food — eaten at every chai stall from Mumbai to Delhi.","prepTime":"45 mins","cookTime":"25 mins","serves":16,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"plain flour"},{"amount":"6 tbsp","item":"vegetable oil or ghee"},{"amount":"1 tsp","item":"salt"},{"amount":"600g","item":"potatoes, boiled and roughly mashed"},{"amount":"150g","item":"frozen peas, thawed"},{"amount":"2 tsp","item":"cumin seeds"},{"amount":"2 tsp","item":"ground coriander"},{"amount":"1 tsp","item":"garam masala"},{"amount":"1","item":"green chilli, finely chopped"},{"amount":"2 tbsp","item":"fresh coriander, chopped"},{"amount":"oil","item":"for deep frying"}],"steps":["Make dough: rub oil into flour and salt until breadcrumb texture. Add just enough water to form a stiff dough. Rest 30 minutes.","Cook cumin seeds in a little oil until they pop. Add peas, mashed potato and all spices. Season well and cool.","Divide dough into 8 balls. Roll each into an oval, cut in half to make two semicircles.","Form each semicircle into a cone, seal the edge with water. Fill with 2 tbsp potato filling. Seal the top firmly.","Deep fry in batches at 170°C for 6-8 minutes until deep golden, turning once. Drain on paper.","Serve with mint chutney and tamarind sauce."],"tip":"A stiff dough is essential — soft dough produces greasy samosas that fall apart in the oil. The dough should feel quite firm before resting.","story":"Samosas originated in Central Asia and travelled to India along ancient trade routes. The Mughal court records mention samosas being served as early as the 13th century."},
"Pad Thai":{"name":"Pad Thai","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Phad_thai_kung_chang_kien.jpg/800px-Phad_thai_kung_chang_kien.jpg","country":"Thailand","description":"Thailand's national noodle dish — rice noodles stir-fried with egg, tofu and prawns in a sweet-savoury tamarind sauce, finished with crushed peanuts and lime.","prepTime":"20 mins","cookTime":"15 mins","serves":2,"difficulty":"Medium","ingredients":[{"amount":"200g","item":"flat rice noodles (5mm wide)"},{"amount":"200g","item":"raw tiger prawns, peeled"},{"amount":"100g","item":"firm tofu, pressed and cubed"},{"amount":"3 tbsp","item":"tamarind paste"},{"amount":"2 tbsp","item":"fish sauce"},{"amount":"1 tbsp","item":"oyster sauce"},{"amount":"2 tsp","item":"palm sugar or brown sugar"},{"amount":"3","item":"eggs"},{"amount":"3","item":"garlic cloves, minced"},{"amount":"100g","item":"bean sprouts"},{"amount":"3","item":"spring onions, cut into 3cm pieces"},{"amount":"60g","item":"roasted peanuts, crushed"},{"amount":"2","item":"limes, halved"}],"steps":["Soak noodles in cold water 30 minutes until pliable but still firm. Drain.","Mix tamarind paste, fish sauce, oyster sauce and sugar. Taste — sweet, sour and salty in balance.","Heat wok over highest heat until smoking. Fry garlic 30 seconds, add tofu until golden.","Add prawns and cook until pink. Push everything to side.","Add noodles and sauce. Toss vigorously for 2 minutes.","Push noodles to side, crack eggs in, scramble briefly then fold into noodles.","Add spring onions and bean sprouts. Toss 30 seconds. Serve with crushed peanuts and lime."],"tip":"The key is extreme heat and working fast. A domestic hob won't get hot enough — if possible use a gas burner on full blast outside.","story":"Pad Thai was promoted as a national dish in the 1940s by the Thai government to encourage rice noodle consumption and build national identity."},
"Green Curry":{"name":"Green Curry","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Green_curry.jpg/800px-Green_curry.jpg","country":"Thailand","description":"Thailand's most aromatic curry — coconut milk simmered with homemade green paste, vegetables and chicken. Fresh, herbal and gently spicy.","prepTime":"25 mins","cookTime":"20 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"800ml","item":"coconut milk (2 tins)"},{"amount":"600g","item":"chicken breast, sliced"},{"amount":"3 tbsp","item":"green curry paste"},{"amount":"2 tbsp","item":"fish sauce"},{"amount":"1 tsp","item":"palm sugar"},{"amount":"150g","item":"bamboo shoots, sliced"},{"amount":"2","item":"courgettes, sliced"},{"amount":"handful","item":"Thai basil leaves"},{"amount":"4","item":"kaffir lime leaves, torn"},{"amount":"2","item":"green chillies, sliced"},{"amount":"1 tbsp","item":"vegetable oil"}],"steps":["Heat oil in a wok. Fry green curry paste over medium heat for 2 minutes until fragrant.","Add half the coconut milk and bring to a gentle boil, stirring constantly.","Add chicken and cook through, about 8 minutes.","Add remaining coconut milk, fish sauce, palm sugar, bamboo shoots and courgettes. Simmer 5 minutes.","Add kaffir lime leaves and chillies. Taste and adjust fish sauce and sugar.","Stir in Thai basil at the last moment. Serve with jasmine rice."],"tip":"The key is frying the curry paste in oil or coconut cream (the thick top layer of the tin) first, before adding the rest of the liquid. This 'cracks' the paste and releases the aromatics.","story":"Green curry — or gaeng keow wan — gets its colour from fresh green chillies and herbs. It developed in central Thailand and is now one of the country's most recognised dishes globally."},
"Tom Yum Soup":{"name":"Tom Yum Soup","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Tom_yum_kung_kung.jpg/800px-Tom_yum_kung_kung.jpg","country":"Thailand","description":"Thailand's bold, sour-hot prawn soup — broth perfumed with lemongrass, galangal and kaffir lime, spiked with chilli and lifted with lime juice. Restorative and electric.","prepTime":"15 mins","cookTime":"20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"1L","item":"chicken or prawn stock"},{"amount":"400g","item":"large raw prawns, peeled (shells reserved)"},{"amount":"3 stalks","item":"lemongrass, bruised and cut into 5cm pieces"},{"amount":"5 slices","item":"galangal or ginger"},{"amount":"6","item":"kaffir lime leaves, torn"},{"amount":"4","item":"bird's eye chillies, bruised"},{"amount":"3 tbsp","item":"fish sauce"},{"amount":"3 tbsp","item":"lime juice"},{"amount":"1 tsp","item":"palm sugar"},{"amount":"200g","item":"oyster mushrooms, torn"},{"amount":"handful","item":"fresh coriander"}],"steps":["Simmer prawn shells in stock for 10 minutes. Strain and discard shells.","Add lemongrass, galangal, kaffir lime leaves and chillies to the stock. Simmer 5 minutes.","Add mushrooms and cook 2 minutes.","Add prawns and cook until just pink, about 2 minutes.","Season with fish sauce, lime juice and palm sugar. The balance should be sour, salty, spicy and slightly sweet.","Serve immediately topped with fresh coriander."],"tip":"The aromatics — lemongrass, galangal, kaffir lime — are for flavour only. Don't eat them. Their role is purely to perfume the broth during cooking.","story":"Tom yum is considered one of Thailand's national dishes and has spread across Southeast Asia. The name means 'boiling' (tom) and 'mixed' (yum) — a reference to the cooking method."},
"Ramen":{"name":"Ramen","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Ramen_hamburger.jpg/800px-Ramen_hamburger.jpg","country":"Japan","description":"Japan's beloved noodle soup — a milky pork broth rich with collagen, topped with chashu pork, soft-boiled egg and spring onion. A project worth every hour.","prepTime":"45 mins","cookTime":"4 hrs","serves":4,"difficulty":"Hard","ingredients":[{"amount":"1kg","item":"pork bones (trotters and neck)"},{"amount":"4 slices","item":"pork belly, rolled and tied"},{"amount":"4","item":"ramen eggs (soft-boiled, marinated in soy and mirin overnight)"},{"amount":"400g","item":"fresh ramen noodles"},{"amount":"4 tbsp","item":"white miso paste"},{"amount":"2 tbsp","item":"soy sauce"},{"amount":"1 tbsp","item":"mirin"},{"amount":"4","item":"spring onions, sliced"},{"amount":"2 sheets","item":"nori, halved"},{"amount":"2 tsp","item":"sesame oil"}],"steps":["Blanch pork bones in boiling water 5 minutes. Drain, rinse and return to pot with fresh water. Bring to vigorous boil.","Boil hard for 2 hours until broth turns white and milky. Top up water as needed.","Sear pork belly rolls. Add soy sauce, mirin and a splash of water. Simmer 30 minutes until lacquered. Cool and slice.","Whisk miso paste into a ladleful of hot broth. Stir into main pot with soy sauce and sesame oil.","Cook noodles and divide between bowls.","Ladle boiling broth over noodles. Top each bowl with pork slices, halved egg, nori and spring onions."],"tip":"The vigorous boil creates the milky white colour. A gentle simmer produces a clear broth. You need high heat to emulsify the collagen and fat.","story":"Ramen was introduced to Japan by Chinese immigrants in the late 19th century and evolved into a uniquely Japanese obsession, with regional variations so different they barely resemble each other."},
"Sushi":{"name":"Nigiri Sushi","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Sushi_platter.jpg/800px-Sushi_platter.jpg","country":"Japan","description":"The purest expression of Japanese cuisine — a small hand-pressed pillow of vinegared rice, crowned with the freshest fish. Simplicity is everything.","prepTime":"40 mins","cookTime":"20 mins","serves":4,"difficulty":"Hard","ingredients":[{"amount":"400g","item":"sushi rice"},{"amount":"5 tbsp","item":"rice vinegar"},{"amount":"2 tbsp","item":"sugar"},{"amount":"1 tsp","item":"salt"},{"amount":"200g","item":"sushi-grade salmon, thinly sliced"},{"amount":"200g","item":"sushi-grade tuna, thinly sliced"},{"amount":"100g","item":"sushi-grade sea bass, thinly sliced"},{"amount":"wasabi, soy sauce, pickled ginger","item":"to serve"}],"steps":["Cook rice. While warm, fold in vinegar mixed with dissolved sugar and salt. Fan while folding to cool and make glossy.","Keep rice at body temperature — not cold. Cover with a damp cloth.","Wet hands with vinegared water. Take 20g rice and shape into an oval with gentle but firm pressure. Aim for tight but not dense.","Smear a tiny amount of wasabi on top of the rice. Drape a slice of fish over, pressing gently to adhere.","Repeat. Serve immediately with soy sauce, pickled ginger and remaining wasabi."],"tip":"The rice is the soul of sushi, not the fish. The correct temperature, texture and seasoning of the rice is what separates great sushi from average. Never refrigerate nigiri rice.","story":"Nigiri sushi as we know it was developed in Tokyo (then Edo) in the early 19th century as a fast food sold from street stalls near the fish market — the original fast food."},
"Gyoza":{"name":"Gyoza","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Gyoza_dumplings_on_plate.jpg/800px-Gyoza_dumplings_on_plate.jpg","country":"Japan","description":"Japan's addictive pan-fried dumplings — a crispy golden base giving way to a juicy pork and cabbage filling, finished with a dipping sauce sharp with rice vinegar.","prepTime":"45 mins","cookTime":"15 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"300g","item":"pork mince"},{"amount":"200g","item":"cabbage, finely shredded"},{"amount":"3","item":"spring onions, finely chopped"},{"amount":"2 tsp","item":"fresh ginger, grated"},{"amount":"2","item":"garlic cloves, minced"},{"amount":"2 tbsp","item":"soy sauce"},{"amount":"1 tsp","item":"sesame oil"},{"amount":"30","item":"gyoza wrappers"},{"amount":"3 tbsp","item":"vegetable oil"},{"amount":"soy sauce, rice vinegar and chilli oil","item":"to serve"}],"steps":["Salt shredded cabbage, leave 10 minutes, then squeeze out all liquid. This is essential.","Mix pork, drained cabbage, spring onions, ginger, garlic, soy sauce and sesame oil until combined.","Place a heaped teaspoon of filling in the centre of each wrapper. Wet the edge, fold and pleat to seal.","Heat oil in a non-stick pan over medium-high. Add gyoza flat-side down in one layer.","Fry until bases are golden, 3 minutes. Add 60ml water, cover immediately. Steam 5 minutes until water evaporates.","Remove lid and cook 1 minute more until bases are crispy again. Serve with dipping sauce."],"tip":"Squeezing all the moisture out of the cabbage is essential. Wet filling creates steam inside the wrapper, making them burst and giving you soggy bottoms.","story":"Gyoza arrived in Japan from China (jiaozi) via soldiers returning after WWII. Japan adapted the dish with more garlic and ginger, and the characteristic single-side fry became uniquely Japanese."},
"Tacos al Pastor":{"name":"Tacos al Pastor","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Tacos_de_trompo.jpg/800px-Tacos_de_trompo.jpg","country":"Mexico","description":"Mexico City's iconic street taco — pork marinated in dried chillies and achiote, cooked with caramelised pineapple. The flavour of Mexico in a corn tortilla.","prepTime":"30 mins","cookTime":"25 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1kg","item":"pork shoulder, thinly sliced"},{"amount":"3","item":"guajillo chillies, dried"},{"amount":"2","item":"ancho chillies, dried"},{"amount":"2 tbsp","item":"achiote paste"},{"amount":"3","item":"garlic cloves"},{"amount":"1 tsp each","item":"dried oregano, ground cumin, ground cinnamon"},{"amount":"3 tbsp","item":"white wine vinegar"},{"amount":"200g","item":"fresh pineapple, sliced"},{"amount":"24","item":"small corn tortillas"},{"amount":"1","item":"white onion, finely diced"},{"amount":"1 bunch","item":"fresh coriander, chopped"},{"amount":"2","item":"limes, cut into wedges"}],"steps":["Toast dried chillies briefly in a dry pan. Remove stems and seeds, soak in boiling water 15 minutes.","Blend chillies with achiote paste, garlic, spices, vinegar and salt until smooth.","Coat pork slices in marinade. Refrigerate at least 4 hours, ideally overnight.","Cook pork in batches on a very hot cast-iron griddle, pressing down, until charred at edges. Chop roughly.","Caramelise pineapple slices on the griddle.","Warm tortillas. Load with pork, diced pineapple, onion and coriander. Serve with lime."],"tip":"Get the griddle ripping hot. You want char and caramelisation, not steaming. Cook in small batches so the meat sears rather than stews.","story":"Al pastor is a Mexican adaptation of shawarma brought by Lebanese immigrants to Mexico City in the early 20th century — the vertical spit technique is identical."},
"Guacamole":{"name":"Guacamole","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Guacamole_and_chips.jpg/800px-Guacamole_and_chips.jpg","country":"Mexico","description":"Mexico's most celebrated condiment — ripe avocados crushed with lime, chilli, onion and coriander. Made in a molcajete, it has a texture no blender can replicate.","prepTime":"15 mins","cookTime":"0 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"3 large","item":"ripe Hass avocados"},{"amount":"juice of 2","item":"limes"},{"amount":"1","item":"jalapeño, finely chopped (seeds removed for less heat)"},{"amount":"half","item":"white onion, very finely diced"},{"amount":"2 tbsp","item":"fresh coriander, roughly chopped"},{"amount":"1 tsp","item":"sea salt"},{"amount":"1","item":"small ripe tomato, deseeded and diced (optional)"}],"steps":["Halve and pit avocados. Scoop flesh into a molcajete or bowl.","Add lime juice and salt. Crush roughly — you want texture, not a smooth paste.","Add jalapeño, onion and coriander. Fold to combine.","Taste and adjust lime and salt. Add tomato if using and fold gently.","Serve immediately. To store briefly, press cling film directly onto the surface to prevent browning."],"tip":"The key is ripe avocados — they must give when pressed. Unripe avocados have no flavour and won't crush properly. If in doubt, wait another day.","story":"Guacamole has been made in Mexico for at least 500 years. The word comes from the Aztec nahuatl: ahuacatl (avocado) and molli (sauce). The Aztecs considered avocado an aphrodisiac."},
"Mole Negro":{"name":"Mole Negro","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Mole_negro_ingredientes.jpg/800px-Mole_negro_ingredientes.jpg","country":"Mexico","description":"Oaxaca's legendary sauce — over 30 ingredients including dried chillies, chocolate, spices and charred tortilla, simmered for hours. The most complex sauce in Mexican cooking.","prepTime":"1 hr","cookTime":"3 hrs","serves":8,"difficulty":"Hard","ingredients":[{"amount":"6","item":"mulato chillies, dried"},{"amount":"4","item":"ancho chillies, dried"},{"amount":"4","item":"pasilla negro chillies, dried"},{"amount":"2","item":"chihuacle negro chillies, dried"},{"amount":"50g","item":"dark chocolate (70%), broken"},{"amount":"2","item":"corn tortillas, toasted until almost burnt"},{"amount":"4","item":"garlic cloves"},{"amount":"2","item":"tomatoes, charred"},{"amount":"1 tsp each","item":"ground cinnamon, cumin, black pepper, dried oregano"},{"amount":"3 tbsp","item":"lard or vegetable oil"},{"amount":"1L","item":"chicken stock"},{"amount":"1","item":"whole chicken, poached"}],"steps":["Toast chillies in a dry pan until fragrant and slightly darkened. Soak in hot water 30 minutes. Drain.","Char tomatoes and garlic in a dry pan until blackened on outside.","Blend chillies with tomatoes, garlic, charred tortilla, chocolate and all spices with a little stock. Blend until perfectly smooth.","Fry the blended paste in lard over high heat, stirring constantly, for 10 minutes. It will spit and thicken.","Add remaining stock gradually, stirring. Simmer uncovered for 1.5-2 hours until thick and dark. Season with salt.","Serve over poached chicken pieces with rice and warm tortillas."],"tip":"The charred tortilla is not a mistake — it is essential. The charring adds the bitter, smoky complexity that defines mole negro. Don't be afraid to burn it properly.","story":"Mole negro is one of the seven moles of Oaxaca and takes days to make properly. It is served at weddings, baptisms and funerals — the sauce of celebration and mourning alike."},
"Boeuf Bourguignon":{"name":"Boeuf Bourguignon","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Boeuf_bourguignon.jpg/800px-Boeuf_bourguignon.jpg","country":"France","description":"The definitive French braised beef — slow-cooked in Burgundy wine with lardons, pearl onions and mushrooms until the meat falls apart and the sauce is impossibly rich.","prepTime":"30 mins","cookTime":"3 hrs","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1.5kg","item":"beef chuck, cut into 4cm chunks"},{"amount":"750ml","item":"Burgundy or full-bodied red wine"},{"amount":"200g","item":"lardons or thick-cut bacon, diced"},{"amount":"200g","item":"pearl onions, peeled"},{"amount":"300g","item":"chestnut mushrooms, quartered"},{"amount":"3","item":"garlic cloves, crushed"},{"amount":"2 tbsp","item":"tomato purée"},{"amount":"2","item":"bay leaves"},{"amount":"4 sprigs","item":"fresh thyme"},{"amount":"2 tbsp","item":"plain flour"}],"steps":["Pat beef dry and season generously. Brown in batches in a heavy Dutch oven over high heat.","Fry lardons until golden. Add pearl onions and cook until lightly browned. Remove and set aside.","Soften garlic in same pot. Stir in tomato purée and flour, cook 1 minute.","Return beef. Pour over wine and enough water to just cover. Add bay leaves and thyme. Simmer.","Cover and cook on lowest heat for 2.5-3 hours until beef is completely tender.","In the last 20 minutes, fry mushrooms in butter until golden, add to stew along with reserved lardons and onions."],"tip":"Make it a day ahead. Bourguignon always tastes better reheated the next day once the flavours have had time to meld.","story":"Named after the Burgundy region, this was peasant food before Julia Child introduced it to American kitchens in 1961. Her version in Mastering the Art of French Cooking defined it for a generation."},
"Crème Brûlée":{"name":"Crème Brûlée","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Flambee.jpg/800px-Flambee.jpg","country":"France","description":"France's most elegant dessert — a barely-set vanilla custard beneath a crackling caramelised sugar crust. The tension between the brittle top and yielding cream is everything.","prepTime":"20 mins","cookTime":"45 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"600ml","item":"double cream"},{"amount":"1","item":"vanilla pod, split and seeds scraped"},{"amount":"6","item":"egg yolks"},{"amount":"80g","item":"caster sugar"},{"amount":"6 tsp","item":"caster sugar, for the crust"}],"steps":["Heat cream with vanilla pod and seeds until just below boiling. Remove vanilla pod.","Whisk egg yolks with sugar until pale. Gradually pour hot cream over, whisking constantly. Strain.","Pour into 6 ramekins set in a roasting tin. Fill the tin with boiling water to halfway up the ramekins.","Bake at 150°C for 35-40 minutes until set with a gentle wobble in the centre. Cool then refrigerate at least 2 hours.","Just before serving, sprinkle 1 tsp caster sugar evenly over each. Caramelise with a blowtorch until amber and bubbling.","Allow the sugar crust to harden for 1 minute. Tap to crack and eat immediately."],"tip":"The custard should wobble like set jelly, not slosh like liquid. An undercooked crème brûlée will never set properly even when cold.","story":"Crème brûlée has been claimed by France, England and Catalonia. The French name is earliest in print, but Cambridge college records show 'burnt cream' served to scholars in 1691."},
"Ratatouille":{"name":"Ratatouille","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Ratatouille-melanzane-300.jpg/800px-Ratatouille-melanzane-300.jpg","country":"France","description":"Provence's great summer vegetable stew — courgettes, aubergine, peppers and tomatoes layered and slow-cooked until they melt into a sweet, fragrant whole.","prepTime":"25 mins","cookTime":"1 hr","serves":6,"difficulty":"Easy","ingredients":[{"amount":"2 large","item":"aubergines, cut into 2cm cubes"},{"amount":"3","item":"courgettes, sliced into rounds"},{"amount":"2","item":"red peppers, deseeded and sliced"},{"amount":"2","item":"yellow peppers, deseeded and sliced"},{"amount":"4","item":"ripe tomatoes, roughly chopped"},{"amount":"1 large","item":"onion, sliced"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"handful","item":"fresh basil"},{"amount":"2 sprigs","item":"fresh thyme"},{"amount":"6 tbsp","item":"olive oil"}],"steps":["Salt aubergine cubes and leave 20 minutes. Rinse and dry.","Fry each vegetable separately in olive oil until lightly golden. This is the key step — don't rush it.","Gently combine all vegetables in the pot with garlic, thyme and tomatoes.","Cook uncovered over lowest heat for 40 minutes, stirring occasionally, until everything is soft and the liquid has reduced.","Remove thyme. Stir in torn basil. Taste and season generously.","Serve warm, at room temperature, or the next day. It improves overnight."],"tip":"Frying each vegetable separately before combining is what distinguishes real ratatouille from a vegetable soup. It gives each component character before they come together.","story":"Ratatouille is a Provençal peasant dish whose name comes from the French touiller — to toss or stir. The Disney film of the same name sparked a global revival of interest in the dish."},
"Paella":{"name":"Paella Valenciana","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Paella_Valenciana.jpg/800px-Paella_Valenciana.jpg","country":"Spain","description":"The original paella from Valencia — rabbit and chicken with green beans, cooked over fire in a wide shallow pan until the bottom forms the prized socarrat crust.","prepTime":"20 mins","cookTime":"45 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"chicken thighs, bone-in"},{"amount":"300g","item":"rabbit pieces"},{"amount":"300g","item":"paella rice (Bomba or Calasparra)"},{"amount":"1L","item":"hot chicken stock"},{"amount":"200g each","item":"green beans (trimmed) and butter beans (drained)"},{"amount":"400g","item":"tinned chopped tomatoes"},{"amount":"1 tsp","item":"sweet smoked paprika"},{"amount":"generous pinch","item":"saffron threads"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"6 tbsp","item":"olive oil"}],"steps":["Steep saffron in 3 tbsp hot stock. Brown meat in batches in a wide paella pan. Remove.","Fry garlic until golden, add tomatoes and paprika. Cook 10 minutes to a paste (sofrito).","Return meat. Add stock, saffron liquid and salt. Bring to rapid boil.","Add rice evenly. Do not stir from this point.","Add beans. Cook on medium-high 10 minutes then medium for 8 more.","Increase heat for final 2 minutes to form socarrat. Remove from heat, cover loosely and rest 5 minutes."],"tip":"Never stir once the rice goes in. Listen for the gentle crackling from the bottom — that is the socarrat forming. That is what you are cooking for.","story":"Paella originated in Valencia and was originally cooked by farmworkers over open fires using whatever was at hand — rabbit, snails, and seasonal vegetables."},
"Gazpacho":{"name":"Gazpacho","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Gazpacho_2.jpg/800px-Gazpacho_2.jpg","country":"Spain","description":"Andalusia's brilliant cold tomato soup — raw vegetables blended until silky, chilled until icy. The greatest thing you can eat on a hot day.","prepTime":"20 mins","cookTime":"0 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"1kg","item":"very ripe tomatoes, roughly chopped"},{"amount":"1","item":"cucumber, peeled and deseeded"},{"amount":"1","item":"red pepper, deseeded"},{"amount":"2","item":"garlic cloves"},{"amount":"100g","item":"stale white bread, crusts removed"},{"amount":"4 tbsp","item":"good olive oil"},{"amount":"2 tbsp","item":"sherry vinegar"},{"amount":"1 tsp","item":"salt"},{"amount":"to garnish","item":"diced cucumber, pepper and croutons"}],"steps":["Soak bread in water for 5 minutes. Squeeze out.","Blend tomatoes, cucumber, pepper, garlic and soaked bread until completely smooth.","With blender running, slowly pour in olive oil to emulsify.","Add sherry vinegar and salt. Blend again.","Pass through a sieve for a smoother result or leave as is for more texture.","Refrigerate at least 2 hours until very cold. Serve in chilled bowls with garnishes."],"tip":"Quality tomatoes are everything. Watery supermarket tomatoes produce a watery gazpacho. Use the ripest, most flavourful tomatoes you can find — ideally in late summer.","story":"Gazpacho has been made in Andalusia since at least the 15th century, originally without tomatoes (which hadn't arrived from the Americas). The original was bread, garlic, olive oil and vinegar."},
"Moussaka":{"name":"Moussaka","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Moussaka_by_Yiannis.jpg/800px-Moussaka_by_Yiannis.jpg","country":"Greece","description":"Greece's great layered casserole — spiced lamb mince with aubergine, topped with a thick béchamel that bakes to a golden custard-like cap. Rich and deeply satisfying.","prepTime":"40 mins","cookTime":"1 hr 20 mins","serves":8,"difficulty":"Medium","ingredients":[{"amount":"3 large","item":"aubergines, sliced into 1cm rounds"},{"amount":"800g","item":"lamb mince"},{"amount":"2","item":"onions, finely diced"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"400g","item":"tinned tomatoes"},{"amount":"1 tsp each","item":"ground cinnamon, allspice, nutmeg"},{"amount":"150ml","item":"red wine"},{"amount":"80g each","item":"unsalted butter and plain flour"},{"amount":"800ml","item":"full-fat milk"},{"amount":"3","item":"eggs, beaten"},{"amount":"100g","item":"Kefalotyri or Parmesan, grated"}],"steps":["Salt aubergine slices 30 minutes. Rinse, pat dry, fry in olive oil until golden both sides.","Brown lamb mince. Add onion and garlic. Cook until soft.","Add wine, tomatoes, purée and spices. Simmer 20 minutes until thick.","Make béchamel: melt butter, stir in flour, gradually whisk in milk until smooth and thick. Cool slightly, beat in eggs and half the cheese.","Layer baking dish: aubergine, meat sauce, aubergine, meat sauce. Pour béchamel over. Scatter remaining cheese.","Bake 180°C for 45-50 minutes until deeply golden. Rest 20 minutes before cutting."],"tip":"The resting time is essential — moussaka needs to set before cutting or it will collapse. It actually tastes better the next day.","story":"Moussaka was codified in its modern form by chef Nikolaos Tselementes in the 1920s, who added the French béchamel topping to the existing Levantine layered aubergine dish."},
"Baklava":{"name":"Baklava","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Baklava_-_Turkish_special%2C_80-ply.JPEG/800px-Baklava_-_Turkish_special%2C_80-ply.JPEG","country":"Greece","description":"Crispy layers of filo pastry filled with chopped walnuts, drenched in honey and rose water syrup. A labour of love and one of the world's great sweet pastries.","prepTime":"45 mins","cookTime":"45 mins","serves":24,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"filo pastry sheets"},{"amount":"200g","item":"unsalted butter, melted"},{"amount":"400g","item":"walnuts, finely chopped"},{"amount":"2 tsp","item":"ground cinnamon"},{"amount":"300g","item":"caster sugar"},{"amount":"200ml","item":"water"},{"amount":"200g","item":"honey"},{"amount":"2 tbsp","item":"rose water"},{"amount":"1","item":"lemon, juice only"}],"steps":["Mix chopped walnuts with cinnamon.","Butter a baking dish. Layer 8 sheets of filo, brushing each with melted butter.","Spread a third of the walnut mixture. Add 4 more buttered filo sheets. Repeat twice. Finish with 8 buttered sheets on top.","Cut into diamonds before baking. Bake at 180°C for 40-45 minutes until deep golden.","Meanwhile make syrup: dissolve sugar in water, add honey, lemon juice and rose water. Simmer 10 minutes.","Pour hot syrup over hot baklava immediately from the oven. Leave to soak at least 4 hours before serving."],"tip":"Pour hot syrup over hot baklava — the temperature difference is what makes it perfectly crispy rather than soggy. Never pour cold syrup over hot or hot over cold.","story":"Baklava's origins are disputed between Greece, Turkey, Lebanon and the Levant. Its current form was refined in the kitchens of the Ottoman Imperial palace in Constantinople."},
"Kung Pao Chicken":{"name":"Kung Pao Chicken","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Kung-pao-2.jpg/800px-Kung-pao-2.jpg","country":"China","description":"A Sichuan classic of tender chicken with dried chillies, peanuts and the tongue-numbing tingle of Sichuan peppercorns. Sweet, sour, spicy and savoury all at once.","prepTime":"20 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"chicken breast, cut into 2cm cubes"},{"amount":"100g","item":"roasted peanuts"},{"amount":"8-10","item":"dried red chillies"},{"amount":"2 tsp","item":"Sichuan peppercorns"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"2 tsp","item":"fresh ginger, minced"},{"amount":"4","item":"spring onions, sliced"},{"amount":"2 tbsp","item":"soy sauce"},{"amount":"2 tbsp","item":"Shaoxing rice wine"},{"amount":"1 tbsp","item":"rice vinegar"},{"amount":"2 tsp each","item":"sugar and sesame oil"},{"amount":"2 tsp","item":"cornflour"}],"steps":["Marinate chicken in 1 tbsp soy sauce, 1 tbsp Shaoxing wine and cornflour for 15 minutes.","Mix remaining soy sauce, rice wine, vinegar, sugar and sesame oil into a sauce.","Heat wok over highest heat. Stir-fry dried chillies and Sichuan peppercorns in oil 30 seconds until fragrant.","Add chicken and stir-fry 3 minutes. Add garlic and ginger, stir 30 seconds.","Pour in sauce and toss to coat. Cook 2 minutes.","Add peanuts and spring onions. Toss and serve with steamed rice."],"tip":"Toast the Sichuan peppercorns briefly before using. The tingling numbing sensation on the tongue is called 'ma' — the defining characteristic of Sichuan cuisine.","story":"Named after Ding Baozhen, a Qing Dynasty official given the title Gong Bao, this dish nearly disappeared during the Cultural Revolution when it was deemed an élitist name."},
"Peking Duck":{"name":"Peking Duck","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Peking_duck_-_melbourne.jpg/800px-Peking_duck_-_melbourne.jpg","country":"China","description":"China's most celebrated banquet dish — lacquered duck roasted until the skin is paper-crisp, carved tableside and wrapped in thin pancakes with cucumber and hoisin sauce.","prepTime":"30 mins","cookTime":"1 hr 30 mins","serves":4,"difficulty":"Hard","ingredients":[{"amount":"1","item":"whole duck (about 2kg)"},{"amount":"3 tbsp","item":"maltose or honey"},{"amount":"2 tbsp","item":"soy sauce"},{"amount":"1 tbsp","item":"Shaoxing rice wine"},{"amount":"1 tsp","item":"five spice powder"},{"amount":"20","item":"Chinese pancakes (shop-bought or homemade)"},{"amount":"1","item":"cucumber, cut into thin matchsticks"},{"amount":"6","item":"spring onions, cut into thin strips"},{"amount":"hoisin sauce","item":"to serve"}],"steps":["Air-dry the duck: pat completely dry, place on a rack uncovered in the fridge for at least 24 hours. The skin must be completely dry.","Mix maltose, soy sauce, Shaoxing wine and five spice. Brush all over the duck.","Roast at 200°C for 30 minutes. Reduce to 180°C and roast a further 50-60 minutes until deep mahogany and crispy.","Rest 10 minutes. Carve the skin off in pieces, then slice the meat separately.","Warm pancakes by steaming briefly.","Assemble: spread hoisin on a pancake, add a piece of crispy skin, some duck meat, cucumber and spring onion. Roll and eat."],"tip":"The 24-hour air-drying is non-negotiable. It is what creates the paper-thin crispy skin. Any moisture in the skin and you'll get a soft, flabby result.","story":"Peking Duck has been prepared in Beijing since the imperial era of the Yuan Dynasty in the 14th century. Imperial chefs refined the technique over centuries in the Forbidden City."},
"Lamb Tagine":{"name":"Lamb Tagine with Preserved Lemon","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Tajine_de_poulet.jpg/800px-Tajine_de_poulet.jpg","country":"Morocco","description":"A fragrant slow braise of lamb with warming spices, preserved lemon and olives. The conical tagine lid traps steam and returns it as condensation, keeping the meat impossibly tender.","prepTime":"20 mins","cookTime":"2 hrs 30 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"1.2kg","item":"lamb shoulder, cut into chunks"},{"amount":"2","item":"preserved lemons, flesh removed, skin sliced"},{"amount":"150g","item":"green olives, pitted"},{"amount":"2","item":"onions, finely sliced"},{"amount":"4","item":"garlic cloves, crushed"},{"amount":"2 tsp each","item":"ground cumin, ground coriander"},{"amount":"1 tsp each","item":"ground ginger, turmeric, sweet paprika"},{"amount":"1/2 tsp","item":"ground cinnamon"},{"amount":"small bunch each","item":"fresh coriander and parsley"},{"amount":"3 tbsp","item":"olive oil"}],"steps":["Mix all spices. Coat lamb and season.","Brown lamb in batches in a tagine or heavy casserole. Set aside.","Soften onions and garlic in same pot 10 minutes.","Return lamb. Add 300ml water. Simmer covered on lowest heat for 2 hours.","Add preserved lemon skin and olives. Cook uncovered 20 minutes to reduce the sauce.","Stir in fresh coriander and parsley. Serve with couscous or flatbread."],"tip":"Preserved lemon is non-negotiable — the fermented citrus flavour is completely different from fresh lemon juice and defines the dish.","story":"Tagine cooking dates back to the Berber nomads of North Africa, who used the conical clay vessel over campfires as both a cooking pot and serving dish."},
"Harira":{"name":"Harira","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Harira_soup.jpg/800px-Harira_soup.jpg","country":"Morocco","description":"Morocco's warming soup of tomatoes, lentils, chickpeas and lamb — spiced with ginger, turmeric and cinnamon. Traditionally served to break the fast during Ramadan.","prepTime":"20 mins","cookTime":"1 hr","serves":8,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"lamb shoulder, cut into small pieces"},{"amount":"200g","item":"brown lentils"},{"amount":"400g","item":"tinned chickpeas, drained"},{"amount":"400g","item":"tinned tomatoes"},{"amount":"2","item":"large onions, finely diced"},{"amount":"3","item":"celery stalks, finely chopped"},{"amount":"1 tsp each","item":"ground ginger, turmeric, cinnamon, black pepper"},{"amount":"small bunch","item":"fresh coriander and parsley, chopped"},{"amount":"juice of 1","item":"lemon"},{"amount":"2 tbsp","item":"plain flour mixed with water to a paste"}],"steps":["Brown lamb pieces in a large pot. Add onions and celery and cook until soft.","Add all spices and stir 1 minute. Add tomatoes, lentils, chickpeas and 1.5L water.","Bring to boil. Simmer covered for 45 minutes until lentils are completely soft.","Stir in flour paste to thicken. Simmer 10 minutes, stirring frequently.","Add fresh coriander, parsley and lemon juice. Taste and adjust seasoning.","Serve with dates, honey and Moroccan bread on the side."],"tip":"The flour-water paste added at the end is the traditional thickening method that gives harira its distinctive silky consistency. Don't skip it.","story":"Harira is Morocco's most beloved soup, served throughout the year but especially during Ramadan when a bowl of harira traditionally marks the breaking of the daily fast."},
"Pho Bo":{"name":"Pho Bo","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Pho_bo_2.jpg/800px-Pho_bo_2.jpg","country":"Vietnam","description":"Vietnam's iconic beef noodle soup — a crystal-clear broth perfumed with charred ginger and star anise, with silky rice noodles and paper-thin beef that cooks in the bowl.","prepTime":"30 mins","cookTime":"4 hrs","serves":6,"difficulty":"Hard","ingredients":[{"amount":"2kg","item":"beef bones (knuckle and marrow)"},{"amount":"500g","item":"beef brisket"},{"amount":"300g","item":"beef sirloin, very thinly sliced"},{"amount":"400g","item":"flat rice noodles"},{"amount":"1 large","item":"onion, halved"},{"amount":"1 large piece","item":"fresh ginger, halved lengthways"},{"amount":"3","item":"star anise"},{"amount":"1","item":"cinnamon stick"},{"amount":"3 tbsp","item":"fish sauce"},{"amount":"bean sprouts, Thai basil, lime, chilli","item":"to serve"}],"steps":["Blanch bones and brisket in boiling water 5 minutes. Drain, rinse, return to pot with cold water.","Char onion and ginger directly over gas flame or under grill until blackened. Toast spices in dry pan.","Add charred aromatics and spices to broth. Simmer uncovered 3-4 hours, skimming regularly. Remove brisket after 1 hour, slice thinly.","Strain broth through fine sieve. Season with fish sauce until perfectly balanced.","Cook noodles, drain and divide between bowls. Add brisket slices and raw sirloin on top.","Ladle boiling broth over — it cooks the sirloin instantly. Serve with bean sprouts, basil, lime and chilli."],"tip":"The charring of ginger and onion is what gives pho its distinctive smoky-sweet depth. This step is what separates great pho from good pho.","story":"Pho originated in northern Vietnam in the early 20th century, likely influenced by French pot-au-feu and Chinese beef noodle soups brought by migrant workers to Hanoi."},
"Bibimbap":{"name":"Bibimbap","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Dolsot-bibimbap.jpg/800px-Dolsot-bibimbap.jpg","country":"South Korea","description":"The harmony bowl — steamed rice with seasoned vegetables, gochujang, sesame oil and a fried egg. Mixed together at the table in a ritual that gives the dish its name.","prepTime":"40 mins","cookTime":"20 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"short-grain white rice, cooked"},{"amount":"4","item":"eggs"},{"amount":"200g","item":"beef mince, seasoned with soy and sesame"},{"amount":"2 tbsp","item":"gochujang (Korean chilli paste)"},{"amount":"200g each","item":"spinach, bean sprouts, shiitake mushrooms"},{"amount":"2 each","item":"carrots and courgettes, julienned"},{"amount":"4 tbsp","item":"sesame oil"},{"amount":"2 tsp","item":"toasted sesame seeds"},{"amount":"2","item":"garlic cloves, minced"}],"steps":["Season beef mince with soy sauce and sesame oil. Fry until cooked.","Blanch spinach and bean sprouts separately 1 minute. Squeeze dry. Season each with sesame oil, soy sauce and garlic.","Stir-fry carrots, courgettes and mushrooms separately in sesame oil, seasoning each lightly.","Fry eggs sunny side up.","Divide rice between bowls. Arrange each vegetable, beef and egg in separate sections.","Place a spoonful of gochujang mixed with sesame oil in the centre. Mix vigorously at the table before eating."],"tip":"Mix everything thoroughly — the joy of bibimbap is in the mixing. Don't be half-hearted. Mix until the egg yolk coats the rice and the gochujang is fully distributed.","story":"Bibimbap's origins are traced to the Korean practice of mixing leftover side dishes with rice at the end of new year's eve to ensure no food was wasted."},
"Feijoada":{"name":"Feijoada","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Feijoada_-_Ronaldo_Caiafa.jpg/800px-Feijoada_-_Ronaldo_Caiafa.jpg","country":"Brazil","description":"Brazil's soul food — a slow-cooked stew of black beans with multiple pork cuts. Saturday's communal ritual, served with rice, crispy farofa and orange slices.","prepTime":"30 mins","cookTime":"3 hrs","serves":8,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"dried black beans, soaked overnight"},{"amount":"300g","item":"smoked pork sausage (linguiça), sliced"},{"amount":"200g","item":"bacon, in one piece"},{"amount":"300g","item":"pork ribs"},{"amount":"200g","item":"salted beef (carne seca), soaked and rinsed"},{"amount":"2","item":"onions, finely diced"},{"amount":"6","item":"garlic cloves, minced"},{"amount":"2","item":"bay leaves"},{"amount":"4","item":"oranges, sliced (to serve)"},{"amount":"200g","item":"farofa (to serve)"}],"steps":["Drain soaked beans. Cover with fresh water and simmer 30 minutes.","Render bacon in olive oil. Brown sausage and ribs. Add carne seca.","Add onion and garlic to meat. Cook until soft, then add to the beans with bay leaves.","Add water to cover by 5cm. Simmer covered on low heat 2-2.5 hours until beans are tender and broth is thick.","Taste and adjust salt. Serve over white rice with farofa and orange slices."],"tip":"The orange slices aren't just a garnish — eating a slice between bites cuts through the richness of the pork and beans, cleansing the palate.","story":"Feijoada developed from a blend of African and Portuguese cooking traditions. It is now considered Brazil's national dish and Saturday's feijoada is a sacred institution in Rio de Janeiro."},
"Beef Wellington":{"name":"Beef Wellington","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Beef_wellington.jpg/800px-Beef_wellington.jpg","country":"United Kingdom","description":"Britain's greatest showstopper — beef fillet coated in mushroom duxelles and wrapped in golden puff pastry. Sliced at the table to reveal a perfectly pink centre.","prepTime":"45 mins","cookTime":"35 mins","serves":6,"difficulty":"Hard","ingredients":[{"amount":"1kg","item":"beef fillet, centre cut, trimmed"},{"amount":"500g","item":"chestnut mushrooms"},{"amount":"4 slices","item":"Parma ham"},{"amount":"500g","item":"puff pastry"},{"amount":"2 tbsp","item":"Dijon mustard"},{"amount":"2","item":"egg yolks, beaten"},{"amount":"2","item":"shallots, finely diced"},{"amount":"2","item":"garlic cloves, minced"},{"amount":"2 tbsp each","item":"unsalted butter and olive oil"}],"steps":["Sear beef fillet in very hot olive oil on all sides until deeply browned, 3 minutes total. Brush with Dijon mustard. Cool completely.","Blitz mushrooms, shallots and garlic until fine. Cook in butter over high heat until all moisture has evaporated, about 15 minutes. Cool.","Lay a sheet of cling film. Arrange Parma ham in overlapping slices. Spread mushroom duxelles over ham. Place beef at edge and roll tightly. Refrigerate 30 minutes.","Unwrap beef. Place on rolled-out pastry. Wrap pastry around, sealing edges with egg yolk.","Brush all over with egg yolk. Score lightly. Refrigerate 15 minutes.","Bake at 220°C for 25-30 minutes until pastry is deep golden. Rest 10 minutes before slicing."],"tip":"Chilling the Wellington in cling film before wrapping in pastry is essential to help it hold its shape and ensure the pastry bakes evenly.","story":"Despite its patriotic name, Beef Wellington has disputed origins — some link it to the Duke of Wellington, others suggest it is simply a British take on the French filet de boeuf en croûte."},
"Fish and Chips":{"name":"Fish and Chips","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/800px-Fish_and_chips_blackpool.jpg","country":"United Kingdom","description":"Britain's great national dish — battered cod fried until shatteringly crisp, served with thick chips and malt vinegar. Simple, perfect, irreplaceable.","prepTime":"20 mins","cookTime":"25 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"4","item":"cod or haddock fillets (about 200g each)"},{"amount":"250g","item":"plain flour"},{"amount":"50g","item":"cornflour"},{"amount":"1 tsp","item":"baking powder"},{"amount":"300ml","item":"cold beer (lager or bitter)"},{"amount":"1kg","item":"Maris Piper potatoes, cut into thick chips"},{"amount":"oil","item":"for deep frying"},{"amount":"salt, malt vinegar and mushy peas","item":"to serve"}],"steps":["Parboil chips in salted water for 5 minutes. Drain and steam dry. Refrigerate to dry out further.","Make batter: whisk flour, cornflour and baking powder. Gradually whisk in cold beer until a thick batter forms. Refrigerate.","First fry chips at 150°C for 5 minutes until cooked but not coloured. Drain.","Season fish, dust with flour. Dip in cold batter, letting excess drip off.","Fry fish at 190°C for 5-6 minutes until deeply golden and batter is crisp. Drain.","Increase oil to 190°C, fry chips second time until golden and crispy, about 3 minutes. Season immediately with salt."],"tip":"The double frying of chips — once to cook, once to crisp — is the secret to chips that are fluffy inside and crispy outside rather than just greasy all the way through.","story":"Fish and chips became Britain's first takeaway in the 1860s, when fried fish shops (from Jewish immigrants) and chip shops (from Lancashire) combined. By WWI, there were over 35,000 shops."},
"Asado":{"name":"Asado","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Asado_en_Argentina.jpg/800px-Asado_en_Argentina.jpg","country":"Argentina","description":"Argentina's defining ritual — beef ribs, chorizo and morcilla cooked slowly over glowing embers on a parrilla grill, with chimichurri and red wine. Not just a meal — a ceremony.","prepTime":"30 mins","cookTime":"2 hrs","serves":8,"difficulty":"Medium","ingredients":[{"amount":"2kg","item":"beef short ribs (asado de tira)"},{"amount":"500g","item":"beef chorizo"},{"amount":"4","item":"morcilla (blood sausage)"},{"amount":"coarse sea salt","item":"only seasoning needed"},{"amount":"1 bunch","item":"flat-leaf parsley, finely chopped"},{"amount":"6","item":"garlic cloves, minced"},{"amount":"2 tsp each","item":"dried oregano and chilli flakes"},{"amount":"4 tbsp","item":"red wine vinegar"},{"amount":"6 tbsp","item":"olive oil"}],"steps":["Build a wood fire and let it burn to glowing coals — no flames. This takes 45 minutes.","Place ribs on the grill rack at medium height. Season only with coarse salt. Do not touch for 45 minutes.","Turn ribs once. Grill a further 45 minutes until charred outside and fat has rendered.","Add chorizo and morcilla in the final 20 minutes.","Make chimichurri: combine parsley, garlic, oregano, chilli flakes, vinegar and olive oil. Season.","Rest meat 10 minutes before serving with chimichurri alongside."],"tip":"The quality of the fire is everything. Asado requires patience and good coals — rushing it over too-hot flame produces tough, dry meat. Low, steady heat wins.","story":"Asado has its roots in the gauchos of the Pampas grasslands who cooked beef over open fires in the 17th-19th centuries. Today it is the central ritual of Argentine social life."},
"Osso Buco":{"name":"Osso Buco","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/OssoBuco.jpg/800px-OssoBuco.jpg","country":"Italy","description":"Milan's signature braised veal shanks — slow-cooked until fall-off-the-bone tender, finished with bright gremolata of lemon zest, garlic and parsley.","prepTime":"20 mins","cookTime":"2 hrs","serves":4,"difficulty":"Medium","ingredients":[{"amount":"4","item":"veal shanks, tied with string"},{"amount":"2","item":"carrots, diced"},{"amount":"2","item":"celery stalks, diced"},{"amount":"1 large","item":"onion, diced"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"200ml","item":"dry white wine"},{"amount":"400g","item":"tinned tomatoes"},{"amount":"300ml","item":"beef stock"},{"amount":"zest of 1","item":"lemon"},{"amount":"small bunch","item":"flat-leaf parsley, chopped"}],"steps":["Season veal shanks and brown on all sides in olive oil over high heat. Remove.","Soften carrots, celery and onion in same pan 10 minutes. Add garlic, cook 2 more minutes.","Pour in wine and reduce by half. Add tomatoes and stock. Return veal.","Cover and braise over lowest heat for 1.5-2 hours until meat is very tender.","Mix lemon zest and parsley for gremolata. Spoon over just before serving.","Serve with saffron risotto or polenta."],"tip":"The string keeps the meat attached to the bone during cooking. Remove before serving.","story":"Osso buco means bone with a hole — the hollow marrow bone is the prized part, traditionally scooped out and eaten on bread."},
"Pizza Margherita":{"name":"Pizza Margherita","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Eq_it-na_pizza-margherita_sep2005_sml.jpg/800px-Eq_it-na_pizza-margherita_sep2005_sml.jpg","country":"Italy","description":"The original Neapolitan pizza — a thin charred crust with San Marzano tomatoes, buffalo mozzarella and fresh basil. Three colours of the Italian flag.","prepTime":"30 mins","cookTime":"10 mins","serves":2,"difficulty":"Medium","ingredients":[{"amount":"300g","item":"strong white bread flour"},{"amount":"7g","item":"fast-action yeast"},{"amount":"1 tsp","item":"salt"},{"amount":"200ml","item":"warm water"},{"amount":"2 tbsp","item":"olive oil"},{"amount":"200g","item":"tinned San Marzano tomatoes, crushed"},{"amount":"200g","item":"buffalo mozzarella, torn"},{"amount":"handful","item":"fresh basil leaves"}],"steps":["Mix flour, yeast and salt. Add water and oil. Knead 10 minutes until smooth. Prove 1 hour.","Preheat oven to maximum with a baking stone inside for 30 minutes.","Stretch dough into thin rounds. Spread tomatoes thinly, leaving border.","Bake 8-10 minutes until crust is charred at edges. Add mozzarella in last 2 minutes.","Top with basil and a drizzle of olive oil. Serve immediately."],"tip":"The hottest possible oven is essential. A baking stone preheated for 30 minutes is the closest to a wood-fired oven you can get at home.","story":"Pizza Margherita was created in 1889 for Queen Margherita of Savoy, garnished in the red, white and green of the Italian flag."},
"Ribollita":{"name":"Ribollita","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Ribollita_Caff%C3%A8_Borghini.jpg/800px-Ribollita_Caff%C3%A8_Borghini.jpg","country":"Italy","description":"Tuscany's famous re-boiled soup — cavolo nero, cannellini beans and stale bread slow-cooked into a thick, deeply warming winter stew.","prepTime":"20 mins","cookTime":"1 hr 30 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"tinned cannellini beans"},{"amount":"200g","item":"cavolo nero, shredded"},{"amount":"2","item":"carrots, diced"},{"amount":"2","item":"celery stalks, diced"},{"amount":"1 large","item":"onion, diced"},{"amount":"400g","item":"tinned tomatoes"},{"amount":"4 thick slices","item":"stale crusty bread"},{"amount":"1L","item":"vegetable stock"}],"steps":["Soften onion, carrots and celery in olive oil 10 minutes.","Add tomatoes and stock. Simmer 20 minutes.","Add cavolo nero. Simmer 30 more minutes.","Mash half the beans, add all beans. Stir in torn bread.","Simmer 15 minutes until bread dissolves and soup is very thick.","Rest 10 minutes. Serve with a generous pour of best olive oil."],"tip":"Ribollita means re-boiled — it tastes even better the next day reheated.","story":"A Florentine peasant dish born from necessity, ribollita was originally made by re-boiling leftover minestrone with stale bread."},
"Coq au Vin":{"name":"Coq au Vin","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Coq_au_vin.jpg/800px-Coq_au_vin.jpg","country":"France","description":"The great French chicken braise — slowly cooked in red Burgundy wine with lardons, mushrooms and pearl onions until impossibly tender.","prepTime":"30 mins","cookTime":"1 hr 30 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1.5kg","item":"chicken pieces, bone-in"},{"amount":"750ml","item":"Burgundy red wine"},{"amount":"200g","item":"lardons"},{"amount":"200g","item":"chestnut mushrooms, quartered"},{"amount":"200g","item":"pearl onions"},{"amount":"4","item":"garlic cloves, crushed"},{"amount":"2 tbsp","item":"plain flour"},{"amount":"30ml","item":"brandy"}],"steps":["Brown chicken in batches. Remove.","Fry lardons and pearl onions until golden.","Return chicken. Add brandy. Stir in flour.","Pour over wine. Add garlic, bay, thyme. Cover and simmer 1 hour.","Add mushrooms in last 20 minutes. Season and serve."],"tip":"Make it the day before — coq au vin always improves overnight.","story":"Originally made with old roosters too tough to roast, the long wine braise transformed them into something magnificent."},
"Tortilla Española":{"name":"Tortilla Española","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Tortilla_de_patata.jpg/800px-Tortilla_de_patata.jpg","country":"Spain","description":"Spain's most essential dish — a thick, tender potato and onion omelette, gently cooked until just set in the centre. Found on every bar counter from breakfast until midnight.","prepTime":"15 mins","cookTime":"30 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"600g","item":"waxy potatoes, thinly sliced"},{"amount":"1 large","item":"onion, thinly sliced"},{"amount":"6 large","item":"eggs"},{"amount":"150ml","item":"olive oil"},{"amount":"1 tsp","item":"salt"}],"steps":["Heat olive oil. Cook potatoes and onion over medium-low 20 minutes until tender.","Drain, reserving oil. Beat eggs, add potato mixture, rest 5 minutes.","Heat 2 tbsp oil in pan. Pour in mixture. Cook 5-6 minutes until edges set.","Flip using a plate. Cook 3-4 more minutes. Centre should wobble slightly."],"tip":"Flip confidently — hesitation causes disaster.","story":"Legend says it was invented in the 19th century during sieges when potatoes were stretched with eggs to feed more mouths."},
"Patatas Bravas":{"name":"Patatas Bravas","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Patates_braves.jpg/800px-Patates_braves.jpg","country":"Spain","description":"Spain's most beloved tapa — crispy fried potato cubes served with a fiery brava sauce and creamy alioli.","prepTime":"15 mins","cookTime":"25 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"floury potatoes, cut into chunks"},{"amount":"oil","item":"for frying"},{"amount":"1 tsp","item":"smoked paprika"},{"amount":"half tsp","item":"cayenne"},{"amount":"200g","item":"tinned tomatoes, blended"},{"amount":"4 tbsp","item":"mayonnaise"},{"amount":"1","item":"garlic clove, crushed"}],"steps":["Par-boil potatoes 8 minutes. Drain and steam dry.","Deep fry at 180C until golden and crispy. Drain. Season.","Make brava sauce: fry onion and garlic, add paprika, cayenne and tomatoes. Simmer 15 minutes.","Make alioli: mix mayonnaise with garlic and lemon juice.","Serve hot potatoes with brava sauce and alioli."],"tip":"Completely drying the par-boiled potatoes before frying is essential for crispiness.","story":"The name means fierce potatoes — a reference to the fiery sauce."},
"Churros":{"name":"Churros","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Churro_-_3.jpg/800px-Churro_-_3.jpg","country":"Spain","description":"Spain's iconic fried dough — crisp ridged sticks dusted with cinnamon sugar, served with thick hot chocolate for dunking.","prepTime":"10 mins","cookTime":"20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"250ml","item":"water"},{"amount":"125g","item":"plain flour"},{"amount":"pinch","item":"salt"},{"amount":"oil","item":"for frying"},{"amount":"4 tbsp","item":"caster sugar"},{"amount":"1 tsp","item":"ground cinnamon"},{"amount":"200g","item":"dark chocolate"},{"amount":"250ml","item":"whole milk"}],"steps":["Bring water and salt to boil. Beat in flour until smooth dough forms.","Pipe through star nozzle into 15cm lengths. Fry at 180C until golden.","Toss hot churros in cinnamon sugar.","Melt chocolate with milk, thickened with cornflour.","Serve immediately with chocolate for dunking."],"tip":"The star-shaped nozzle gives ridges that maximise crispiness per bite.","story":"Churros were brought to Spain by Portuguese sailors who encountered similar fried dough in China."},
"Mapo Tofu":{"name":"Mapo Tofu","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Mabo_doufu_%28Mapo_tofu%29_by_Jeremy_Keith_in_Osaka.jpg/800px-Mabo_doufu_%28Mapo_tofu%29_by_Jeremy_Keith_in_Osaka.jpg","country":"China","description":"Sichuan's most electric dish — silken tofu and minced pork in a fiery doubanjiang sauce, leaving lips tingling with the characteristic ma la sensation.","prepTime":"10 mins","cookTime":"20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"silken tofu, cubed"},{"amount":"200g","item":"pork mince"},{"amount":"2 tbsp","item":"doubanjiang"},{"amount":"3","item":"garlic cloves, minced"},{"amount":"2 tsp","item":"Sichuan peppercorns, toasted and ground"},{"amount":"300ml","item":"chicken stock"},{"amount":"1 tbsp","item":"cornflour in 2 tbsp water"}],"steps":["Blanch tofu in salted water 1 minute. Drain.","Fry pork until browned. Add doubanjiang and garlic.","Pour in stock. Bring to boil. Slide in tofu gently. Simmer 3 minutes.","Thicken with cornflour. Finish with Sichuan pepper."],"tip":"Handle silken tofu with extreme care — it breaks easily.","story":"Named after a pock-faced elderly woman who supposedly invented it in a Chengdu restaurant in the 19th century."},
"Sweet and Sour Pork":{"name":"Sweet and Sour Pork","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Sweet_and_sour_pork.jpg/800px-Sweet_and_sour_pork.jpg","country":"China","description":"Cantonese cooking at its most satisfying — crispy battered pork with peppers and pineapple in a glossy perfectly balanced sweet-sour sauce.","prepTime":"20 mins","cookTime":"20 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"pork shoulder, cubed"},{"amount":"1","item":"egg"},{"amount":"4 tbsp","item":"cornflour"},{"amount":"1 each","item":"red and green pepper"},{"amount":"200g","item":"pineapple chunks"},{"amount":"3 tbsp","item":"rice vinegar"},{"amount":"3 tbsp","item":"ketchup"},{"amount":"3 tbsp","item":"caster sugar"}],"steps":["Coat pork in egg and cornflour. Deep fry until golden.","Stir-fry peppers over high heat.","Mix vinegar, ketchup and sugar for sauce. Add to wok and reduce.","Add pineapple and fried pork. Toss to coat. Serve with rice."],"tip":"Fry the pork twice for maximum crispiness.","story":"Originated in Guangdong province and became one of the first Chinese dishes popular in the West."},
"Couscous Royal":{"name":"Couscous Royal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Couscous_de_Poulet.jpg/800px-Couscous_de_Poulet.jpg","country":"Morocco","description":"The grandest version of Morocco's national dish — fluffy steamed couscous above fragrant lamb, chicken, merguez and vegetables. A Friday celebration.","prepTime":"30 mins","cookTime":"1 hr 30 mins","serves":8,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"couscous"},{"amount":"600g","item":"lamb shoulder, cubed"},{"amount":"4","item":"merguez sausages"},{"amount":"2 each","item":"carrots, courgettes, turnips"},{"amount":"400g","item":"tinned chickpeas"},{"amount":"1 tsp each","item":"ginger, turmeric, cinnamon, cumin"}],"steps":["Brown lamb and simmer with spices and vegetables.","Steam couscous in a couscoussier over the broth for 20 minutes.","Remove, break up with oil and water, steam again 15 minutes.","Grill merguez separately until charred.","Mound couscous and arrange meat and vegetables over."],"tip":"Double steaming couscous above the broth gives incomparably light fluffy texture.","story":"Couscous is the national dish of Morocco, Algeria and Tunisia and has been made in North Africa for 800 years."},
"Pastilla":{"name":"Pastilla","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Pastilla.jpg/800px-Pastilla.jpg","country":"Morocco","description":"Morocco's extraordinary sweet-savoury pie — spiced pigeon or chicken with eggs and almonds wrapped in crisp warqa pastry, dusted with cinnamon sugar. A dish of pure theatre.","prepTime":"45 mins","cookTime":"1 hr","serves":8,"difficulty":"Hard","ingredients":[{"amount":"1 whole","item":"chicken or 2 pigeons"},{"amount":"2 large","item":"onions, grated"},{"amount":"1 tsp each","item":"ground ginger, cinnamon, saffron"},{"amount":"small bunch","item":"fresh coriander and parsley"},{"amount":"6","item":"eggs, beaten"},{"amount":"150g","item":"blanched almonds, toasted and roughly ground"},{"amount":"4 tbsp","item":"icing sugar"},{"amount":"2 tsp","item":"ground cinnamon (for dusting)"},{"amount":"12 sheets","item":"brick pastry or filo"},{"amount":"100g","item":"butter, melted"}],"steps":["Poach chicken or pigeon with onion, spices and herbs until very tender. Remove and shred meat.","Reduce cooking liquid. Add beaten eggs and scramble gently into the sauce. Cool.","Layer 6 buttered pastry sheets in a round tin. Add egg mixture, then meat, then almonds mixed with sugar and cinnamon.","Fold over pastry and top with remaining sheets, tucking in edges.","Brush with butter. Bake at 200C until deep golden.","Dust with icing sugar and draw a cinnamon lattice pattern."],"tip":"The contrast of sweet icing sugar dusting over savoury spiced meat is the defining characteristic — do not skip it.","story":"Pastilla is served at the most important Moroccan celebrations. It was originally made with pigeon in Fez and remains one of the most technically demanding dishes in Moroccan cuisine."},
"Spanakopita":{"name":"Spanakopita","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Spanakopita_%28Greek_spinach_pie%29.jpg/800px-Spanakopita_%28Greek_spinach_pie%29.jpg","country":"Greece","description":"Greece's iconic spinach and feta pie — layers of crisp buttered filo encasing a fragrant filling of wilted spinach, crumbled feta and dill.","prepTime":"30 mins","cookTime":"45 mins","serves":8,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"fresh spinach, wilted and squeezed dry"},{"amount":"300g","item":"feta cheese, crumbled"},{"amount":"2","item":"eggs, beaten"},{"amount":"1 large","item":"onion, diced"},{"amount":"bunch","item":"fresh dill and parsley"},{"amount":"12 sheets","item":"filo pastry"},{"amount":"100ml","item":"olive oil"}],"steps":["Wilt spinach, cool and squeeze out all water. Mix with feta, eggs, onion and herbs.","Brush dish with oil. Lay 6 oiled filo sheets, edges hanging over.","Spread filling. Fold edges over. Layer remaining filo on top, oiling each sheet.","Score top into diamonds. Bake 180C 40-45 minutes until deep golden.","Rest 10 minutes before cutting."],"tip":"Squeezing every drop of water from the spinach is non-negotiable.","story":"Spanakopita appears throughout Greek history — spinach pies were offered to the gods at Olympia."},
"Souvlaki":{"name":"Souvlaki","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Souvlaki_-_Athens.jpg/800px-Souvlaki_-_Athens.jpg","country":"Greece","description":"Greece's greatest street food — marinated pork on skewers grilled over charcoal until slightly charred. Served with pitta, tomatoes and tzatziki.","prepTime":"20 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"pork neck, cut into 3cm cubes"},{"amount":"juice of 2","item":"lemons"},{"amount":"4 tbsp","item":"olive oil"},{"amount":"2 tsp","item":"dried oregano"},{"amount":"4","item":"pitta breads"},{"amount":"tzatziki","item":"to serve"}],"steps":["Marinate pork in lemon, oil and oregano at least 2 hours.","Thread onto skewers. Grill over high heat 8-10 minutes, turning regularly.","Warm pittas briefly on the grill.","Serve with pitta, tomatoes, onion and generous tzatziki."],"tip":"Pork neck stays juicy on the grill — lean loin will dry out.","story":"Souvlaki has been eaten in Greece since antiquity — evidence of ancient barbecue stones dates to 1600 BCE."},
"Tzatziki":{"name":"Tzatziki","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Tzatziki_with_pita_and_olives.jpg/800px-Tzatziki_with_pita_and_olives.jpg","country":"Greece","description":"Greece's cooling cucumber and yoghurt dip — strained yoghurt with grated cucumber, garlic and dill. The essential companion to souvlaki and mezze.","prepTime":"15 mins","cookTime":"0 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"full-fat Greek yoghurt"},{"amount":"1 large","item":"cucumber"},{"amount":"2-3","item":"garlic cloves, finely grated"},{"amount":"2 tbsp","item":"fresh dill"},{"amount":"2 tbsp","item":"extra virgin olive oil"},{"amount":"1 tbsp","item":"white wine vinegar"}],"steps":["Grate cucumber and squeeze out all water in a cloth.","Mix with yoghurt, garlic, dill, oil and vinegar.","Season generously with salt. Refrigerate 30 minutes.","Serve drizzled with olive oil."],"tip":"Straining the cucumber twice is the most important step — wet cucumber makes watery tzatziki immediately.","story":"Derives from the Turkish word cacik — Greeks and Turks each believe theirs is the original version."},
"Horiatiki Salad":{"name":"Horiatiki Salad","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Greek_salad.jpg/800px-Greek_salad.jpg","country":"Greece","description":"The Greek village salad — ripe tomatoes, cucumber, peppers and Kalamata olives with a whole block of feta and nothing but olive oil. No lettuce, ever.","prepTime":"10 mins","cookTime":"0 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4 large","item":"ripe tomatoes, wedged"},{"amount":"1 large","item":"cucumber, chunked"},{"amount":"1","item":"green pepper, sliced"},{"amount":"1 small","item":"red onion, thinly sliced"},{"amount":"12","item":"Kalamata olives"},{"amount":"200g","item":"block of Greek feta"},{"amount":"1 tsp","item":"dried oregano"},{"amount":"4 tbsp","item":"extra virgin olive oil"}],"steps":["Arrange tomatoes, cucumber, pepper and onion in a wide bowl.","Place feta block whole on top — do not crumble.","Scatter olives. Sprinkle oregano over feta. Pour olive oil generously over.","Serve with crusty bread."],"tip":"Use the ripest tomatoes and best feta available — this salad has nowhere to hide.","story":"Horiatiki means village-style. The international Greek salad with lettuce is not how it is eaten in Greece."},
"Churrasco":{"name":"Churrasco","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Churrasco_brasileiro.jpg/800px-Churrasco_brasileiro.jpg","country":"Brazil","description":"Brazil's legendary rotating-spit barbecue — picanha cooked over hot coals and carved tableside in long spiralling slices. The ultimate expression of Brazilian hospitality.","prepTime":"15 mins","cookTime":"30 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1.5kg","item":"picanha (top sirloin cap) with fat cap"},{"amount":"coarse sea salt","item":"only seasoning"}],"steps":["Score fat cap in a crosshatch. Season extremely generously with coarse salt.","Thread onto large skewer in a C-shape with fat cap outward.","Cook over hot charcoal rotating constantly for 20-25 minutes.","When fat is golden and crackling, slice off outer layers onto plates.","Return to fire and continue slicing as it cooks."],"tip":"The picanha fat layer must remain during cooking — it renders into the meat giving extraordinary flavour.","story":"Churrasco dates to the gauchos of the Brazilian Pampas who cooked meat over open fires while driving cattle in the 17th century."},
"Moqueca":{"name":"Moqueca","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Moqueca_baiana.jpg/800px-Moqueca_baiana.jpg","country":"Brazil","description":"Brazil's fragrant fish stew — firm white fish simmered in coconut milk with tomatoes, peppers and dendê palm oil. The flavour of coastal Bahia.","prepTime":"20 mins","cookTime":"25 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"firm white fish fillets (sea bass or cod)"},{"amount":"400ml","item":"coconut milk"},{"amount":"2","item":"tomatoes, sliced"},{"amount":"1 large","item":"onion, sliced"},{"amount":"1","item":"red pepper, sliced"},{"amount":"1","item":"green pepper, sliced"},{"amount":"2 tbsp","item":"dendê (palm oil) or annatto oil"},{"amount":"bunch","item":"fresh coriander"},{"amount":"juice of 2","item":"limes"}],"steps":["Marinate fish with lime juice, garlic and salt for 20 minutes.","In a clay pot or wide pan, layer onion, tomatoes and peppers.","Add fish. Pour coconut milk over. Drizzle with dendê oil.","Simmer covered 20 minutes until fish is just cooked.","Scatter coriander. Serve with white rice and farofa."],"tip":"Dendê (palm oil) gives moqueca its characteristic orange colour and unique flavour — it cannot be substituted.","story":"Moqueca is Brazil's oldest documented recipe, first recorded in 1648. The Bahian version with coconut milk and dendê reflects West African culinary influence."},
"Pão de Queijo":{"name":"Pão de Queijo","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Pao-de-queijo.jpg/800px-Pao-de-queijo.jpg","country":"Brazil","description":"Brazil's addictive cheese bread — puffy, chewy balls of tapioca starch and queijo minas, crisp outside and molten-centred within. Impossible to eat just one.","prepTime":"15 mins","cookTime":"25 mins","serves":24,"difficulty":"Easy","ingredients":[{"amount":"250ml","item":"whole milk"},{"amount":"125ml","item":"vegetable oil"},{"amount":"1 tsp","item":"salt"},{"amount":"300g","item":"tapioca starch (polvilho azedo or doce)"},{"amount":"2","item":"eggs"},{"amount":"200g","item":"queijo minas or mature cheddar, grated"}],"steps":["Heat milk, oil and salt until just boiling. Pour over tapioca starch. Mix well.","Cool 10 minutes. Beat in eggs one at a time.","Add cheese. Mix until a sticky dough forms.","Roll into walnut-sized balls with oiled hands.","Bake at 200C for 20-25 minutes until puffed and golden.","Eat warm — they deflate as they cool."],"tip":"Eat straight from the oven for the best molten cheese pull inside.","story":"Pão de queijo originated in Minas Gerais in the 18th century when slaves used tapioca starch (a byproduct of cassava processing) to make bread."},
"Brigadeiro":{"name":"Brigadeiro","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Brigadeiro_bem_casado.jpg/800px-Brigadeiro_bem_casado.jpg","country":"Brazil","description":"Brazil's national sweet — condensed milk chocolate truffles rolled in chocolate sprinkles. Found at every Brazilian birthday, celebration and churrasqueria.","prepTime":"10 mins","cookTime":"15 mins","serves":30,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"sweetened condensed milk"},{"amount":"3 tbsp","item":"cocoa powder"},{"amount":"1 tbsp","item":"butter"},{"amount":"pinch","item":"salt"},{"amount":"chocolate sprinkles","item":"for rolling"}],"steps":["Combine condensed milk, cocoa, butter and salt in a non-stick pan.","Cook over medium heat, stirring constantly, until mixture thickens and pulls away from sides, about 10-15 minutes.","Pour onto a buttered plate. Cool completely in the fridge, at least 1 hour.","With buttered hands, roll into small balls.","Roll each ball in chocolate sprinkles until completely coated.","Place in paper cases."],"tip":"The mixture is ready when you can draw a line through it with a spoon and it holds for a few seconds before filling in.","story":"Brigadeiro was created in 1945 to support the election campaign of Brigadier Eduardo Gomes. His supporters sold the sweets at fundraisers — the name stuck even after he lost."},
"Banh Mi":{"name":"Bánh Mì","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/B%C3%A1nh_M%C3%AC_Saigon.jpg/800px-B%C3%A1nh_M%C3%AC_Saigon.jpg","country":"Vietnam","description":"Saigon's iconic sandwich — a French baguette filled with pork, pâté, pickled vegetables, chilli and coriander. A perfect fusion of French and Vietnamese flavour.","prepTime":"20 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"small French baguettes"},{"amount":"200g","item":"char siu pork or pork belly, sliced"},{"amount":"4 tbsp","item":"chicken liver pâté"},{"amount":"4 tbsp","item":"mayonnaise"},{"amount":"1","item":"cucumber, matchsticks"},{"amount":"2","item":"carrots, pickled"},{"amount":"1","item":"red chilli, sliced"},{"amount":"bunch","item":"fresh coriander"}],"steps":["Pickle carrots with rice vinegar, sugar and salt for 20 minutes.","Split baguettes. Spread one side with pâté, other with mayonnaise.","Add pork, cucumber and pickled carrot.","Top with chilli and generous coriander.","Press closed and serve immediately."],"tip":"Vietnamese baguettes use rice flour for distinct crunch — the bread is crucial to the sandwich.","story":"Created during French colonialism in Vietnam and now considered one of the world's great street food sandwiches."},
"Goi Cuon":{"name":"Goi Cuon","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/G%E1%BB%8Fi_cu%E1%BB%91n.jpg/800px-G%E1%BB%8Fi_cu%E1%BB%91n.jpg","country":"Vietnam","description":"Vietnam's delicate fresh spring rolls — rice paper wrapped around prawns, herbs, vermicelli and lettuce, served with peanut dipping sauce. Light, fresh and beautiful.","prepTime":"30 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"16","item":"rice paper rounds"},{"amount":"200g","item":"cooked prawns, halved lengthways"},{"amount":"100g","item":"rice vermicelli, cooked"},{"amount":"1","item":"lettuce, leaves separated"},{"amount":"mint, coriander, Thai basil","item":"large bunches"},{"amount":"1","item":"cucumber, julienned"},{"amount":"3 tbsp","item":"smooth peanut butter (dipping sauce)"},{"amount":"2 tbsp each","item":"hoisin sauce and lime juice"},{"amount":"1 tsp","item":"chilli sauce"}],"steps":["Mix peanut butter, hoisin, lime juice and chilli with warm water for dipping sauce.","Dip a rice paper in warm water for 10 seconds until just pliable.","Lay on a damp cloth. Place lettuce, herbs, vermicelli and cucumber in centre.","Add 2-3 prawn halves across the roll.","Fold sides in, roll tightly. Place seam-down.","Serve immediately with peanut dipping sauce."],"tip":"Work quickly — over-soaked rice paper tears when rolling. Ten seconds maximum.","story":"Goi cuon are called summer rolls to distinguish them from fried spring rolls. They represent the Vietnamese philosophy of fresh, balanced and light eating."},
"Hummus":{"name":"Hummus","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Hummus_from_The_Nile.jpg/800px-Hummus_from_The_Nile.jpg","country":"Lebanon","description":"Lebanon's silky chickpea and tahini dip — impossibly smooth, nutty and lemony, served warm with olive oil. The benchmark against which all hummus is judged.","prepTime":"15 mins","cookTime":"1 hr","serves":6,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"dried chickpeas, soaked overnight"},{"amount":"1 tsp","item":"bicarbonate of soda"},{"amount":"4 tbsp","item":"best quality tahini"},{"amount":"juice of 2","item":"lemons"},{"amount":"2","item":"garlic cloves"},{"amount":"4 tbsp","item":"ice-cold water"}],"steps":["Boil chickpeas with bicarbonate of soda until very soft. Drain.","Blend hot chickpeas immediately until completely smooth.","Add tahini, lemon juice and garlic. Blend 5 more minutes.","Add ice-cold water gradually until very smooth and creamy. Season.","Serve with olive oil, paprika and warm bread."],"tip":"Blend while hot and add ice-cold water — the temperature contrast creates the silk.","story":"Claimed by Lebanon, Israel and several other nations. The Arabic word simply means chickpeas."},
"Kibbeh":{"name":"Kibbeh","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Kibbeh_Samboussak.jpg/800px-Kibbeh_Samboussak.jpg","country":"Lebanon","description":"Lebanon's national dish — a torpedo-shaped shell of bulgur and lamb encasing a filling of spiced minced lamb, onion and pine nuts. Fried or baked until golden.","prepTime":"45 mins","cookTime":"20 mins","serves":16,"difficulty":"Hard","ingredients":[{"amount":"400g","item":"fine bulgur wheat"},{"amount":"600g","item":"lean lamb mince"},{"amount":"1 large","item":"onion"},{"amount":"1 tsp each","item":"ground allspice, cinnamon, cumin"},{"amount":"200g","item":"lamb mince (filling)"},{"amount":"1","item":"onion, finely diced (filling)"},{"amount":"50g","item":"pine nuts"},{"amount":"1 tsp","item":"ground allspice (filling)"},{"amount":"oil","item":"for deep frying"}],"steps":["Soak bulgur 20 minutes, drain and squeeze dry.","Blend bulgur with 600g lamb, grated onion and spices to a smooth paste. Chill.","Make filling: fry onion until golden. Add 200g lamb, pine nuts and allspice.","Wet hands. Take golf-ball of shell paste, hollow with finger, fill with 1 tsp filling.","Seal into torpedo shape. Fry at 170C 6-8 minutes until golden."],"tip":"The shell paste must be very cold and the hands kept wet — warm paste falls apart.","story":"Kibbeh is considered Lebanon's national dish and varies by region — some versions are raw, some baked, some fried."},
"Tabbouleh":{"name":"Tabbouleh","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Tabbouleh_01.jpg/800px-Tabbouleh_01.jpg","country":"Lebanon","description":"Lebanon's herb-forward salad — masses of flat-leaf parsley with a little bulgur, tomatoes and a sharp lemon dressing. More herb salad than grain salad.","prepTime":"20 mins","cookTime":"0 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"3 large bunches","item":"flat-leaf parsley, very finely chopped"},{"amount":"1 small bunch","item":"fresh mint, chopped"},{"amount":"50g","item":"fine bulgur wheat"},{"amount":"3","item":"ripe tomatoes, finely diced"},{"amount":"4","item":"spring onions, sliced"},{"amount":"juice of 2","item":"lemons"},{"amount":"4 tbsp","item":"extra virgin olive oil"},{"amount":"half tsp","item":"ground allspice"}],"steps":["Soak bulgur in cold water 20 minutes. Drain and squeeze dry.","Mix bulgur, tomatoes and spring onion with lemon, oil and allspice. Season.","Add parsley and mint. Toss to combine.","Taste — should be predominantly herby, sharp and bright.","Serve immediately."],"tip":"Use much more parsley than seems right — it is a herb salad, not a grain salad.","story":"Tabbouleh spread globally through the Lebanese diaspora and is now one of the most recognised Middle Eastern foods worldwide."},
"Fattoush":{"name":"Fattoush","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Fattoush_salad.jpg/800px-Fattoush_salad.jpg","country":"Lebanon","description":"Lebanon's crispy bread salad — seasonal vegetables tossed with toasted pitta shards and dressed with sumac and lemon. Bright, tangy and texturally brilliant.","prepTime":"15 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"2","item":"stale pitta breads, torn into pieces"},{"amount":"3","item":"ripe tomatoes, chopped"},{"amount":"1","item":"cucumber, chopped"},{"amount":"4","item":"radishes, sliced"},{"amount":"1 small","item":"gem lettuce, torn"},{"amount":"4","item":"spring onions, sliced"},{"amount":"bunch","item":"fresh mint and parsley"},{"amount":"2 tbsp","item":"sumac"},{"amount":"juice of 1","item":"lemon"},{"amount":"4 tbsp","item":"olive oil"}],"steps":["Toast pitta pieces in oven at 200C until crispy and golden, about 8 minutes.","Combine all vegetables and herbs in a wide bowl.","Whisk lemon juice, olive oil and sumac. Season well.","Dress salad just before serving.","Add pitta last and toss — they should retain some crunch."],"tip":"Add the pitta at the last possible moment — they become soggy within minutes.","story":"Fattoush is Lebanon's answer to Italian panzanella — a bread salad designed to use up stale flatbread rather than waste it."},
"Shawarma":{"name":"Shawarma","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Shawarma_wrap.jpg/800px-Shawarma_wrap.jpg","country":"Lebanon","description":"The Levant's great street food — chicken marinated in yoghurt and warm spices, roasted until caramelised, wrapped in flatbread with garlic sauce and pickles.","prepTime":"20 mins","cookTime":"30 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"chicken thighs, boneless"},{"amount":"200g","item":"yoghurt"},{"amount":"juice of 1","item":"lemon"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"1 tsp each","item":"ground cumin, coriander, allspice, paprika, turmeric"},{"amount":"4","item":"flatbreads"},{"amount":"4 tbsp","item":"toum (garlic sauce) or mayonnaise"},{"amount":"pickled turnips, tomatoes, parsley","item":"to serve"}],"steps":["Marinate chicken in yoghurt, lemon, garlic and all spices overnight.","Roast at 220C for 25 minutes until charred at edges.","Rest 5 minutes then slice thinly or shred.","Warm flatbreads. Spread with toum.","Add chicken, pickles, tomatoes and parsley.","Roll tightly and serve immediately."],"tip":"High heat and overnight marinating are the two secrets to authentic shawarma flavour.","story":"Shawarma originated in the Ottoman Empire and spread throughout the Middle East. The vertical spit technique was adopted globally and inspired the Turkish doner kebab and Mexican al pastor."},
"Knafeh":{"name":"Knafeh","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Kanafeh.jpg/800px-Kanafeh.jpg","country":"Lebanon","description":"The Middle East's greatest dessert — shredded kataifi pastry over molten white cheese, soaked in fragrant rose water syrup and scattered with crushed pistachios.","prepTime":"20 mins","cookTime":"30 mins","serves":10,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"kataifi (shredded filo) pastry"},{"amount":"200g","item":"butter, melted"},{"amount":"500g","item":"unsalted white cheese (akkawi or mozzarella)"},{"amount":"300g","item":"caster sugar"},{"amount":"200ml","item":"water"},{"amount":"2 tbsp","item":"rose water"},{"amount":"1 tbsp","item":"orange blossom water"},{"amount":"100g","item":"unsalted pistachios, finely chopped"}],"steps":["Make syrup: dissolve sugar in water, simmer 10 minutes. Add rose and orange blossom water.","Mix kataifi with melted butter until well coated.","Press half into a buttered baking dish.","Slice cheese thinly and layer over kataifi.","Top with remaining kataifi, pressing firmly.","Bake at 200C 25-30 minutes until golden. Immediately pour cold syrup over hot knafeh. Scatter pistachios."],"tip":"Always pour cold syrup over hot knafeh — this creates the perfect soaked but not soggy texture.","story":"Knafeh originated in the Palestinian city of Nablus, where it remains the city's most famous export. Every Arab country has its own version but Nablus knafeh is considered the original."},
"Ceviche":{"name":"Ceviche","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Cebiche.jpg/800px-Cebiche.jpg","country":"Peru","description":"Peru's national treasure — fresh raw fish cured in lime juice with ají amarillo, red onion and coriander. Bracing, electric and one of the world's great dishes.","prepTime":"20 mins","cookTime":"0 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"very fresh sea bass or sole, cubed"},{"amount":"juice of 8-10","item":"limes (about 150ml)"},{"amount":"2","item":"ají amarillo chillies (or 1 scotch bonnet), chopped"},{"amount":"1 large","item":"red onion, very thinly sliced"},{"amount":"2 tbsp","item":"fresh coriander"},{"amount":"1 tsp","item":"fresh ginger, grated"},{"amount":"1","item":"garlic clove, grated"}],"steps":["Chill fish in freezer 10 minutes. Pat dry.","Mix lime juice, ginger and garlic. Season well.","Add fish to marinade. Mix gently. Marinate 3-5 minutes only.","Add sliced onion, chilli and coriander. Toss.","Serve immediately in cold bowls with corn and sweet potato."],"tip":"Marinate only 3 minutes for tender fish. Over-marinading makes it rubbery.","story":"Ceviche has been made on the Peruvian coast for over 2000 years. Spanish colonists introduced citrus which transformed it into what it is today."},
"Lomo Saltado":{"name":"Lomo Saltado","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Lomo_saltado02.jpg/800px-Lomo_saltado02.jpg","country":"Peru","description":"Peru's great stir-fry — beef, tomatoes and peppers wok-fried with soy sauce and vinegar, served over rice and chips. The definitive Chinese-Peruvian fusion dish.","prepTime":"20 mins","cookTime":"15 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"600g","item":"beef tenderloin, cut into strips"},{"amount":"2 large","item":"tomatoes, wedged"},{"amount":"1 large","item":"red onion, wedged"},{"amount":"3 tbsp","item":"soy sauce"},{"amount":"2 tbsp","item":"red wine vinegar"},{"amount":"2","item":"garlic cloves, minced"},{"amount":"fresh coriander, chips and rice","item":"to serve"}],"steps":["Heat wok over highest heat until smoking.","Sear beef in batches 1 minute maximum. Remove.","Stir-fry onion and chilli 2 minutes over high heat.","Add tomatoes briefly then return beef.","Add soy sauce and vinegar. Toss vigorously.","Finish with coriander. Serve over rice topped with chips."],"tip":"Extreme high heat is essential — you want charred edges and smokiness.","story":"Created by Chinese workers who arrived in Peru in the 19th century, adapting stir-fry techniques with local ingredients."},
"Aji de Gallina":{"name":"Ají de Gallina","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Aji_de_Gallina.jpg/800px-Aji_de_Gallina.jpg","country":"Peru","description":"Peru's beloved yellow chilli chicken — shredded chicken in a rich, creamy ají amarillo sauce with walnuts and cheese. Comforting, complex and deeply Peruvian.","prepTime":"20 mins","cookTime":"40 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"800g","item":"chicken breast, poached and shredded"},{"amount":"4 tbsp","item":"ají amarillo paste"},{"amount":"4 slices","item":"white bread, crusts removed, soaked in milk"},{"amount":"100g","item":"walnuts, ground"},{"amount":"100g","item":"Parmesan or queso blanco, grated"},{"amount":"1 large","item":"onion, diced"},{"amount":"3","item":"garlic cloves, minced"},{"amount":"200ml","item":"chicken stock"}],"steps":["Fry onion and garlic until soft. Add ají amarillo paste and cook 3 minutes.","Squeeze bread and add to pan. Mash into sauce.","Add stock gradually until smooth and creamy.","Add ground walnuts and cheese. Stir until melted.","Add shredded chicken. Simmer 10 minutes.","Serve over rice with boiled potatoes and olives."],"tip":"Ají amarillo is the soul of Peruvian cooking — its fruity heat is unlike any other chilli.","story":"Ají de gallina is one of Peru's most beloved comfort dishes, often the first thing Peruvians living abroad want to eat when they return home."},
"Doro Wat":{"name":"Doro Wat","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Doro_wat.jpg/800px-Doro_wat.jpg","country":"Ethiopia","description":"Ethiopia's most celebrated dish — chicken slow-braised in a deep dark berbere-spiced sauce with caramelised onions and whole hard-boiled eggs. The feast day dish.","prepTime":"30 mins","cookTime":"2 hrs","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1.5kg","item":"chicken pieces, skin removed"},{"amount":"4 large","item":"red onions, very finely diced"},{"amount":"3 tbsp","item":"berbere spice blend"},{"amount":"4 tbsp","item":"niter kibbeh or butter"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"6","item":"hard-boiled eggs, peeled and scored"}],"steps":["Dry-fry onions in a heavy pot with no oil for 20 minutes, stirring constantly.","Add niter kibbeh and continue until onions are very dark and jammy.","Add berbere, garlic. Cook 5 minutes.","Add chicken. Cover and simmer on low heat 1 hour 30 minutes.","Score eggs and add in last 20 minutes.","Serve on injera with eggs nestled in the sauce."],"tip":"Dry-frying onions without oil first is the key Ethiopian technique — it concentrates and caramelises them without burning.","story":"Doro wat is the dish Ethiopians make for their most important celebrations — Christmas, Easter and weddings. No feast is complete without it."},
"Injera":{"name":"Injera","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Injera-Ethiopian-food.jpg/800px-Injera-Ethiopian-food.jpg","country":"Ethiopia","description":"Ethiopia's ancient sourdough flatbread — made from fermented teff flour, spongy and sour, used as both plate and utensil for scooping up stews and salads.","prepTime":"5 mins (plus 3 days fermentation)","cookTime":"2 mins per injera","serves":8,"difficulty":"Medium","ingredients":[{"amount":"300g","item":"teff flour"},{"amount":"700ml","item":"water"},{"amount":"half tsp","item":"salt"}],"steps":["Mix teff flour with 500ml water. Cover and ferment at room temperature for 2-3 days until bubbly and sour.","Stir in remaining water and salt to make a thin batter.","Heat a large non-stick pan over medium heat. No oil needed.","Pour a ladleful of batter and swirl to cover pan as thinly as possible.","Cook 2-3 minutes until holes appear across the surface and edges lift. Do not flip.","Slide onto a clean cloth. Stack when cooled."],"tip":"Injera should only be cooked on one side — the bubbly top surface is for scooping and the bottom is the contact side. Never flip.","story":"Injera has been Ethiopia's staple food for millennia and is made from teff — a grain unique to the Ethiopian highlands. It serves as both food and edible plate at every Ethiopian meal."},
"Tibs":{"name":"Tibs","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Ethiopian_cuisine_-_tibs.jpg/800px-Ethiopian_cuisine_-_tibs.jpg","country":"Ethiopia","description":"Ethiopia's most popular sautéed dish — cubes of beef or lamb quickly cooked with onions, jalapeños, rosemary and berbere in a hot pan. Fast, fragrant and deeply savoury.","prepTime":"15 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"beef or lamb, cut into small cubes"},{"amount":"2 large","item":"onions, sliced"},{"amount":"2","item":"jalapeños, sliced"},{"amount":"3","item":"garlic cloves, minced"},{"amount":"1 tsp","item":"berbere spice"},{"amount":"1 tsp","item":"fresh rosemary, chopped"},{"amount":"2 tbsp","item":"niter kibbeh or butter"},{"amount":"salt and black pepper","item":"to taste"}],"steps":["Heat niter kibbeh in a heavy pan until smoking.","Add meat in batches and sear over high heat until browned outside.","Add onions and jalapeños. Cook 3 minutes.","Add garlic, berbere and rosemary. Toss 2 minutes.","Season generously. Serve sizzling on a hot plate.","Accompany with injera."],"tip":"Work in small batches and use highest heat — tibs should sear and caramelise, not steam.","story":"Tibs is Ethiopia's version of a quick sauté and is eaten for any occasion — from street food to restaurant dining."},
"Misir Wat":{"name":"Misir Wat","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Misir_wat.jpg/800px-Misir_wat.jpg","country":"Ethiopia","description":"Ethiopia's essential red lentil stew — split red lentils cooked down with onions and berbere into a thick, deeply spiced purée. The backbone of a traditional Ethiopian spread.","prepTime":"15 mins","cookTime":"45 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"split red lentils, rinsed"},{"amount":"2 large","item":"onions, very finely diced"},{"amount":"2 tbsp","item":"berbere spice blend"},{"amount":"3","item":"garlic cloves, minced"},{"amount":"1 tsp","item":"fresh ginger, grated"},{"amount":"3 tbsp","item":"niter kibbeh or vegetable oil"},{"amount":"600ml","item":"water"}],"steps":["Dry-fry onions without oil for 15 minutes until very soft and beginning to colour.","Add niter kibbeh, garlic and ginger. Cook 3 minutes.","Add berbere and stir 2 minutes until very fragrant.","Add lentils and water. Simmer 30 minutes until thick, stirring frequently.","Season well. Serve on injera."],"tip":"The long dry-frying of onions is the Ethiopian foundation — it creates a deeply caramelised base that no shortcut can replicate.","story":"Misir wat is a staple of Ethiopian fasting days when meat is forbidden. Ethiopia has one of the world's richest vegetarian cuisines developed through centuries of Orthodox Christian fasting."},
"Bulgogi":{"name":"Bulgogi","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Bulgogi.jpg/800px-Bulgogi.jpg","country":"South Korea","description":"Korea's beloved fire meat — thinly sliced beef marinated in sweet soy, pear and sesame, grilled until caramelised. One of the world's great marinades.","prepTime":"20 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"beef ribeye, very thinly sliced"},{"amount":"4 tbsp","item":"soy sauce"},{"amount":"2 tbsp","item":"sesame oil"},{"amount":"2 tbsp","item":"caster sugar"},{"amount":"half","item":"Asian pear, grated"},{"amount":"4","item":"garlic cloves, grated"},{"amount":"4","item":"spring onions, sliced"},{"amount":"1 tbsp","item":"toasted sesame seeds"}],"steps":["Mix soy, sesame oil, sugar, pear and garlic into marinade.","Add beef and spring onions. Marinate at least 1 hour.","Grill over very high heat 1-2 minutes per side until caramelised.","Cook in batches. The caramelisation is key.","Scatter sesame seeds. Serve with rice and lettuce for wrapping."],"tip":"The grated pear tenderises the meat and helps caramelisation — do not substitute with apple.","story":"Bulgogi means fire meat in Korean and dates to the Goguryeo era (37 BCE). One of the first Korean dishes to become popular internationally."},
"Japchae":{"name":"Japchae","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Japchae.jpg/800px-Japchae.jpg","country":"South Korea","description":"Korea's celebratory glass noodle dish — sweet potato starch noodles stir-fried with a rainbow of vegetables and beef. Served at every Korean birthday and celebration.","prepTime":"30 mins","cookTime":"20 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"200g","item":"glass noodles (dangmyeon)"},{"amount":"200g","item":"beef sirloin, thinly sliced"},{"amount":"3 tbsp","item":"soy sauce"},{"amount":"2 tbsp","item":"sesame oil"},{"amount":"1 tbsp","item":"sugar"},{"amount":"1 large","item":"carrot, julienned"},{"amount":"6","item":"shiitake mushrooms, sliced"},{"amount":"100g","item":"spinach, blanched"},{"amount":"2 tbsp","item":"toasted sesame seeds"}],"steps":["Soak glass noodles 20 minutes. Boil 5 minutes. Drain, season with soy and sesame.","Marinate beef in soy, sesame oil and sugar. Stir-fry quickly.","Stir-fry each vegetable separately, seasoning lightly.","Combine noodles, beef and vegetables. Toss with remaining soy and sesame.","Add sesame seeds. Serve warm or at room temperature."],"tip":"Stir-fry each ingredient separately before combining — this keeps each at its best texture.","story":"Created in the 17th century for King Gwanghaegun who loved it so much he gave its creator a high court position."},
"Tteokbokki":{"name":"Tteokbokki","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Tteok-bokki.jpg/800px-Tteok-bokki.jpg","country":"South Korea","description":"Korea's most beloved street food — chewy rice cakes in a fiery gochujang sauce. Found bubbling on street stalls across Seoul, eaten standing up.","prepTime":"10 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"tteok (cylinder rice cakes)"},{"amount":"200g","item":"fish cakes, sliced"},{"amount":"3 tbsp","item":"gochujang"},{"amount":"1 tbsp","item":"gochugaru (chilli flakes)"},{"amount":"1 tbsp","item":"soy sauce"},{"amount":"1 tbsp","item":"sugar"},{"amount":"500ml","item":"anchovy or vegetable stock"},{"amount":"2","item":"spring onions, sliced"},{"amount":"2","item":"hard-boiled eggs (optional)"}],"steps":["Bring stock to boil in a wide pan.","Mix gochujang, gochugaru, soy sauce and sugar into stock.","Add rice cakes. Simmer 8-10 minutes until sauce thickens and rice cakes are tender and chewy.","Add fish cakes and spring onion. Cook 3 more minutes.","Add eggs if using. Serve immediately — the sauce will thicken further on standing."],"tip":"The rice cakes should be tender but with a distinct chew — overcooked tteok become mushy.","story":"Tteokbokki has been a Korean street food staple since the 1950s when the current gochujang version replaced an older royal-court version made with soy sauce and beef."},
"Samgyeopsal":{"name":"Samgyeopsal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Samgyeopsal-bokkeum.jpg/800px-Samgyeopsal-bokkeum.jpg","country":"South Korea","description":"Korea's most convivial meal — thick pork belly grilled at the table on a charcoal grill, wrapped in lettuce with garlic, chilli paste and perilla leaves. Pure shared pleasure.","prepTime":"15 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"pork belly, sliced 1cm thick"},{"amount":"1 head","item":"garlic, cloves sliced"},{"amount":"1","item":"green chilli, sliced"},{"amount":"4 tbsp","item":"ssamjang (fermented soybean dipping paste)"},{"amount":"butter lettuce leaves","item":"for wrapping"},{"amount":"perilla leaves","item":"for wrapping"},{"amount":"spring onion salad","item":"to serve"}],"steps":["Heat table grill or cast-iron griddle to high.","Place pork belly on grill. Cook without moving until fat renders and underside is golden, 3-4 minutes.","Flip. Cook 3 more minutes. Cut into bite-sized pieces with scissors at the table.","Grill sliced garlic and chilli alongside until lightly golden.","To eat: place pork in lettuce or perilla leaf, add garlic, chilli and dab of ssamjang. Wrap and eat in one bite."],"tip":"Pork belly on a charcoal grill has a smokiness a gas grill cannot replicate. A cast-iron griddle on the hob is the best home substitute.","story":"Samgyeopsal means three-layer meat — the three visible layers of fat and meat in pork belly. It is South Korea's most popular restaurant dish, eaten communally."},
"Full English Breakfast":{"name":"Full English Breakfast","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Full_English_Breakfast_%2832052685560%29.jpg/800px-Full_English_Breakfast_%2832052685560%29.jpg","country":"United Kingdom","description":"Britain's greatest morning meal — bacon, eggs, sausages, beans, mushrooms, tomatoes and toast on one plate. An institution that requires no justification.","prepTime":"10 mins","cookTime":"20 mins","serves":2,"difficulty":"Easy","ingredients":[{"amount":"4 rashers","item":"back bacon"},{"amount":"4","item":"pork sausages"},{"amount":"4","item":"eggs"},{"amount":"200g","item":"baked beans"},{"amount":"4","item":"chestnut mushrooms"},{"amount":"2","item":"tomatoes, halved"},{"amount":"4 slices","item":"white or brown bread"},{"amount":"butter","item":"for toast"},{"amount":"oil","item":"for frying"}],"steps":["Start sausages first — grill or fry over medium heat for 15 minutes, turning.","After 5 minutes add bacon and grill until crisp.","Fry mushrooms and tomatoes cut-side down in butter.","Heat beans in a small pan. Season.","Fry or scramble eggs to preference.","Toast bread. Butter generously.","Arrange everything on a warm plate. Serve with brown sauce or ketchup."],"tip":"Everything must arrive at the table simultaneously and hot. The mark of a great fry-up is timing, not technique.","story":"The full English developed from Victorian-era country house breakfasts and became democratised as a working-class meal in the 20th century. Every element is disputed — beans divide opinion most sharply."},
"Chicken Tikka Masala":{"name":"Chicken Tikka Masala","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Chicken_tikka_masala.jpg/800px-Chicken_tikka_masala.jpg","country":"United Kingdom","description":"Britain's adopted national dish — tandoor-grilled chicken tikka in a rich mildly spiced tomato-cream sauce. Whether British or Indian in origin, it is completely delicious.","prepTime":"20 mins","cookTime":"35 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"chicken breast, cubed"},{"amount":"200g","item":"full-fat yoghurt"},{"amount":"2 tbsp","item":"tikka masala paste"},{"amount":"2 large","item":"onions, diced"},{"amount":"400g","item":"tinned tomatoes"},{"amount":"200ml","item":"double cream"},{"amount":"2 tsp each","item":"ground cumin, coriander, garam masala"}],"steps":["Marinate chicken in yoghurt and tikka paste 1 hour. Grill until charred.","Fry onions in butter until golden. Add garlic, ginger and spices. Cook 3 minutes.","Add tomatoes and simmer 15 minutes until thick. Blend until smooth.","Add cream and grilled chicken. Simmer 10 minutes.","Serve with rice and naan."],"tip":"The tikka — charring the chicken first — is what separates great tikka masala from a flat one.","story":"Allegedly created in Glasgow in the 1970s when a customer complained his chicken tikka was too dry. The added tomato-cream sauce changed British food history."},
"Sticky Toffee Pudding":{"name":"Sticky Toffee Pudding","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Sticky_toffee_pudding.jpg/800px-Sticky_toffee_pudding.jpg","country":"United Kingdom","description":"Britain's greatest dessert — a moist dense date sponge drenched in hot butterscotch sauce. Served with vanilla ice cream or clotted cream.","prepTime":"20 mins","cookTime":"35 mins","serves":8,"difficulty":"Easy","ingredients":[{"amount":"175g","item":"medjool dates, chopped"},{"amount":"175ml","item":"boiling water"},{"amount":"1 tsp","item":"bicarbonate of soda"},{"amount":"175g","item":"plain flour"},{"amount":"175g","item":"caster sugar"},{"amount":"75g","item":"butter"},{"amount":"2","item":"eggs"},{"amount":"200g","item":"dark brown sugar (sauce)"},{"amount":"200ml","item":"double cream (sauce)"},{"amount":"100g","item":"butter (sauce)"}],"steps":["Soak dates in boiling water with bicarb 10 minutes. Blend roughly.","Beat butter and sugar until pale. Beat in eggs.","Fold in flour then date mixture. Pour into buttered dish.","Bake 180C 30-35 minutes.","Make sauce: melt butter, brown sugar and cream until smooth.","Pour hot sauce over warm pudding. Serve with ice cream."],"tip":"Poke holes before pouring sauce — this allows it to seep into the sponge rather than just pooling on top.","story":"Invented at Sharrow Bay Hotel in the Lake District in the 1970s. The Lake District still claims it as theirs."},
"BBQ Brisket":{"name":"BBQ Brisket","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Texas_brisket.jpg/800px-Texas_brisket.jpg","country":"United States","description":"The crown jewel of Texas barbecue — beef brisket slow-smoked over post oak for up to 18 hours until a black bark forms outside and the meat trembles with juiciness within.","prepTime":"15 mins","cookTime":"12-18 hrs","serves":12,"difficulty":"Hard","ingredients":[{"amount":"5-6kg","item":"whole beef brisket"},{"amount":"4 tbsp","item":"coarse black pepper"},{"amount":"4 tbsp","item":"coarse sea salt"},{"amount":"oak or hickory wood","item":"for smoking"}],"steps":["Trim fat cap to 1cm. Apply equal parts salt and pepper all over. Rest 1 hour.","Smoke at 107C with post oak for 6 hours until bark forms.","Wrap tightly in butcher paper. Return to smoker.","Continue smoking until internal temperature reaches 96C (12-18 hours total).","Rest wrapped at least 1 hour. Slice against the grain."],"tip":"Never rush brisket. The paper wrap traps moisture to push through the temperature stall.","story":"Texas barbecue brisket traces to Czech and German butchers who settled Central Texas in the 19th century and smoked this tough cheap cut to sell from their markets."},
"Clam Chowder":{"name":"Clam Chowder","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Clam_chowder.jpg/800px-Clam_chowder.jpg","country":"United States","description":"New England's iconic white chowder — clams, potatoes and bacon in a thick rich cream broth. Served in a sourdough bread bowl on Fisherman's Wharf.","prepTime":"20 mins","cookTime":"35 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"3 tins","item":"clams in juice"},{"amount":"4 rashers","item":"smoked bacon, diced"},{"amount":"1 large","item":"onion, diced"},{"amount":"3","item":"medium potatoes, diced"},{"amount":"400ml","item":"fish stock"},{"amount":"400ml","item":"double cream"},{"amount":"2 tbsp","item":"plain flour"},{"amount":"30g","item":"butter"}],"steps":["Fry bacon until crispy. Remove. Melt butter, soften onion 8 minutes.","Stir in flour. Add clam juice and stock gradually. Add potatoes. Simmer 15 minutes.","Add cream and clams. Heat gently — never boil.","Season. Serve topped with bacon and chives."],"tip":"Never boil the chowder once cream is added — it will break and curdle.","story":"New England clam chowder dates to the 18th century. The great debate — cream-based vs tomato-based Manhattan — remains fiercely contested."},
"Gumbo":{"name":"Gumbo","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Gumbo_-_Meal.jpg/800px-Gumbo_-_Meal.jpg","country":"United States","description":"Louisiana's great stew — shrimp, andouille sausage and okra in a dark roux-thickened broth. The soul of Cajun and Creole cooking.","prepTime":"30 mins","cookTime":"1 hr 30 mins","serves":8,"difficulty":"Hard","ingredients":[{"amount":"175ml","item":"vegetable oil"},{"amount":"175g","item":"plain flour"},{"amount":"2","item":"onions, diced"},{"amount":"4","item":"celery stalks, diced"},{"amount":"2","item":"green peppers, diced"},{"amount":"400g","item":"andouille sausage, sliced"},{"amount":"500g","item":"raw prawns, peeled"},{"amount":"200g","item":"okra, sliced"},{"amount":"1.5L","item":"chicken stock"},{"amount":"2 tsp each","item":"smoked paprika, thyme, cayenne"}],"steps":["Stir oil and flour over medium heat continuously for 30-45 minutes until dark chocolate colour.","Add onion, celery, pepper. Cook 10 minutes.","Add garlic, sausage and spices. Add warm stock gradually.","Simmer 45 minutes. Add okra and prawns in last 10 minutes.","Serve over white rice."],"tip":"The dark roux is the soul of gumbo and cannot be rushed. Constant stirring for 45 minutes is required.","story":"Gumbo is the official state cuisine of Louisiana, blending West African, French, Spanish and Native American cooking traditions."},
"Lobster Roll":{"name":"Lobster Roll","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Lobster_roll_sandwich.jpg/800px-Lobster_roll_sandwich.jpg","country":"United States","description":"New England's summer luxury — fresh lobster lightly dressed with mayonnaise and lemon, piled into a butter-griddled hot dog bun.","prepTime":"20 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"cooked lobster meat, chunked"},{"amount":"3 tbsp","item":"good quality mayonnaise"},{"amount":"juice of half","item":"lemon"},{"amount":"1 tbsp","item":"fresh chives, chopped"},{"amount":"4","item":"top-split hot dog rolls"},{"amount":"30g","item":"butter"}],"steps":["Mix lobster gently with mayonnaise, lemon and chives. Season. Chill.","Butter the sides of the rolls.","Toast rolls butter-side-down until golden.","Fill generously with cold lobster mixture.","Serve immediately with lemon and chips."],"tip":"The filling should be cold, the roll warm — this contrast is the hallmark of a great lobster roll.","story":"Invented in 1929 in Milford Connecticut. Maine and Connecticut still argue about whose version is definitive."},
"Philly Cheesesteak":{"name":"Philly Cheesesteak","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Philly_cheesesteak_from_Genos.jpg/800px-Philly_cheesesteak_from_Genos.jpg","country":"United States","description":"Philadelphia's greatest contribution — thinly shaved ribeye with caramelised onions and melted cheese in a toasted hoagie roll. Iconic, indulgent, irreplaceable.","prepTime":"15 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"ribeye steak, frozen briefly then shaved thin"},{"amount":"2 large","item":"onions, thinly sliced"},{"amount":"100g","item":"Cheez Whiz or provolone"},{"amount":"4","item":"hoagie rolls, toasted"}],"steps":["Caramelise onions over medium heat 20 minutes. Push to side.","Spread shaved steak on high-heat griddle. Season. Chop and flip with spatula.","Mix with onions when cooked. Form into roll-shaped portions.","Lay cheese over each. When melted, scoop into rolls.","Serve immediately."],"tip":"Freezing the ribeye briefly makes it possible to shave paper thin at home.","story":"Invented in 1930 by Pat Olivieri in South Philadelphia. Cheese wasn't added until the 1940s."},
"Key Lime Pie":{"name":"Key Lime Pie","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Key_Lime_Pie.jpg/800px-Key_Lime_Pie.jpg","country":"United States","description":"Florida's official state pie — a custardy intensely tangy lime filling in a cracker crust. Deceptively simple and utterly addictive.","prepTime":"20 mins","cookTime":"20 mins","serves":8,"difficulty":"Easy","ingredients":[{"amount":"200g","item":"digestive biscuits, crushed"},{"amount":"80g","item":"butter, melted"},{"amount":"4","item":"egg yolks"},{"amount":"400ml","item":"sweetened condensed milk"},{"amount":"120ml","item":"lime juice"},{"amount":"zest of 4","item":"limes"},{"amount":"300ml","item":"double cream, whipped"}],"steps":["Mix biscuits with butter. Press into tart tin. Bake 180C 10 minutes. Cool.","Beat egg yolks with zest 2 minutes. Add condensed milk and lime juice.","Pour into cooled base. Bake 160C 15 minutes until just set with wobble.","Refrigerate 2 hours minimum. Top with whipped cream."],"tip":"Do not over-bake — the filling sets further as it cools. A wobble is correct.","story":"Originated in the Florida Keys in the late 19th century using local Key limes and condensed milk, which didn't require refrigeration at sea."},
"Empanadas":{"name":"Empanadas","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Empanada_de_pino.jpg/800px-Empanada_de_pino.jpg","country":"Argentina","description":"Argentina's beloved pastry parcels — flaky dough folded around spiced beef, olive and egg filling. Every province has its own version.","prepTime":"45 mins","cookTime":"25 mins","serves":12,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"plain flour"},{"amount":"125g","item":"cold lard or butter"},{"amount":"150ml","item":"warm water"},{"amount":"400g","item":"beef mince"},{"amount":"2","item":"onions, diced"},{"amount":"2 tsp","item":"ground cumin"},{"amount":"1 tsp","item":"smoked paprika"},{"amount":"2","item":"hard-boiled eggs, chopped"},{"amount":"50g","item":"green olives, sliced"}],"steps":["Rub fat into flour and salt. Add water to form soft dough. Rest 30 minutes.","Brown beef with onion and spices until dry. Cool completely.","Mix in eggs and olives. Roll dough to 3mm and cut 15cm rounds.","Fill off-centre, fold over and crimp edges.","Bake 200C 20-25 minutes until golden."],"tip":"The filling must be completely cold before filling or the dough steams from inside and becomes soggy.","story":"Arrived in Argentina with Spanish colonists from Galicia. Each province developed distinct fillings — Salta's spiced beef is most famous."},
"Chimichurri Steak":{"name":"Chimichurri Steak","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Chimichurri_sauce.jpg/800px-Chimichurri_sauce.jpg","country":"Argentina","description":"Argentina's perfect pairing — a charred beef steak resting in a pool of vivid chimichurri of parsley, oregano, garlic and red wine vinegar. The backbone of the Argentine table.","prepTime":"15 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"sirloin steaks, 2cm thick"},{"amount":"coarse salt and black pepper","item":"to season"},{"amount":"large bunch","item":"flat-leaf parsley, finely chopped"},{"amount":"4","item":"garlic cloves, finely chopped"},{"amount":"1 tsp each","item":"dried oregano and chilli flakes"},{"amount":"4 tbsp","item":"red wine vinegar"},{"amount":"8 tbsp","item":"extra virgin olive oil"}],"steps":["Make chimichurri: combine all ingredients. Rest 30 minutes minimum.","Season steaks generously. Grill over highest heat 3 minutes per side for medium-rare.","Rest steaks 5 minutes.","Spoon chimichurri generously over resting steaks.","Serve with more chimichurri alongside."],"tip":"Make chimichurri at least 30 minutes ahead — the garlic and herbs need time to mellow.","story":"The name possibly derives from Basque tximitxurri, brought by Basque immigrants to the Pampas in the 19th century."},
"Locro":{"name":"Locro","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Locro_de_Argentina.jpg/800px-Locro_de_Argentina.jpg","country":"Argentina","description":"Argentina's hearty winter stew — white corn, white beans and multiple cuts of pork slow-cooked for hours into a thick, sustaining potage. The dish of national holidays.","prepTime":"20 mins","cookTime":"3 hrs","serves":8,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"dried white corn, soaked overnight"},{"amount":"200g","item":"dried white beans, soaked overnight"},{"amount":"400g","item":"pork shoulder, cubed"},{"amount":"200g","item":"chorizo, sliced"},{"amount":"200g","item":"panceta (cured pork belly), diced"},{"amount":"1 large","item":"onion, diced"},{"amount":"2","item":"sweet potatoes, diced"},{"amount":"1 tsp each","item":"ground cumin, sweet paprika"}],"steps":["Simmer corn and beans separately until tender, about 1 hour each.","Brown pork shoulder, chorizo and panceta. Add onion and cook until soft.","Combine meat with drained corn, beans and sweet potato.","Add water to cover. Simmer 1.5 hours until very thick.","Season generously. Serve with a spiced sofrito of paprika and chilli oil on the side."],"tip":"Locro should be very thick — almost more stew than soup. Add water sparingly during cooking.","story":"Locro was the staple food of pre-Columbian Andean civilisations and remains the traditional dish eaten on May 25 — Argentina's national day."},
"Iskender Kebab":{"name":"Iskender Kebab","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Iskender_kebab.jpg/800px-Iskender_kebab.jpg","country":"Turkey","description":"Bursa's legendary dish — thin slices of döner lamb on torn flatbread, drenched in hot tomato sauce and brown butter, with yoghurt alongside. Theatre of contrasting temperatures.","prepTime":"30 mins","cookTime":"25 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"600g","item":"lamb mince"},{"amount":"2 tsp each","item":"ground cumin, paprika, oregano"},{"amount":"4 large","item":"flatbreads or pide, torn"},{"amount":"400g","item":"tinned tomatoes, blended"},{"amount":"100g","item":"butter"},{"amount":"300g","item":"thick yoghurt"}],"steps":["Mix lamb with spices. Form into a log. Grill until cooked and slightly charred. Slice very thinly.","Make tomato sauce: simmer tomatoes with garlic until thick. Season.","Toast flatbread pieces until slightly crispy.","Arrange bread in bowls. Spoon lamb over. Pour hot tomato sauce over.","Brown butter until nutty and pour sizzling over. Add yoghurt alongside."],"tip":"The butter must be genuinely browned and nutty — the sizzle when it hits the dish is part of the experience.","story":"Invented in 1867 by Iskender Efendi in Bursa, who created the first vertical spit döner kebab. His family still runs the original restaurant."},
"Manti":{"name":"Manti","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Manti_dumplings.jpg/800px-Manti_dumplings.jpg","country":"Turkey","description":"Turkey's exquisite tiny dumplings — walnut-sized parcels of spiced lamb, served with garlicky yoghurt, brown butter and dried mint. The smaller the dumpling, the better the cook.","prepTime":"1 hr","cookTime":"15 mins","serves":4,"difficulty":"Hard","ingredients":[{"amount":"300g","item":"plain flour"},{"amount":"2","item":"eggs"},{"amount":"water","item":"as needed"},{"amount":"300g","item":"lamb mince"},{"amount":"1","item":"onion, grated"},{"amount":"1 tsp","item":"ground allspice"},{"amount":"500g","item":"thick yoghurt"},{"amount":"4","item":"garlic cloves, crushed"},{"amount":"60g","item":"butter"},{"amount":"2 tsp","item":"dried mint and paprika"}],"steps":["Knead flour, eggs and water to a firm dough. Rest 30 minutes.","Mix lamb with grated onion, allspice, salt and pepper.","Roll dough very thin. Cut into small squares (3cm).","Place tiny amount of filling in each. Pinch corners together to seal.","Boil in salted water 10-12 minutes until tender.","Serve with garlic yoghurt, browned butter drizzled over, and dried mint."],"tip":"In Kayseri the sign of a skilled cook is how many manti fit in a spoon — the ideal is 40.","story":"Manti arrived in Turkey from Central Asia via the Silk Road and became particularly associated with Kayseri, where the making of tiny manti is considered a test of a bride's skill."},
"Lahmacun":{"name":"Lahmacun","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Lahmacun_2_%28cropped%29.jpg/800px-Lahmacun_2_%28cropped%29.jpg","country":"Turkey","description":"Turkish pizza — a thin crispy flatbread topped with finely minced spiced lamb and vegetables, rolled up with parsley, lemon and tomato. Street food perfection.","prepTime":"30 mins","cookTime":"8 mins","serves":8,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"strong flour"},{"amount":"7g","item":"yeast"},{"amount":"250ml","item":"warm water"},{"amount":"300g","item":"lamb mince, very finely minced"},{"amount":"1 large","item":"onion, finely grated"},{"amount":"2","item":"tomatoes, very finely diced"},{"amount":"1","item":"red pepper, very finely diced"},{"amount":"1 tsp each","item":"ground cumin, paprika, allspice, sumac"},{"amount":"bunch","item":"flat-leaf parsley"},{"amount":"2","item":"lemons, cut into wedges"}],"steps":["Make dough: mix flour, yeast, salt and water. Knead 10 minutes. Prove 1 hour.","Combine all topping ingredients. The mixture should be almost a paste.","Preheat oven to maximum with a baking tray inside.","Roll dough into very thin ovals. Spread topping extremely thinly.","Bake 6-8 minutes until edges are crisp and topping is cooked.","Roll up with parsley, lemon juice and sliced tomato inside."],"tip":"The topping must be spread paper thin — thick topping prevents the base from crisping and makes it soggy.","story":"Lahmacun is claimed by both Turkey and Armenia and has been made throughout the Middle East for centuries. In Turkey it is often called Turkish pizza, though purists object strongly."},
"Imam Bayildi":{"name":"Imam Bayildı","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Imam_bayildi.jpg/800px-Imam_bayildi.jpg","country":"Turkey","description":"Turkey's most poetic dish — aubergines stuffed and slow-cooked in olive oil until almost melting, with a sweet onion, tomato and garlic filling. The imam who tasted it fainted with delight.","prepTime":"20 mins","cookTime":"1 hr","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4 medium","item":"aubergines"},{"amount":"4 large","item":"onions, thinly sliced"},{"amount":"6","item":"garlic cloves, sliced"},{"amount":"4","item":"tomatoes, diced"},{"amount":"small bunch","item":"flat-leaf parsley"},{"amount":"150ml","item":"extra virgin olive oil"},{"amount":"1 tsp","item":"sugar"},{"amount":"juice of 1","item":"lemon"}],"steps":["Slit aubergines lengthways without cutting through. Salt and rest 30 minutes. Rinse and dry.","Caramelise onions in half the olive oil for 20 minutes. Add garlic and tomatoes. Season with sugar and salt.","Stuff aubergines with onion mixture. Place in a baking dish.","Pour remaining olive oil over and around. Add water to come 1cm up the sides.","Bake covered at 180C for 45 minutes until aubergines are completely collapsed.","Cool to room temperature. Serve with parsley and lemon."],"tip":"Imam bayildi is always served at room temperature or cold — never hot. The flavours deepen as it cools.","story":"The name means the imam fainted — with delight at the flavour, some say, or with horror at the quantity of expensive olive oil used, according to others."},"Soupe à l'Oignon":{"name":"Soupe à l'Oignon","country":"France","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Soupe_%C3%A0_l%27oignon-1.jpg/800px-Soupe_%C3%A0_l%27oignon-1.jpg","description":"Paris's greatest cold-weather soup — slowly caramelised onions in rich beef broth, crowned with a crouton drowned in bubbling Gruyère.","prepTime":"15 mins","cookTime":"1 hr 20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"1.2kg","item":"onions, thinly sliced"},{"amount":"60g","item":"unsalted butter"},{"amount":"200ml","item":"dry white wine"},{"amount":"1L","item":"beef stock"},{"amount":"4 slices","item":"baguette, toasted"},{"amount":"150g","item":"Gruyère, grated"}],"steps":["Melt butter. Cook onions with salt over medium-low 45-60 minutes until deep golden.","Stir in flour, cook 2 minutes. Add wine, reduce by half.","Pour in stock. Simmer 20 minutes. Season.","Ladle into oven-safe bowls. Float crouton on top. Cover with Gruyère.","Grill until cheese is bubbling and spotted brown."],"tip":"The caramelisation cannot be rushed — 45 minutes minimum on low heat.","story":"Became iconic in the Les Halles market district of Paris, eaten at dawn by market workers."}
,"Croissants":{"name":"Croissants","country":"France","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Croissant_copy.jpg/800px-Croissant_copy.jpg","description":"The pinnacle of viennoiserie — 27 layers of buttery dough folded over two days to produce shattering crispness and a honeycomb interior.","prepTime":"4 hrs over 2 days","cookTime":"20 mins","serves":12,"difficulty":"Hard","ingredients":[{"amount":"500g","item":"strong white bread flour"},{"amount":"10g","item":"salt"},{"amount":"75g","item":"caster sugar"},{"amount":"10g","item":"yeast"},{"amount":"300ml","item":"cold whole milk"},{"amount":"280g","item":"cold unsalted butter"},{"amount":"1","item":"egg, beaten"}],"steps":["Mix flour, salt, sugar, yeast and milk to smooth dough. Refrigerate overnight.","Pound cold butter into 20cm square. Chill until same firmness as dough.","Roll dough, place butter in centre, fold over. Roll and fold into thirds. Chill 30 mins. Repeat 3 more times.","Roll to 5mm. Cut into long triangles. Roll from base to tip. Curve ends. Prove 2-3 hours.","Egg wash. Bake 190C 18-20 minutes until deep golden."],"tip":"Dough and butter must be same temperature — if butter breaks through, refrigerate immediately.","story":"Despite the French association, croissants originated in Vienna. The crescent shape mocks the Ottoman flag from a 1683 siege."}
,"Tonkatsu":{"name":"Tonkatsu","country":"Japan","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Tonkatsu-Schweineschnitzel_%28Japan%29.jpg/800px-Tonkatsu-Schweineschnitzel_%28Japan%29.jpg","description":"Japan's beloved breaded pork cutlet — thick pork loin in panko, fried to a shatteringly crisp golden crust with shredded cabbage and tonkatsu sauce.","prepTime":"15 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"pork loin cutlets, 2cm thick"},{"amount":"50g","item":"plain flour"},{"amount":"2","item":"eggs, beaten"},{"amount":"150g","item":"panko breadcrumbs"},{"amount":"oil","item":"for deep frying"},{"amount":"4 tbsp","item":"tonkatsu sauce"},{"amount":"quarter","item":"white cabbage, shredded"}],"steps":["Score fat edge of each cutlet. Season.","Coat each: flour, egg, panko, pressing firmly.","Deep fry at 170C for 6-7 minutes until golden.","Drain on a rack. Rest 2 minutes then slice.","Serve over cabbage with tonkatsu sauce."],"tip":"170C rather than high heat ensures pork cooks through before crust burns.","story":"Created in Tokyo in 1899, adapting the French pork cutlet using panko — creating something entirely Japanese."}
,"Miso Soup":{"name":"Miso Soup","country":"Japan","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Miso_Soup.jpg/800px-Miso_Soup.jpg","description":"Japan's daily ritual — pure dashi broth dissolved with white miso, silken tofu, wakame and spring onion. Simple, restorative and profound.","prepTime":"5 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"1L","item":"dashi stock"},{"amount":"3-4 tbsp","item":"white miso paste"},{"amount":"150g","item":"silken tofu, cubed"},{"amount":"2 tbsp","item":"dried wakame"},{"amount":"2","item":"spring onions, sliced"}],"steps":["Rehydrate wakame 5 minutes. Drain.","Heat dashi until just below simmering — never boil.","Place miso in ladle, lower into stock and whisk to dissolve.","Add tofu and wakame. Heat gently 1 minute.","Divide into bowls and top with spring onion."],"tip":"Never boil miso after adding — it destroys flavour and kills probiotic culture.","story":"Part of Japanese daily life since the 12th century. The traditional breakfast of miso soup, rice and pickles has been unchanged for 800 years."}
,"Okonomiyaki":{"name":"Okonomiyaki","country":"Japan","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Okonomiyaki_Okonomimura.jpg/800px-Okonomiyaki_Okonomimura.jpg","description":"Osaka's iconic savoury pancake — shredded cabbage batter with pork belly, topped with mayonnaise, okonomiyaki sauce and dancing bonito flakes.","prepTime":"15 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"200g","item":"plain flour"},{"amount":"200ml","item":"dashi stock"},{"amount":"4","item":"eggs"},{"amount":"600g","item":"white cabbage, very finely shredded"},{"amount":"200g","item":"pork belly, thinly sliced"},{"amount":"4 tbsp","item":"Japanese mayonnaise"},{"amount":"4 tbsp","item":"okonomiyaki sauce"},{"amount":"large handful","item":"bonito flakes"}],"steps":["Whisk flour, dashi and eggs. Rest 10 minutes. Fold in cabbage.","Heat oil in wide pan. Pour quarter of batter per pancake.","Lay pork belly over top. Cook 5 minutes until base is golden.","Flip carefully. Cook 5 more minutes.","Top with mayonnaise, sauce and bonito flakes."],"tip":"The bonito flakes dancing in heat signal the dish is properly hot.","story":"Okonomiyaki means cook what you like. Osaka and Hiroshima each claim their version as definitive."}
,"Chiles en Nogada":{"name":"Chiles en Nogada","country":"Mexico","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Chiles_en_nogada_02.jpg/800px-Chiles_en_nogada_02.jpg","description":"Mexico's most patriotic dish — poblano chillies stuffed with spiced meat and fruit, draped in walnut cream and scattered with pomegranate seeds.","prepTime":"1 hr","cookTime":"45 mins","serves":6,"difficulty":"Hard","ingredients":[{"amount":"6 large","item":"poblano chillies"},{"amount":"400g","item":"pork mince"},{"amount":"2","item":"peaches and 2 pears, diced"},{"amount":"50g","item":"raisins and 50g almonds"},{"amount":"1 tsp each","item":"cinnamon, cloves, pepper"},{"amount":"200g","item":"fresh walnuts"},{"amount":"200g","item":"cream cheese"},{"amount":"150ml","item":"double cream"},{"amount":"seeds of 1","item":"pomegranate"}],"steps":["Char poblanos, peel, slit and deseed.","Fry pork with fruit, raisins, almonds and spices 20 minutes. Cool.","Fill each chilli. Press closed.","Blend walnuts, cream cheese and cream until smooth.","Pour walnut sauce over chillies. Scatter pomegranate and parsley."],"tip":"Seasonal dish — best in August-September when walnuts and pomegranates are at peak.","story":"Created in 1821 by nuns in Puebla using the red, white and green of the new Mexican flag."}
,"Pozole":{"name":"Pozole Rojo","country":"Mexico","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Pozole_rojo.jpg/800px-Pozole_rojo.jpg","description":"Mexico's ancient feast soup — hominy corn and slow-cooked pork in a rich red chilli broth, piled with shredded cabbage and lime at the table.","prepTime":"20 mins","cookTime":"2 hrs","serves":8,"difficulty":"Medium","ingredients":[{"amount":"1kg","item":"pork shoulder, cubed"},{"amount":"800g","item":"tinned hominy corn"},{"amount":"4","item":"guajillo chillies, dried"},{"amount":"2","item":"ancho chillies, dried"},{"amount":"4","item":"garlic cloves"},{"amount":"to serve","item":"cabbage, radishes, lime, tostadas"}],"steps":["Simmer pork 1.5 hours. Shred. Reserve stock.","Toast chillies, soak, blend with garlic.","Strain into stock. Simmer 15 minutes.","Add hominy and pork. Simmer 20 minutes. Season.","Serve in deep bowls with garnishes at the table."],"tip":"Pozole is always better the next day — the broth deepens overnight.","story":"A sacred Aztec dish made for ceremonies. Hominy corn was considered sacred."}
,"Enchiladas":{"name":"Enchiladas Verdes","country":"Mexico","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Enchiladas.jpg/800px-Enchiladas.jpg","description":"Corn tortillas rolled around chicken and bathed in tangy tomatillo salsa verde, topped with crema and crumbled cheese.","prepTime":"30 mins","cookTime":"30 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"12","item":"corn tortillas"},{"amount":"400g","item":"cooked chicken, shredded"},{"amount":"500g","item":"fresh tomatillos"},{"amount":"2","item":"jalapeños"},{"amount":"150ml","item":"soured cream"},{"amount":"100g","item":"queso fresco or feta"}],"steps":["Boil tomatillos and jalapeños. Blend with onion, garlic, coriander.","Heat sauce until simmering.","Fry tortillas 10 seconds each side to soften.","Dip in sauce, fill with chicken, roll seam-down in dish.","Pour remaining sauce over. Top with crema and cheese."],"tip":"Frying tortillas briefly prevents them going soggy when sauced.","story":"Enchiladas date to pre-Columbian Mexico when Aztecs rolled corn tortillas around small fish."}
,"Dal Makhani":{"name":"Dal Makhani","country":"India","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Dal_makhani_in_a_bowl.jpg/800px-Dal_makhani_in_a_bowl.jpg","description":"Delhi's legendary overnight lentil dish — black lentils and kidney beans slow-cooked for hours with butter and cream until impossibly rich and silky.","prepTime":"20 mins","cookTime":"8 hrs","serves":6,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"whole black lentils, soaked overnight"},{"amount":"100g","item":"red kidney beans, soaked overnight"},{"amount":"2 large","item":"tomatoes, blended"},{"amount":"2","item":"onions, diced"},{"amount":"2 tbsp","item":"ginger-garlic paste"},{"amount":"1 tsp each","item":"cumin, coriander, garam masala, chilli"},{"amount":"80g","item":"butter"},{"amount":"150ml","item":"double cream"}],"steps":["Pressure cook lentils and beans until very soft. Mash roughly.","Fry onions in butter until deep golden. Add ginger-garlic paste.","Add tomatoes and spices. Cook 15 minutes.","Add lentils. Simmer on lowest heat 2+ hours.","Stir in butter and cream. Serve with naan."],"tip":"The long slow simmer is the secret — restaurant dal makhani is cooked overnight.","story":"Invented at Moti Mahal in Delhi in the 1950s by the same chef who created butter chicken."}
,"Palak Paneer":{"name":"Palak Paneer","country":"India","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Palak_paneer_%28FBIF%29.jpg/800px-Palak_paneer_%28FBIF%29.jpg","description":"Fresh paneer cheese in a vivid green spinach sauce fragrant with ginger, garlic and warm spices. One of India's most loved vegetarian dishes.","prepTime":"20 mins","cookTime":"25 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"fresh spinach"},{"amount":"250g","item":"paneer, cubed"},{"amount":"2 large","item":"tomatoes, chopped"},{"amount":"1 large","item":"onion, diced"},{"amount":"2 tbsp","item":"ginger-garlic paste"},{"amount":"1 tsp each","item":"cumin, coriander, garam masala, turmeric"},{"amount":"2 tbsp","item":"double cream"}],"steps":["Blanch spinach 2 minutes. Drain and blend smooth.","Fry paneer until golden. Remove.","Fry onion until golden. Add ginger-garlic paste and spices.","Add tomatoes and cook 10 minutes. Stir in spinach.","Add cream and paneer. Heat through gently."],"tip":"Cool spinach in ice water immediately after blanching to keep the vivid green colour.","story":"One of the dishes most responsible for popularising Indian vegetarian cuisine globally."}
,"Chana Masala":{"name":"Chana Masala","country":"India","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Chana_Masala.jpg/800px-Chana_Masala.jpg","description":"Punjab's bold chickpea curry — robust, tangy and deeply spiced. Street food royalty.","prepTime":"15 mins","cookTime":"35 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"2 x 400g tins","item":"chickpeas, drained"},{"amount":"2 large","item":"tomatoes, blended"},{"amount":"1 large","item":"onion, diced"},{"amount":"2 tbsp","item":"ginger-garlic paste"},{"amount":"1 tsp each","item":"cumin, coriander, turmeric, chilli"},{"amount":"2 tsp","item":"amchoor"},{"amount":"1 tsp","item":"garam masala"}],"steps":["Fry onion until deep golden. Add ginger-garlic paste.","Add dry spices. Stir 30 seconds.","Add tomatoes. Cook 10 minutes until thick.","Add chickpeas and water. Simmer 15 minutes.","Add garam masala and amchoor."],"tip":"Amchoor gives the characteristic sour tang — lemon juice works if unavailable.","story":"The signature dish of Punjabi street food, served with fluffy bhatura bread."}
,"Som Tum":{"name":"Som Tum","country":"Thailand","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Som_tam_1.jpg/800px-Som_tam_1.jpg","description":"Thailand's fiery green papaya salad — shredded unripe papaya pounded with chillies, lime and fish sauce. Explosive and addictive.","prepTime":"20 mins","cookTime":"0 mins","serves":2,"difficulty":"Easy","ingredients":[{"amount":"1 medium","item":"green papaya, shredded"},{"amount":"2-4","item":"bird's eye chillies"},{"amount":"2","item":"garlic cloves"},{"amount":"2 tbsp each","item":"fish sauce, lime juice"},{"amount":"1 tsp","item":"palm sugar"},{"amount":"6","item":"cherry tomatoes, halved"},{"amount":"2 tbsp","item":"roasted peanuts"}],"steps":["Pound chillies and garlic to rough paste.","Add papaya in batches, bruising not pulverising.","Add tomatoes, fish sauce, lime and sugar. Mix.","Taste and adjust — sour, salty, spicy, slightly sweet.","Top with peanuts. Serve with sticky rice."],"tip":"Bruising rather than pulverising keeps the papaya textured.","story":"Originated in Laos and northeast Thailand. Over 30 regional variations exist."}
,"Massaman Curry":{"name":"Massaman Curry","country":"Thailand","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Masaman_curry.jpg/800px-Masaman_curry.jpg","description":"Thailand's most complex curry — rich coconut sauce with beef, potatoes and peanuts, influenced by Persian traders. Voted the world's most delicious food.","prepTime":"20 mins","cookTime":"2 hrs","serves":4,"difficulty":"Medium","ingredients":[{"amount":"700g","item":"beef chuck, cubed"},{"amount":"400ml","item":"coconut milk"},{"amount":"3 tbsp","item":"massaman paste"},{"amount":"300g","item":"small potatoes"},{"amount":"100g","item":"roasted peanuts"},{"amount":"2 tbsp","item":"fish sauce"},{"amount":"1 tbsp","item":"palm sugar"},{"amount":"2 tbsp","item":"tamarind paste"}],"steps":["Fry paste in coconut cream 3 minutes.","Add beef. Add remaining coconut milk, cardamom and cinnamon.","Simmer covered 1 hour 30 minutes.","Add potatoes and onion. Cook 20 minutes.","Season with fish sauce, palm sugar and tamarind. Add peanuts."],"tip":"The longer you cook it the better — beef should be soft enough to cut with a spoon.","story":"Thailand's most Persian-influenced curry. The name likely derives from Mussulman, the Thai word for Muslim."}
,"Mango Sticky Rice":{"name":"Mango Sticky Rice","country":"Thailand","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Mango-sticky-rice.jpg/800px-Mango-sticky-rice.jpg","description":"Thailand's most beloved dessert — glutinous rice cooked in sweet coconut milk, served warm alongside ripe mango slices.","prepTime":"10 mins","cookTime":"30 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"glutinous rice, soaked 4 hours"},{"amount":"400ml","item":"coconut milk"},{"amount":"4 tbsp","item":"caster sugar"},{"amount":"1 tsp","item":"salt"},{"amount":"2 large","item":"ripe mangoes, sliced"},{"amount":"2 tbsp","item":"toasted sesame seeds"}],"steps":["Steam soaked rice 20-25 minutes until translucent.","Heat coconut milk with sugar and salt.","Pour most over hot rice. Cover and rest 15 minutes.","Reserve remaining as drizzle sauce.","Serve rice with fanned mango and coconut drizzle."],"tip":"Must use glutinous rice — regular rice will not work.","story":"Made only with seasonal mangoes. The Nam Dok Mai mango is considered the only proper variety."}
,"Cocido Madrileño":{"name":"Cocido Madrileño","country":"Spain","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Cocido_madrileno.jpg/800px-Cocido_madrileno.jpg","description":"Madrid's great chickpea stew — a three-course meal in one pot: first the broth as soup, then vegetables, then meats.","prepTime":"20 mins","cookTime":"3 hrs","serves":6,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"dried chickpeas, soaked overnight"},{"amount":"400g","item":"beef brisket"},{"amount":"200g","item":"serrano ham bone"},{"amount":"2","item":"morcilla and 2 chorizo"},{"amount":"3","item":"carrots and 3 potatoes"},{"amount":"quarter","item":"savoy cabbage"}],"steps":["Place chickpeas, beef and ham bone in pot with cold water. Bring slowly to boil. Skim.","Simmer covered 2 hours.","Add carrots, potatoes, chorizo and morcilla. Cook 30 minutes.","Wilt cabbage separately.","Serve in three courses: broth, then vegetables, then meats."],"tip":"Starting in cold water and heating slowly is essential for a clear rich broth.","story":"Evolved from a Jewish adafina stew. Madrid's defining dish — the Sunday meal that united all social classes."}
,"Dim Sum":{"name":"Dim Sum","country":"China","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/DimSumCarts.jpg/800px-DimSumCarts.jpg","description":"Cantonese yum cha — an endless procession of small steamed and fried dumplings, buns and rolls. The ultimate shared eating experience.","prepTime":"1 hr","cookTime":"20 mins","serves":4,"difficulty":"Hard","ingredients":[{"amount":"300g","item":"plain flour"},{"amount":"150ml","item":"boiling water"},{"amount":"300g","item":"pork mince"},{"amount":"200g","item":"raw prawns, chopped"},{"amount":"2 tbsp","item":"soy sauce"},{"amount":"1 tbsp","item":"sesame oil"},{"amount":"1 tsp","item":"fresh ginger, grated"},{"amount":"1 tbsp","item":"cornflour"}],"steps":["Mix flour with boiling then cold water to smooth dough. Rest 30 minutes.","Combine pork, prawns, soy, sesame oil, ginger and cornflour.","Roll dough thin. Cut circles. Add filling.","Pleat and seal. Steam over high heat 8-10 minutes.","Serve with soy and chilli oil."],"tip":"Boiling water partially cooks the starch creating the characteristic translucent wrapper.","story":"Developed as snacks in teahouses along the Silk Road. Today yum cha is a Cantonese Sunday institution."}
,"Hot Pot":{"name":"Hot Pot","country":"China","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Chongqing_Hot_Pot.jpg/800px-Chongqing_Hot_Pot.jpg","description":"China's most convivial meal — a bubbling spiced broth at the table with thinly sliced meats, vegetables and noodles cooked by diners themselves.","prepTime":"30 mins","cookTime":"30 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"2L","item":"chicken or beef stock"},{"amount":"4 tbsp","item":"doubanjiang"},{"amount":"2 tsp","item":"Sichuan peppercorns"},{"amount":"400g","item":"beef sirloin, paper thin"},{"amount":"200g","item":"tofu, cubed"},{"amount":"200g","item":"enoki mushrooms"},{"amount":"200g","item":"glass noodles"},{"amount":"sesame paste, soy, chilli oil","item":"for dipping"}],"steps":["Bring stock to boil. Add doubanjiang, Sichuan peppercorns and star anise. Simmer 20 minutes.","Place pot on portable burner at the table.","Each diner cooks their own ingredients — meat 10-30 seconds, tofu 2 minutes.","Dip into personal sesame and soy dipping sauces."],"tip":"Slice meat when partially frozen for paper-thin pieces.","story":"Eaten in China for 1000 years. The Sichuan fiery version became the most popular nationally."}
,"Chermoula Fish":{"name":"Chermoula Fish","country":"Morocco","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Grilled_fish_with_chermoula.jpg/800px-Grilled_fish_with_chermoula.jpg","description":"Morocco's classic fish preparation — whole fish marinated in a vivid herb and spice paste of coriander, cumin and lemon, grilled until fragrant.","prepTime":"20 mins","cookTime":"25 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"sea bass or bream fillets"},{"amount":"large bunch","item":"fresh coriander"},{"amount":"4","item":"garlic cloves"},{"amount":"2 tsp","item":"ground cumin"},{"amount":"1 tsp","item":"smoked paprika"},{"amount":"juice of 2","item":"lemons"},{"amount":"4 tbsp","item":"olive oil"}],"steps":["Blend all chermoula ingredients to a thick paste.","Score fish and rub chermoula all over. Marinate 30 minutes.","Grill over high heat or bake at 200C 20-25 minutes.","Serve with couscous and preserved lemon."],"tip":"Score fish deeply so chermoula penetrates into the flesh.","story":"Morocco's most versatile marinade — used for fish, chicken and vegetables. Every cook has their own version."}
,"Msemen":{"name":"Msemen","country":"Morocco","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Msemen_moroccan_flat_bread.jpg/800px-Msemen_moroccan_flat_bread.jpg","description":"Morocco's flaky griddle bread — folded and refolded to create layers, cooked until golden and crispy outside. Eaten with honey and argan oil for breakfast.","prepTime":"30 mins","cookTime":"20 mins","serves":8,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"plain flour"},{"amount":"100g","item":"fine semolina"},{"amount":"1 tsp","item":"salt"},{"amount":"7g","item":"fast-action yeast"},{"amount":"250ml","item":"warm water"},{"amount":"100g","item":"butter, softened"}],"steps":["Mix flour, semolina, salt and yeast. Add water and knead 10 minutes. Rest 30 minutes.","Divide into 8 balls. Flatten each very thinly, brush with butter.","Fold sides in to square. Fold again. Rest 10 minutes.","Flatten each square again gently.","Cook on dry griddle 3-4 minutes per side until golden."],"tip":"The more folds the more layers — three folds minimum for proper layering.","story":"Msemen is eaten throughout the Maghreb for breakfast with honey, jam or cheese."}
,"Coxinha":{"name":"Coxinha","country":"Brazil","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Coxinha_de_frango.jpg/800px-Coxinha_de_frango.jpg","description":"Brazil's most popular street snack — a teardrop-shaped croquette filled with shredded chicken and cream cheese, breaded and deep fried until golden.","prepTime":"45 mins","cookTime":"30 mins","serves":20,"difficulty":"Medium","ingredients":[{"amount":"500ml","item":"chicken stock"},{"amount":"300g","item":"plain flour"},{"amount":"1 tbsp","item":"butter"},{"amount":"400g","item":"cooked chicken, shredded"},{"amount":"150g","item":"cream cheese"},{"amount":"1","item":"onion, diced"},{"amount":"200g","item":"fine breadcrumbs"},{"amount":"oil","item":"for deep frying"}],"steps":["Bring stock and butter to boil. Add flour all at once. Stir until dough forms. Cool.","Mix chicken with cream cheese and fried onion. Season.","Flatten dough ball, fill, shape into teardrop.","Dip in egg then breadcrumbs.","Deep fry at 175C until deep golden, about 4 minutes."],"tip":"The dough must be completely cool before shaping or it tears.","story":"Coxinha means little thigh — originally shaped like a chicken thigh. Brazil's most beloved party snack."}
,"Bun Bo Hue":{"name":"Bun Bo Hue","country":"Vietnam","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/B%C3%BAn_B%C3%B2_Hu%E1%BA%BF.jpg/800px-B%C3%BAn_B%C3%B2_Hu%E1%BA%BF.jpg","description":"Hue's fiery imperial soup — a lemongrass and shrimp paste broth with thick noodles, sliced beef and pork. More complex and spicier than pho.","prepTime":"30 mins","cookTime":"3 hrs","serves":6,"difficulty":"Hard","ingredients":[{"amount":"1kg","item":"beef bones"},{"amount":"500g","item":"beef shank"},{"amount":"3 stalks","item":"lemongrass, bruised"},{"amount":"2 tbsp","item":"fermented shrimp paste"},{"amount":"2 tbsp","item":"annatto oil"},{"amount":"400g","item":"thick round rice noodles"}],"steps":["Blanch bones 5 minutes. Rinse. Simmer with lemongrass 2 hours.","Dissolve shrimp paste in broth. Add annatto oil and chilli.","Add beef shank and pork hock. Simmer 1 more hour.","Slice meats. Strain broth. Season.","Cook noodles. Add meat slices. Ladle hot broth over."],"tip":"Fermented shrimp paste is essential — there is no substitute for the authentic Hue flavour.","story":"Originated in the imperial city of Hue and remained a regional speciality until the 20th century."}
,"Banh Xeo":{"name":"Banh Xeo","country":"Vietnam","description":"Vietnam's sizzling crepe — a crispy turmeric rice flour pancake filled with prawns, pork and bean sprouts, wrapped in lettuce and dipped in nuoc cham.","prepTime":"20 mins","cookTime":"20 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"200g","item":"rice flour"},{"amount":"400ml","item":"coconut milk"},{"amount":"1 tsp","item":"turmeric"},{"amount":"200g","item":"raw prawns, peeled"},{"amount":"200g","item":"pork belly, sliced"},{"amount":"200g","item":"bean sprouts"},{"amount":"butter lettuce and herbs","item":"to serve"}],"steps":["Mix rice flour, coconut milk and turmeric. Rest 30 minutes.","Heat oil in wide pan until very hot. Add pork and prawns.","Add batter and swirl to coat pan.","Add bean sprouts. Cover 2 minutes.","Uncover and cook until edges are crispy. Fold in half.","Serve with lettuce and nuoc cham dipping sauce."],"tip":"The pan must be ripping hot — the name means sizzling cake.","story":"Thought to have been influenced by Indian dosas brought by traders. Different regions make markedly different versions."}
,"Cao Lau":{"name":"Cao Lau","country":"Vietnam","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Cao_lau.jpg/800px-Cao_lau.jpg","description":"Hoi An's unique noodle dish — thick chewy noodles with char siu pork, crispy croutons and a small amount of broth. Traditionally only authentic in Hoi An.","prepTime":"20 mins","cookTime":"20 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"thick udon noodles"},{"amount":"300g","item":"char siu pork, sliced"},{"amount":"4 tbsp","item":"soy sauce"},{"amount":"2 tbsp","item":"five spice powder"},{"amount":"2 tbsp","item":"hoisin sauce"},{"amount":"100g","item":"fried wonton strips"},{"amount":"bean sprouts, mint, basil","item":"to serve"}],"steps":["Marinate pork in soy, five spice and hoisin. Roast at 200C 25 minutes.","Cook noodles until just tender. Drain.","Toss noodles with annatto oil and a little hoisin.","Divide into bowls. Add sliced pork.","Top with bean sprouts, herbs and crispy croutons."],"tip":"Cao lau is almost dry — just enough sauce to coat the noodles, not a soup.","story":"Legend says authentic cao lau requires water from a specific ancient well in Hoi An. The dish has remained unchanged for centuries."}
,"Causa Rellena":{"name":"Causa Rellena","country":"Peru","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Causa_de_atun_o_papa_rellena.jpg/800px-Causa_de_atun_o_papa_rellena.jpg","description":"Peru's elegant cold potato terrine — layers of yellow potato mashed with aji amarillo and lime, filled with tuna salad and avocado.","prepTime":"30 mins","cookTime":"20 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1kg","item":"yellow potatoes, boiled and mashed"},{"amount":"3 tbsp","item":"aji amarillo paste"},{"amount":"juice of 2","item":"limes"},{"amount":"4 tbsp","item":"vegetable oil"},{"amount":"300g","item":"tinned tuna"},{"amount":"4 tbsp","item":"mayonnaise"},{"amount":"2","item":"avocados, sliced"}],"steps":["Mix warm mashed potato with aji amarillo, lime and oil. Season. Cool.","Mix tuna with mayonnaise, salt and pepper.","Line tin with cling film. Press half the potato as base.","Layer avocado then tuna.","Press remaining potato on top. Refrigerate 1 hour.","Unmould and slice. Serve cold."],"tip":"Season the potato mixture very assertively — it tastes bland when cold if under-seasoned.","story":"Causa dates to the Inca period. The name comes from the Quechua word kawsay meaning life."}
,"Anticuchos":{"name":"Anticuchos","country":"Peru","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Anticuchos_de_corazon.jpg/800px-Anticuchos_de_corazon.jpg","description":"Peru's beloved street food — beef heart marinated in aji panca and vinegar, skewered and grilled over charcoal. Smoky, rich and surprisingly delicious.","prepTime":"20 mins","cookTime":"10 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"beef heart, cleaned and cubed"},{"amount":"4 tbsp","item":"aji panca paste"},{"amount":"3 tbsp","item":"red wine vinegar"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"1 tsp each","item":"ground cumin, dried oregano"}],"steps":["Trim beef heart. Mix aji panca, vinegar, garlic, cumin and oregano.","Marinate heart at least 4 hours.","Thread onto skewers.","Grill over very high heat 2-3 minutes per side — charred outside, pink within.","Serve with boiled potato."],"tip":"Do not overcook — beef heart becomes tough when well done.","story":"Made by Africans enslaved in Lima using offcuts rejected by Spanish colonisers. Now one of Peru's most cherished street foods."}
,"Arroz con Leche":{"name":"Arroz con Leche","country":"Peru","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Arroz-con-leche.jpg/800px-Arroz-con-leche.jpg","description":"Peru's comforting rice pudding — short-grain rice slow-cooked in whole milk with cinnamon and sugar until creamy. Dusted with cinnamon.","prepTime":"5 mins","cookTime":"40 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"200g","item":"short-grain rice"},{"amount":"1L","item":"whole milk"},{"amount":"200ml","item":"condensed milk"},{"amount":"1","item":"cinnamon stick"},{"amount":"zest of 1","item":"orange"},{"amount":"1 tsp","item":"vanilla extract"},{"amount":"ground cinnamon","item":"for dusting"}],"steps":["Rinse rice. Cook with 300ml water and cinnamon until absorbed.","Add whole milk gradually, stirring constantly over medium-low heat.","Continue stirring 30-35 minutes until thick and creamy.","Stir in condensed milk, orange zest and vanilla. Cook 5 more minutes.","Serve warm or cold, dusted with cinnamon."],"tip":"Constant stirring releases starch and creates the creamy consistency.","story":"Brought to Peru by Spanish colonists. Now one of Latin America's most beloved desserts."}
,"Kitfo":{"name":"Kitfo","country":"Ethiopia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Kitfo.jpg/800px-Kitfo.jpg","description":"Ethiopia's steak tartare — very finely minced lean beef seasoned with mitmita spice and niter kibbeh, served raw or lightly warmed.","prepTime":"20 mins","cookTime":"5 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"very lean beef, finely minced"},{"amount":"3 tbsp","item":"niter kibbeh"},{"amount":"2 tsp","item":"mitmita spice blend"},{"amount":"1 tsp","item":"cardamom"},{"amount":"ayibe and gomen","item":"to serve"}],"steps":["Melt niter kibbeh. Add mitmita and cardamom. Remove from heat.","Mix warm spiced butter into minced beef. Season.","Serve raw (tere) or warm briefly 1-2 minutes (leb leb).","Accompany with injera, fresh white cheese and collard greens."],"tip":"The beef must be extremely fresh and very finely minced — ask butcher to mince twice.","story":"Considered the most prestigious Ethiopian dish, served at weddings and important celebrations."}
,"Shiro":{"name":"Shiro Wat","country":"Ethiopia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Shiro_wat.jpg/800px-Shiro_wat.jpg","description":"Ethiopia's silky chickpea powder stew — shiro flour whisked into spiced water to create a smooth rich sauce. The most common everyday dish in Ethiopia.","prepTime":"5 mins","cookTime":"20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"200g","item":"shiro powder (ground chickpeas with spices)"},{"amount":"600ml","item":"water"},{"amount":"1 large","item":"onion, very finely diced"},{"amount":"3 tbsp","item":"niter kibbeh or oil"},{"amount":"2","item":"garlic cloves, minced"}],"steps":["Fry onion in niter kibbeh until very soft and golden, 15 minutes.","Add garlic and ginger. Cook 2 minutes.","Add water and bring to simmer.","Whisk in shiro powder gradually to prevent lumps.","Simmer stirring 10-15 minutes until thick and smooth."],"tip":"Shiro powder is available at Ethiopian grocery stores. Cannot be substituted.","story":"The everyday food of Ethiopia. On Orthodox fasting days when meat is forbidden, shiro is the main protein source."}
,"Mercimek Çorbası":{"name":"Mercimek Çorbası","country":"Turkey","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Mercimek_%C3%A7orbas%C4%B1.jpg/800px-Mercimek_%C3%A7orbas%C4%B1.jpg","description":"Turkey's beloved red lentil soup — smooth and warming, finished with a sizzle of butter and dried mint. The soup every Turkish grandmother makes.","prepTime":"10 mins","cookTime":"30 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"split red lentils, rinsed"},{"amount":"1 large","item":"onion, diced"},{"amount":"2","item":"carrots, diced"},{"amount":"1 tsp each","item":"ground cumin, paprika"},{"amount":"1L","item":"stock"},{"amount":"3 tbsp","item":"butter"},{"amount":"1 tsp","item":"dried mint and red pepper flakes"}],"steps":["Soften onion and carrots 8 minutes. Add spices.","Add lentils and stock. Simmer 20 minutes.","Blend completely smooth. Adjust consistency and seasoning.","Ladle into bowls.","Brown butter, add dried mint and pepper flakes. Pour sizzling over each bowl."],"tip":"The sizzling butter poured over at the end is what makes this distinctively Turkish.","story":"Served at every Turkish breakfast table. A national comfort food eaten across all generations."}
,"Kimchi Jjigae":{"name":"Kimchi Jjigae","country":"South Korea","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Korean.food-Kimchi.jjigae-01.jpg/800px-Korean.food-Kimchi.jjigae-01.jpg","description":"Korea's most beloved stew — deeply fermented kimchi simmered with pork belly and tofu into a bubbling fiery sour broth.","prepTime":"10 mins","cookTime":"30 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"well-fermented kimchi"},{"amount":"200g","item":"pork belly, sliced"},{"amount":"200g","item":"firm tofu, cubed"},{"amount":"3 tbsp","item":"kimchi juice"},{"amount":"1 tbsp","item":"gochujang"},{"amount":"500ml","item":"stock"},{"amount":"2","item":"spring onions, sliced"}],"steps":["Fry pork belly until fat renders.","Add kimchi and juice. Stir fry 3 minutes.","Add gochujang and stock. Bring to boil.","Add tofu. Simmer 20 minutes.","Finish with sesame oil and spring onions. Serve over rice."],"tip":"Old well-fermented kimchi makes far better jjigae than fresh.","story":"Korea's most comforting dish — Koreans living abroad cite it as the first thing they crave when homesick."}
,"Shepherd's Pie":{"name":"Shepherd's Pie","country":"United Kingdom","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Shepherdspie.jpg/800px-Shepherdspie.jpg","description":"Britain's most comforting dish — minced lamb with carrots and herbs in rich gravy, topped with golden mashed potato and baked until bubbling.","prepTime":"25 mins","cookTime":"1 hr","serves":6,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"lamb mince"},{"amount":"2 each","item":"carrots and onions, diced"},{"amount":"2 tbsp","item":"tomato purée"},{"amount":"200ml","item":"beef stock"},{"amount":"2 tbsp","item":"Worcestershire sauce"},{"amount":"1kg","item":"Maris Piper potatoes"},{"amount":"80g","item":"butter"},{"amount":"4 tbsp","item":"warm milk"}],"steps":["Brown lamb. Soften onion and carrots. Return lamb.","Add tomato purée, stock and Worcestershire. Simmer 20 minutes.","Pour into baking dish.","Boil potatoes. Mash with butter and milk until smooth.","Spoon mash over. Rough up with fork. Bake 200C 25-30 minutes."],"tip":"Smooth buttery mash — stiff mash dries out rather than browning properly.","story":"Dates to the 18th century as a way to use leftover roasted meat."}
,"Provoleta":{"name":"Provoleta","country":"Argentina","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Provoleta.jpg/800px-Provoleta.jpg","description":"Argentina's irresistible grilled cheese — a thick round of provolone seasoned with oregano and chilli, grilled until golden and bubbling.","prepTime":"5 mins","cookTime":"8 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"provolone cheese, 2cm thick rounds"},{"amount":"2 tsp","item":"dried oregano"},{"amount":"1 tsp","item":"red chilli flakes"}],"steps":["Sprinkle one side with oregano and chilli.","Place herb side down on very hot cast-iron pan.","Cook without touching 3-4 minutes until golden crust forms.","Serve immediately with crusty bread."],"tip":"The pan must be very hot before adding cheese — lower heat makes it spread without forming a crust.","story":"Introduced by Italian immigrants and has become essential at every Argentine asado."}
,"Alfajores":{"name":"Alfajores","country":"Argentina","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Alfajores-de-maizena.jpg/800px-Alfajores-de-maizena.jpg","description":"Argentina's most beloved biscuit — two delicate cornstarch cookies sandwiched with thick dulce de leche and rolled in coconut.","prepTime":"30 mins","cookTime":"12 mins","serves":20,"difficulty":"Easy","ingredients":[{"amount":"200g each","item":"plain flour and cornstarch"},{"amount":"1 tsp","item":"baking powder"},{"amount":"100g each","item":"butter and icing sugar"},{"amount":"3","item":"egg yolks"},{"amount":"1 tsp","item":"vanilla"},{"amount":"400g","item":"dulce de leche"},{"amount":"100g","item":"desiccated coconut"}],"steps":["Beat butter and sugar until pale. Add egg yolks and vanilla.","Fold in flour and cornstarch. Chill dough 30 minutes.","Roll to 5mm. Cut 5cm rounds. Bake 180C 10-12 minutes — should remain pale.","Cool completely. Sandwich with dulce de leche.","Roll edges in coconut."],"tip":"Biscuits must remain pale — golden alfajores are overcooked and hard, not delicate.","story":"Arrived with Spanish colonists from Andalusia. Argentina has made them entirely their own."}
,"Jollof Rice":{"name":"Jollof Rice","country":"Nigeria","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Jollof_Rice.jpg/800px-Jollof_Rice.jpg","description":"West Africa's most contested dish — long grain rice cooked in rich tomato and pepper sauce until deeply flavoured and slightly smoky at the bottom.","prepTime":"20 mins","cookTime":"45 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"long grain rice, washed"},{"amount":"400g","item":"tinned tomatoes, blended"},{"amount":"2","item":"red peppers and 2 scotch bonnets, blended"},{"amount":"1 large","item":"onion, diced"},{"amount":"2 tbsp","item":"tomato purée"},{"amount":"400ml","item":"chicken stock"},{"amount":"1 tsp each","item":"curry powder, thyme"}],"steps":["Fry onion until golden. Add tomato purée and cook 3 minutes.","Add blended tomatoes and peppers. Fry over high heat 15-20 minutes until paste darkens.","Add stock, curry powder and thyme. Bring to boil. Season.","Add washed rice. Stir once. Cover tightly and cook on lowest heat 25-30 minutes.","The slightly caught bottom (party jollof) is prized."],"tip":"Do not lift the lid or stir — the steam and slight bottom catch give jollof its character.","story":"The great Jollof Wars between Nigeria, Ghana and Senegal rage on social media — each country passionately defends their version."}
,"Egusi Soup":{"name":"Egusi Soup","country":"Nigeria","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Egusi_soup.jpg/800px-Egusi_soup.jpg","description":"Nigeria's beloved melon seed soup — ground egusi seeds fried in palm oil with stockfish and leafy greens. Rich, earthy and deeply Nigerian.","prepTime":"20 mins","cookTime":"45 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"300g","item":"egusi (ground melon seeds)"},{"amount":"300g","item":"beef or goat, cooked"},{"amount":"100g","item":"stockfish, soaked and shredded"},{"amount":"4 tbsp","item":"palm oil"},{"amount":"2","item":"scotch bonnet chillies"},{"amount":"200g","item":"spinach or bitter leaf"}],"steps":["Blend chillies and onion. Fry in palm oil 5 minutes.","Mix egusi with water to form paste. Add to pot in lumps.","Fry egusi clumps without stirring 5 minutes.","Add beef, stockfish and stock. Simmer 20 minutes.","Add greens and cook 5 more minutes."],"tip":"Do not stir egusi when first added — letting it set in clumps is the traditional technique.","story":"Considered Nigeria's national dish, varying considerably between Yoruba, Igbo and other ethnic groups."}
,"Suya":{"name":"Suya","country":"Nigeria","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Suya.jpg/800px-Suya.jpg","description":"Nigeria's iconic street food — thinly sliced beef coated in spicy groundnut paste and grilled over open charcoal. Eaten wrapped in newspaper with raw onion.","prepTime":"20 mins","cookTime":"10 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"beef sirloin, cut thin"},{"amount":"100g","item":"roasted groundnuts, finely ground"},{"amount":"2 tsp each","item":"ground ginger, smoked paprika"},{"amount":"1 tsp each","item":"garlic powder, cayenne"},{"amount":"raw onion, tomato","item":"to serve"}],"steps":["Mix ground peanuts with all spices and oil to form paste.","Coat beef strips thoroughly in yaji spice mix.","Thread onto flat skewers.","Grill over very high charcoal heat 3-4 minutes per side.","Serve wrapped in paper with raw onion and tomato."],"tip":"Peanuts must be very finely ground — coarse peanuts burn before meat cooks.","story":"Originated with Hausa-Fulani cattle herders of northern Nigeria. The spice mix (yaji) varies by family."}
,"Nasi Goreng":{"name":"Nasi Goreng","country":"Indonesia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Nasi_goreng_best.jpg/800px-Nasi_goreng_best.jpg","description":"Indonesia's national dish — wok-fried rice with kecap manis, shrimp paste and chillies, topped with a fried egg and prawn crackers.","prepTime":"15 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"day-old cooked rice"},{"amount":"4","item":"eggs"},{"amount":"200g","item":"prawns or chicken"},{"amount":"3 tbsp","item":"kecap manis"},{"amount":"1 tbsp","item":"soy sauce"},{"amount":"1 tsp","item":"shrimp paste, toasted"},{"amount":"3","item":"garlic cloves and 3 shallots"},{"amount":"prawn crackers, cucumber","item":"to serve"}],"steps":["Fry shallots, garlic and chilli until fragrant. Add shrimp paste.","Add protein and cook through.","Add rice. Toss over highest heat breaking up clumps.","Add kecap manis and soy. Toss 2 minutes.","Fry eggs alongside with runny yolk.","Serve rice with fried egg on top."],"tip":"Day-old cold rice is essential — fresh rice becomes clumpy and steams rather than fries.","story":"Indonesia's national dish, eaten at every meal from street stalls to five-star hotels."}
,"Rendang":{"name":"Rendang","country":"Indonesia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Rendang.jpg/800px-Rendang.jpg","description":"The world's most flavourful dish — beef slow-cooked in coconut milk and complex spice paste for hours until almost dry and intensely caramelised.","prepTime":"30 mins","cookTime":"3-4 hrs","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1kg","item":"beef chuck, cubed"},{"amount":"800ml","item":"coconut milk"},{"amount":"4 stalks","item":"lemongrass, bruised"},{"amount":"8","item":"kaffir lime leaves"},{"amount":"6","item":"dried red chillies"},{"amount":"6 shallots and 4 garlic cloves","item":"blended to paste"},{"amount":"1 tsp each","item":"coriander, cumin, turmeric"}],"steps":["Blend chillies, shallots and garlic. Fry paste 5 minutes.","Add dry spices. Add beef. Add coconut milk and aromatics.","Simmer uncovered 3-4 hours, stirring increasingly often as liquid reduces.","Ready when almost dry and deep brown."],"tip":"Patience to cook 3-4 hours without rushing is the only skill required.","story":"Originated with the Minangkabau people of West Sumatra for weddings. The drying process also preserved it — rendang keeps for weeks."}
,"Satay":{"name":"Satay","country":"Indonesia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Indonesian_peanut_sauce.jpg/800px-Indonesian_peanut_sauce.jpg","description":"Southeast Asia's most beloved street food — skewered marinated meat grilled over charcoal, served with rich peanut sauce.","prepTime":"20 mins","cookTime":"10 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"chicken thighs, boneless"},{"amount":"3 tbsp","item":"kecap manis"},{"amount":"1 tsp each","item":"coriander, turmeric"},{"amount":"200g","item":"smooth peanut butter"},{"amount":"200ml","item":"coconut milk"},{"amount":"1 tbsp","item":"lime juice"}],"steps":["Marinate chicken in kecap manis, oil, garlic and spices 1 hour.","Thread onto soaked bamboo skewers.","Grill over hot charcoal 3-4 minutes per side, basting.","Make peanut sauce: heat peanut butter, coconut milk and kecap manis. Add lime and chilli.","Serve with warm peanut sauce and cucumber."],"tip":"Soak bamboo skewers 30 minutes before grilling or they catch fire.","story":"Derived from Indian kebab via Arab and Indian traders. Became the defining street food of Indonesia, Malaysia and Singapore."}
,"Gado-Gado":{"name":"Gado-Gado","country":"Indonesia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Gado-gado_Betawi.jpg/800px-Gado-gado_Betawi.jpg","description":"Indonesia's great salad — a colourful array of vegetables, tofu and egg dressed in rich peanut sauce. Indonesia's national salad.","prepTime":"20 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"200g each","item":"firm tofu and tempeh, fried"},{"amount":"2","item":"hard-boiled eggs, halved"},{"amount":"200g","item":"green beans and cabbage, blanched"},{"amount":"2","item":"potatoes, boiled and sliced"},{"amount":"1","item":"cucumber, sliced"},{"amount":"200g","item":"smooth peanut butter"},{"amount":"200ml","item":"coconut milk"},{"amount":"2 tbsp","item":"kecap manis"}],"steps":["Fry tofu and tempeh. Blanch vegetables and cool.","Make peanut sauce: blend peanut butter, coconut milk and kecap manis. Heat gently.","Arrange all vegetables, tofu, tempeh and egg on a platter.","Pour peanut sauce generously over.","Serve with prawn crackers."],"tip":"Peanut sauce should be thick enough to coat but still pourable — add water to adjust.","story":"Gado-gado means mix-mix in Indonesian. Every region has its own version."}
,"Soto Ayam":{"name":"Soto Ayam","country":"Indonesia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Soto_ayam_Indonesian.jpg/800px-Soto_ayam_Indonesian.jpg","description":"Indonesia's golden chicken soup — turmeric-yellow broth fragrant with lemongrass, served with shredded chicken, glass noodles and crispy shallots.","prepTime":"20 mins","cookTime":"45 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"1","item":"whole chicken"},{"amount":"3 stalks","item":"lemongrass, bruised"},{"amount":"4 slices","item":"galangal"},{"amount":"1 tsp","item":"turmeric"},{"amount":"4","item":"shallots, fried crispy"},{"amount":"200g","item":"glass noodles"},{"amount":"bean sprouts, lime, sambal","item":"to serve"}],"steps":["Simmer chicken with lemongrass, galangal and turmeric 40 minutes.","Remove chicken, cool and shred. Strain broth.","Cook glass noodles separately.","Divide noodles and chicken into bowls. Ladle hot broth over.","Top with crispy shallots. Serve with lime and sambal."],"tip":"Crispy fried shallots are essential — they provide crunch and sweetness that balances the broth.","story":"Soto is a class of Indonesian soups with regional versions across the archipelago."}
,"Martabak":{"name":"Martabak","country":"Indonesia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Martabak_Manis.jpg/800px-Martabak_Manis.jpg","description":"Indonesia's ultimate street treat — a thick fluffy pancake with a crispy butter-fried bottom, filled with chocolate, cheese and condensed milk.","prepTime":"15 mins","cookTime":"15 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"300g","item":"plain flour"},{"amount":"1 tsp","item":"baking powder"},{"amount":"7g","item":"yeast"},{"amount":"300ml","item":"warm water"},{"amount":"4 tbsp","item":"butter"},{"amount":"chocolate sprinkles, grated cheese, condensed milk","item":"for filling"}],"steps":["Mix flour, baking powder, yeast and water. Rest 30 minutes until bubbly.","Heat heavy pan over medium heat. Add butter.","Pour batter 1cm deep. Cover and cook 5 minutes until holes appear.","When top is dry, sprinkle generously with all fillings.","Fold in half. Remove and butter outside immediately."],"tip":"Condensed milk and butter must go on while still hot for the characteristic sticky sweetness.","story":"Indonesia's most popular street dessert, sold from carts that appear every evening at 5pm across the country."}
,"Meat Pie":{"name":"Meat Pie","country":"Australia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Meat_pie_with_sauce.jpg/800px-Meat_pie_with_sauce.jpg","description":"Australia's national food — a hand-held puff pastry pie filled with minced beef in thick gravy. Eaten with tomato sauce at the footy.","prepTime":"20 mins","cookTime":"45 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"beef mince"},{"amount":"1 large","item":"onion, diced"},{"amount":"2 tbsp","item":"plain flour"},{"amount":"300ml","item":"beef stock"},{"amount":"2 tbsp","item":"Worcestershire sauce"},{"amount":"400g","item":"shortcrust pastry"},{"amount":"400g","item":"puff pastry"}],"steps":["Brown mince. Soften onion. Stir in flour.","Add stock and Worcestershire. Simmer 15 minutes. Cool.","Line pie tins with shortcrust. Fill with cold beef mixture.","Top with puff pastry. Seal and score. Egg wash.","Bake 200C 25-30 minutes until deep golden.","Serve with tomato sauce."],"tip":"Filling must be cold before adding to pastry or the bottom becomes soggy.","story":"260 million meat pies are eaten in Australia every year — about 12 per person."}
,"Barramundi":{"name":"Pan-Fried Barramundi","country":"Australia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Barramundi_fish.jpg/800px-Barramundi_fish.jpg","description":"Australia's greatest native fish — barramundi pan-fried skin-side down until the skin is impossibly crispy, with lemon butter and macadamia salsa.","prepTime":"15 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"barramundi fillets, skin on"},{"amount":"2 tbsp","item":"olive oil"},{"amount":"50g","item":"butter"},{"amount":"juice of 1","item":"lemon"},{"amount":"50g","item":"macadamia nuts, chopped"},{"amount":"1","item":"long red chilli, sliced"},{"amount":"small bunch","item":"coriander"}],"steps":["Pat skin very dry. Season with salt.","Heat oil until very hot. Place fish skin-side down. Press firmly 30 seconds.","Cook skin-side down 5-6 minutes without touching.","Flip. Cook 2 more minutes.","Toast macadamias. Add butter, lemon and chilli.","Serve fish skin-side up with macadamia butter."],"tip":"Pressing fish down for 30 seconds ensures full contact with the heat for maximum crispiness.","story":"Its name comes from the Aboriginal Rockhampton language meaning large-scaled river fish."}
,"Lamington":{"name":"Lamington","country":"Australia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Lamingtons.jpg/800px-Lamingtons.jpg","description":"Australia's national cake — squares of vanilla sponge dipped in chocolate icing and rolled in desiccated coconut. Found at every school fête.","prepTime":"30 mins","cookTime":"25 mins","serves":16,"difficulty":"Medium","ingredients":[{"amount":"200g","item":"self-raising flour"},{"amount":"200g","item":"caster sugar"},{"amount":"100g","item":"butter"},{"amount":"3","item":"eggs"},{"amount":"120ml","item":"milk"},{"amount":"300g","item":"icing sugar and 50g cocoa (icing)"},{"amount":"200g","item":"desiccated coconut"}],"steps":["Beat butter and sugar. Add eggs. Fold in flour and milk.","Bake 20x30cm tin 180C 25 minutes. Cool and refrigerate overnight.","Cut into 16 squares.","Mix icing sugar, cocoa and boiling water until smooth.","Dip each square in chocolate icing then roll in coconut."],"tip":"The sponge must be a day old and cold — fresh warm cake crumbles in the icing.","story":"Named after Lord Lamington, Governor of Queensland 1896-1901. Australia's national cake ever since."}
,"Pavlova":{"name":"Pavlova","country":"Australia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Pavlova-with-strawberries.jpg/800px-Pavlova-with-strawberries.jpg","description":"The great Antipodean dessert — a vast meringue with a marshmallow centre, piled with whipped cream and fresh fruit. Both Australia and New Zealand claim it.","prepTime":"20 mins","cookTime":"1 hr 15 mins","serves":10,"difficulty":"Medium","ingredients":[{"amount":"6","item":"egg whites, room temperature"},{"amount":"300g","item":"caster sugar"},{"amount":"2 tsp","item":"cornflour"},{"amount":"1 tsp","item":"white wine vinegar"},{"amount":"400ml","item":"double cream, whipped"},{"amount":"fresh strawberries, kiwi, passionfruit","item":"to top"}],"steps":["Beat egg whites to stiff peaks. Gradually add sugar until very stiff and glossy.","Fold in cornflour, vinegar and vanilla.","Spread on baking paper circle with slightly sunken centre.","Bake 120C for 1 hour 15 minutes. Leave inside oven to cool completely.","Top with whipped cream and fresh fruit just before serving."],"tip":"Vinegar and cornflour are essential — they create the marshmallow centre that distinguishes pavlova from ordinary meringue.","story":"Named after Russian ballerina Anna Pavlova during her 1926 tour. Both Australia and New Zealand claim the invention."}
,"Koshari":{"name":"Koshari","country":"Egypt","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Kushari.jpg/800px-Kushari.jpg","description":"Egypt's national dish and greatest street food — layers of rice, lentils, macaroni and crispy onions, drenched in spiced tomato sauce and garlic vinegar.","prepTime":"20 mins","cookTime":"45 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"200g each","item":"brown lentils, short grain rice, macaroni"},{"amount":"3 large","item":"onions, thinly sliced, deep fried"},{"amount":"400g","item":"tinned tomatoes, blended"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"2 tbsp","item":"red wine vinegar"},{"amount":"1 tsp each","item":"cumin, coriander, cinnamon, cayenne"}],"steps":["Deep fry onions until dark golden and crispy. Drain.","Cook lentils, rice and macaroni separately.","Make tomato sauce: fry garlic, add tomatoes and spices. Simmer 15 minutes. Add vinegar.","Layer in bowls: rice and lentils, then macaroni, then tomato sauce.","Top with crispy onions."],"tip":"The crispy fried onions are the crown of koshari — make more than you think you need.","story":"Evolved in 19th-century Egypt combining elements from Italian, Indian and Middle Eastern communities."}
,"Ful Medames":{"name":"Ful Medames","country":"Egypt","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Foul-Mudammas.jpg/800px-Foul-Mudammas.jpg","description":"Egypt's ancient breakfast — slow-cooked fava beans with olive oil, lemon, cumin and garlic. Eaten since the time of the pharaohs.","prepTime":"10 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"2 x 400g tins","item":"fava or broad beans"},{"amount":"4 tbsp","item":"extra virgin olive oil"},{"amount":"juice of 2","item":"lemons"},{"amount":"4","item":"garlic cloves, minced"},{"amount":"1 tsp","item":"ground cumin"},{"amount":"pitta, parsley, tomato","item":"to serve"}],"steps":["Heat beans with a splash of water over medium heat.","Mash roughly — half beans, leave rest whole.","Stir in oil, lemon, garlic and cumin. Season.","Heat through. Serve drizzled with extra oil, with pitta."],"tip":"The combination of mashed and whole beans is traditional — gives both texture and creaminess.","story":"Has been eaten in Egypt for over 4000 years — the most ancient dish still eaten daily today."}
,"Molokhia":{"name":"Molokhia","country":"Egypt","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Molokhia.jpg/800px-Molokhia.jpg","description":"Egypt's beloved green soup — finely chopped molokhia leaves in chicken broth with a sizzling garlic and coriander ta'lia poured over.","prepTime":"15 mins","cookTime":"20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"fresh or frozen molokhia leaves, chopped"},{"amount":"1L","item":"chicken stock"},{"amount":"6","item":"garlic cloves, finely minced"},{"amount":"1 tbsp","item":"ground coriander"},{"amount":"4 tbsp","item":"butter or ghee"},{"amount":"cooked chicken and rice","item":"to serve"}],"steps":["Bring chicken stock to boil.","Add molokhia. Simmer 5 minutes.","Make ta'lia: fry garlic in butter until golden. Add coriander. Sizzle 30 seconds.","Pour sizzling ta'lia into soup. Add vinegar.","Serve immediately over rice with chicken."],"tip":"The ta'lia must be added at the last moment and served immediately — molokhia loses its green colour quickly.","story":"Molokhia has been eaten in Egypt since ancient times. A Fatimid Caliph banned it, reportedly causing riots in Cairo."}
,"Beef Stroganoff":{"name":"Beef Stroganoff","country":"Russia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Beef_stroganoff.jpg/800px-Beef_stroganoff.jpg","description":"Russia's great export — strips of tender beef with mushrooms in a soured cream sauce. Simple, rich and deeply satisfying over egg noodles.","prepTime":"15 mins","cookTime":"20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"beef sirloin, thin strips"},{"amount":"300g","item":"chestnut mushrooms, sliced"},{"amount":"1 large","item":"onion, thinly sliced"},{"amount":"2 tbsp","item":"Dijon mustard"},{"amount":"200ml","item":"beef stock"},{"amount":"200ml","item":"soured cream"},{"amount":"egg noodles","item":"to serve"}],"steps":["Sear beef in very hot butter in small batches — 1 minute per side. Remove.","Fry onion until golden. Add mushrooms until liquid evaporates.","Add mustard. Pour in stock. Simmer 5 minutes.","Remove from heat. Stir in soured cream.","Return beef. Heat gently — never boil. Serve with noodles and dill."],"tip":"Sear beef in tiny batches over very high heat — crowding causes steaming not searing.","story":"Created for Count Pavel Stroganov of St Petersburg in the 19th century. Appeared in a Russian cookbook in 1861."}
,"Borscht":{"name":"Borscht","country":"Russia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Borscht_Ukrainian_style.JPG/800px-Borscht_Ukrainian_style.JPG","description":"Eastern Europe's greatest soup — a vivid crimson broth of beetroot, cabbage and beef. Served with soured cream and rye bread.","prepTime":"20 mins","cookTime":"1 hr 30 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"beef brisket, cubed"},{"amount":"3 large","item":"beetroots, grated"},{"amount":"quarter","item":"white cabbage, shredded"},{"amount":"3","item":"carrots, grated"},{"amount":"3","item":"medium potatoes, diced"},{"amount":"400g","item":"tinned tomatoes"},{"amount":"3 tbsp","item":"red wine vinegar"},{"amount":"soured cream, dill, rye bread","item":"to serve"}],"steps":["Brown beef. Add 2L water. Simmer 1 hour.","Add potatoes, carrots and onion. Cook 15 minutes.","Add cabbage, tomatoes and beetroot. Cook 20 more minutes.","Season with vinegar, salt and sugar — sweet, sour and savoury balance is key.","Serve with soured cream and fresh dill."],"tip":"Vinegar and sugar are essential — without this balance it is just beetroot soup.","story":"Ukraine considers it a national symbol — UNESCO recognised Ukrainian borscht in 2022."}
,"Pelmeni":{"name":"Pelmeni","country":"Russia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Pelmeni_with_sour_cream.jpg/800px-Pelmeni_with_sour_cream.jpg","description":"Russia's beloved dumplings — thin dough wrapped around spiced pork and beef, boiled and served with soured cream. The food of Siberian winters.","prepTime":"1 hr","cookTime":"10 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"plain flour"},{"amount":"2","item":"eggs"},{"amount":"150ml","item":"water"},{"amount":"300g","item":"pork mince"},{"amount":"200g","item":"beef mince"},{"amount":"1 large","item":"onion, finely grated"},{"amount":"1 tsp","item":"black pepper"},{"amount":"soured cream, butter, dill","item":"to serve"}],"steps":["Make dough from flour, eggs and water. Rest 30 minutes.","Mix pork and beef with grated onion and pepper. Season.","Roll dough thinly. Cut circles. Fill and seal by pinching edges.","Press the two ends together to create traditional shape.","Boil in salted water 8-10 minutes until they float and dough is cooked.","Toss with butter. Serve with soured cream and dill."],"tip":"The grated onion keeps the meat moist and flavourful inside the dumpling.","story":"Originated in Siberia where they were frozen outside in winter and stored for months."}
,"Bobotie":{"name":"Bobotie","country":"South Africa","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Bobotie_2.jpg/800px-Bobotie_2.jpg","description":"South Africa's national dish — spiced minced beef with apricot jam, baked with a savoury egg custard topping. Cape Malay cooking at its finest.","prepTime":"20 mins","cookTime":"45 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"beef mince"},{"amount":"2 large","item":"onions, diced"},{"amount":"2 tbsp","item":"curry powder"},{"amount":"2 tbsp","item":"apricot jam"},{"amount":"50g","item":"raisins and 50g flaked almonds"},{"amount":"3 slices","item":"bread soaked in milk"},{"amount":"3","item":"eggs"},{"amount":"250ml","item":"milk"},{"amount":"bay leaves","item":"for topping"}],"steps":["Fry onion until golden. Add mince and brown.","Add curry, jam, raisins and almonds. Season.","Squeeze bread and mix into meat. Pour into dish.","Beat eggs with milk. Pour over meat. Lay bay leaves on top.","Bake 180C 30-35 minutes until custard just set.","Serve with yellow rice and chutney."],"tip":"Bread soaked in milk lightens the mixture and keeps it moist.","story":"Arrived with Cape Malay slaves from Southeast Asia in the 17th century. Synonymous with South African cuisine."}
,"Bunny Chow":{"name":"Bunny Chow","country":"South Africa","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Durban_Bunny_Chow.jpg/800px-Durban_Bunny_Chow.jpg","description":"Durban's iconic street food — a hollowed-out quarter loaf filled with lamb or bean curry. Eaten by hand, always.","prepTime":"15 mins","cookTime":"45 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"600g","item":"lamb shoulder, cubed"},{"amount":"2 large","item":"onions, diced"},{"amount":"3 tbsp","item":"Durban curry powder"},{"amount":"2","item":"tomatoes, chopped"},{"amount":"3","item":"potatoes, cubed"},{"amount":"1 loaf","item":"unsliced white bread"}],"steps":["Fry onions in oil. Add curry powder and cook 2 minutes.","Add lamb and brown. Add tomatoes and potatoes.","Add water. Simmer 35-40 minutes until tender.","Cut loaf into quarters. Hollow out each quarter.","Fill generously with hot curry. Place bread lid on top."],"tip":"The bread is part of the eating — use it to scoop curry as you eat down through the loaf.","story":"Created in Durban in the 1940s by Indian workers as a convenient way to carry curry to work."}
,"Braai":{"name":"Braai","country":"South Africa","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Braai_South_Africa.jpg/800px-Braai_South_Africa.jpg","description":"South Africa's sacred barbecue — a social institution built around an open wood fire, with boerewors, lamb chops and pap. More ritual than meal.","prepTime":"30 mins","cookTime":"1 hr","serves":8,"difficulty":"Medium","ingredients":[{"amount":"1kg","item":"boerewors sausage"},{"amount":"8","item":"lamb chops"},{"amount":"coarse sea salt","item":"only seasoning"},{"amount":"400g","item":"mealie meal (coarse cornmeal)"},{"amount":"600ml","item":"water"},{"amount":"tomato relish and chakalaka","item":"to serve"}],"steps":["Build wood fire and burn down to glowing coals — 45 minutes.","Make pap: boil salted water, add mealie meal stirring. Simmer on low 30 minutes until thick.","Season meat only with coarse salt.","Grill boerewors as a coil. Cook lamb chops alongside.","Turn meat once only.","Serve with pap, tomato relish and chakalaka."],"tip":"A braai is built around conversation and patience — the fire and the time are part of the ritual.","story":"South Africa's most important social institution, transcending all racial and cultural divisions."}
,"Bandeja Paisa":{"name":"Bandeja Paisa","country":"Colombia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Bandeja_paisa.jpg/800px-Bandeja_paisa.jpg","description":"Colombia's most epic meal — a platter of red beans, rice, ground beef, chicharrón, fried egg, sweet plantain, avocado and arepa. Everything at once.","prepTime":"30 mins","cookTime":"1 hr","serves":4,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"dried red beans, cooked"},{"amount":"200g","item":"pork belly, for chicharrón"},{"amount":"400g","item":"ground beef, seasoned"},{"amount":"4","item":"eggs"},{"amount":"2","item":"ripe plantains, sliced and fried"},{"amount":"2","item":"avocados and 4 arepas"}],"steps":["Simmer beans with onion and garlic 1.5 hours.","Fry pork belly pieces in their own fat until crispy.","Brown ground beef with onion and tomatoes.","Fry plantains until golden. Fry eggs sunny side up.","Arrange everything generously on large plates."],"tip":"The beauty of bandeja paisa is abundance — everything should overflow.","story":"Originates from Antioquia region. Colombia's most recognisable dish internationally."}
,"Ajiaco":{"name":"Ajiaco","country":"Colombia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Ajiaco_bogotano.jpg/800px-Ajiaco_bogotano.jpg","description":"Bogotá's great cold-weather soup — three varieties of potato with chicken and guascas herb in a thick warming broth.","prepTime":"20 mins","cookTime":"1 hr","serves":6,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"chicken pieces, bone-in"},{"amount":"300g each","item":"papa criolla, papa pastusa, papa sabanera"},{"amount":"2 tbsp","item":"dried guascas herb"},{"amount":"3 stalks","item":"spring onion"},{"amount":"small bunch","item":"fresh coriander"},{"amount":"double cream and capers","item":"to serve"}],"steps":["Simmer chicken with spring onion and coriander in 2L water 30 minutes.","Remove chicken. Shred meat. Reserve stock.","Add all three potato varieties to stock. Simmer 30 minutes.","Add guascas. Return shredded chicken. Season generously.","Serve with cream and capers stirred in at the table."],"tip":"The three different potato varieties are essential — each plays a different role in the broth.","story":"Considered Bogotá's signature dish. The guascas herb is essential and gives ajiaco its unique flavour."}
,"Sancocho":{"name":"Sancocho","country":"Colombia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Sancocho_colombiano.jpg/800px-Sancocho_colombiano.jpg","description":"Colombia's great healing soup — chicken, plantain, yuca and corn in a fragrant herb broth. The Sunday family meal and the cure for everything.","prepTime":"20 mins","cookTime":"1 hr","serves":8,"difficulty":"Easy","ingredients":[{"amount":"1 whole","item":"chicken, cut into pieces"},{"amount":"2","item":"green plantains, chunked"},{"amount":"400g","item":"yuca (cassava), cubed"},{"amount":"2","item":"corn cobs, cut into rounds"},{"amount":"2","item":"potatoes, cubed"},{"amount":"small bunch","item":"fresh coriander and green onion"},{"amount":"white rice, avocado, lime","item":"to serve"}],"steps":["Simmer chicken with onion, garlic and coriander in cold water. Bring to boil 20 minutes.","Remove chicken and shred.","Add plantain and yuca to broth. Cook 20 minutes.","Add corn and potatoes. Cook 15 more minutes.","Return chicken. Season generously.","Serve with rice, avocado and lime."],"tip":"The broth is as important as the ingredients — golden, fragrant and deeply flavoured.","story":"Eaten across Latin America. In Colombia it is the Sunday dish that families gather for."}
,"Buñuelos":{"name":"Buñuelos","country":"Colombia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Bunuelos.jpg/800px-Bunuelos.jpg","description":"Colombia's favourite Christmas fritter — crispy fried dough balls made with cheese and yuca starch, golden outside and hollow within.","prepTime":"20 mins","cookTime":"15 mins","serves":20,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"fresh white cheese, grated"},{"amount":"200g","item":"yuca starch"},{"amount":"2","item":"eggs"},{"amount":"1 tbsp","item":"sugar"},{"amount":"oil","item":"for deep frying"}],"steps":["Mix cheese, yuca starch, eggs and sugar to smooth dough.","Roll into walnut-sized balls.","Deep fry at 170C turning constantly until golden and puffed, about 5 minutes.","They should be hollow inside with thin crispy shell."],"tip":"Low frying temperature is essential — high heat prevents the hollow centre from forming.","story":"Eaten exclusively at Christmas in Colombia. The tradition dates to colonial times."}
,"Pierogi":{"name":"Pierogi","country":"Poland","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Pierogi_with_potato-and-cheese_filling.jpg/800px-Pierogi_with_potato-and-cheese_filling.jpg","description":"Poland's national comfort food — half-moon dumplings stuffed with potato and cheese, boiled then fried in butter with onions until golden.","prepTime":"1 hr","cookTime":"20 mins","serves":30,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"plain flour"},{"amount":"1 egg and 200ml warm water","item":"for dough"},{"amount":"600g","item":"potatoes, boiled and mashed"},{"amount":"200g","item":"farmer's cheese"},{"amount":"2 large","item":"onions, caramelised"},{"amount":"butter and soured cream","item":"to serve"}],"steps":["Make dough from flour, egg and water. Rest 30 minutes.","Mix mashed potato with cheese and half the caramelised onion. Season.","Roll dough thin. Cut circles. Place filling off-centre. Fold and press edges.","Boil in salted water until they float plus 2 minutes.","Pan-fry in butter until golden on both sides.","Serve with remaining onion and soured cream."],"tip":"Pan-frying after boiling is essential — boiled pierogi alone lack the golden crust.","story":"Made in Poland since the 13th century. Eaten at Christmas, Easter and whenever Poles feel homesick."}
,"Bigos":{"name":"Bigos","country":"Poland","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Bigos_pot.jpg/800px-Bigos_pot.jpg","description":"Poland's hunter's stew — sauerkraut and fresh cabbage slow-cooked with multiple meats for days until deeply complex. Gets better with every reheating.","prepTime":"30 mins","cookTime":"3 hrs","serves":8,"difficulty":"Easy","ingredients":[{"amount":"500g each","item":"sauerkraut and fresh cabbage"},{"amount":"300g","item":"pork shoulder, cubed"},{"amount":"200g","item":"kielbasa sausage"},{"amount":"200g","item":"smoked bacon"},{"amount":"30g","item":"dried porcini mushrooms, soaked"},{"amount":"200ml","item":"red wine"},{"amount":"2 tbsp","item":"tomato purée"}],"steps":["Brown all meats in batches.","Combine sauerkraut, fresh cabbage, meats, mushrooms and their liquid.","Add wine, tomato purée, bay leaves and allspice. Cover and simmer 2-3 hours.","Season. Reheat the next day — bigos is always better reheated."],"tip":"Must be made at least a day ahead. Traditional recipes call for reheating three times over three days.","story":"Poland's national dish since the 14th century — hunters made it from whatever game and leftovers were available."}
,"Kotlet Schabowy":{"name":"Kotlet Schabowy","country":"Poland","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Kotlet_schabowy.jpg/800px-Kotlet_schabowy.jpg","description":"Poland's beloved breaded pork cutlet — pork loin pounded thin, breaded and pan-fried until golden. The cornerstone of the Polish dinner table.","prepTime":"15 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"pork loin chops"},{"amount":"100g","item":"plain flour"},{"amount":"3","item":"eggs, beaten"},{"amount":"200g","item":"fine breadcrumbs"},{"amount":"lard or oil","item":"for frying"},{"amount":"boiled potatoes, sauerkraut","item":"to serve"}],"steps":["Pound pork to 5mm thickness.","Season. Coat in flour, then egg, then breadcrumbs, pressing firmly.","Fry in lard over medium-high heat 3-4 minutes per side until deep golden.","Drain briefly and serve immediately with potatoes and sauerkraut."],"tip":"Lard gives kotlet schabowy its distinctive flavour that vegetable oil cannot replicate.","story":"The dish most associated with Polish home cooking. Origins disputed between Polish and German (Schnitzel) traditions."}
,"Sernik":{"name":"Sernik","country":"Poland","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Sernik_z_rodzynkami.jpg/800px-Sernik_z_rodzynkami.jpg","description":"Poland's beloved cheesecake — made with twaróg (fresh farmer's cheese) rather than cream cheese, giving it a lighter, grainier texture.","prepTime":"20 mins","cookTime":"1 hr","serves":10,"difficulty":"Medium","ingredients":[{"amount":"1kg","item":"twaróg (Polish farmer's cheese) or dry-curd cottage cheese"},{"amount":"200g","item":"caster sugar"},{"amount":"5","item":"eggs, separated"},{"amount":"100g","item":"butter, softened"},{"amount":"3 tbsp","item":"plain flour"},{"amount":"zest of 1","item":"lemon"},{"amount":"1 tsp","item":"vanilla extract"},{"amount":"50g","item":"raisins"}],"steps":["Press twaróg through a sieve or blend smooth.","Beat butter and sugar. Beat in egg yolks.","Mix in cheese, flour, lemon zest, vanilla and raisins.","Beat egg whites to stiff peaks. Fold into cheese mixture.","Bake 160C 55-60 minutes until just set.","Cool in oven with door ajar to prevent cracking."],"tip":"Sernik must cool slowly in the oven — dramatic temperature changes cause cracking.","story":"Made in Poland since the 17th century using local twaróg cheese. Every grandmother has her own definitive recipe."}
,"Bacalhau à Brás":{"name":"Bacalhau à Brás","country":"Portugal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Bacalhau_a_Bras.jpg/800px-Bacalhau_a_Bras.jpg","description":"Portugal's most beloved salt cod dish — shredded bacalhau scrambled with eggs, straw potatoes and olives. One of 365 ways to cook bacalhau.","prepTime":"30 mins","cookTime":"20 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"salt cod, soaked 24-48 hours, shredded"},{"amount":"4 large","item":"eggs, beaten"},{"amount":"2 large","item":"onions, thinly sliced"},{"amount":"200g","item":"straw potatoes (thin crisps)"},{"amount":"black olives and parsley","item":"to finish"},{"amount":"4 tbsp","item":"olive oil"}],"steps":["Fry onion in olive oil until golden and soft, 15 minutes.","Add shredded cod. Cook 3 minutes.","Add beaten eggs. Stir gently over low heat until just set — very softly scrambled.","Remove from heat. Fold in straw potatoes.","Top with olives and parsley."],"tip":"The eggs must be only lightly scrambled — overcooked eggs make this dish dry and heavy.","story":"Portugal has 365 recipes for bacalhau — one for every day of the year."}
,"Caldo Verde":{"name":"Caldo Verde","country":"Portugal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Caldo_verde.jpg/800px-Caldo_verde.jpg","description":"Portugal's most comforting soup — a silky potato broth with fine ribbons of kale and slices of chouriço. The soup of Portuguese weddings and festivals.","prepTime":"15 mins","cookTime":"35 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"floury potatoes, diced"},{"amount":"1 large","item":"onion and 3 garlic cloves"},{"amount":"300g","item":"Portuguese kale or savoy cabbage, very finely shredded"},{"amount":"200g","item":"chouriço sausage, sliced"},{"amount":"1.5L","item":"water or stock"}],"steps":["Fry onion and garlic in olive oil. Add potatoes and water.","Simmer 20 minutes until potatoes are very soft.","Blend until completely smooth and thick.","Add very finely shredded kale. Simmer 5 minutes.","Add chouriço and heat through. Season. Drizzle with olive oil."],"tip":"The kale must be shredded as finely as possible — fine ribbons are characteristic of authentic caldo verde.","story":"Considered Portugal's national soup, served at all major celebrations. The Minho region is its birthplace."}
,"Pastéis de Nata":{"name":"Pastéis de Nata","country":"Portugal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Pastel_de_nata.jpg/800px-Pastel_de_nata.jpg","description":"Lisbon's legendary custard tarts — flaky puff pastry cases filled with rich egg custard, blistered until caramelised and spotted brown.","prepTime":"30 mins","cookTime":"15 mins","serves":12,"difficulty":"Medium","ingredients":[{"amount":"500g","item":"puff pastry"},{"amount":"6","item":"egg yolks"},{"amount":"200g","item":"caster sugar"},{"amount":"30g","item":"plain flour"},{"amount":"500ml","item":"whole milk"},{"amount":"1","item":"cinnamon stick"},{"amount":"cinnamon and icing sugar","item":"to dust"}],"steps":["Make custard: whisk sugar and flour. Whisk in milk. Cook stirring until thick. Beat in egg yolks. Cool.","Roll puff pastry into a log. Slice into 2cm rounds. Press into tart tins forming cups.","Fill with cold custard.","Bake at maximum oven temperature (250C+) 12-15 minutes until blistered.","Dust with cinnamon and icing sugar."],"tip":"The oven must be at maximum temperature — the blistered tops only form at very high heat.","story":"Created by monks at the Jerónimos Monastery in Belém in the 18th century. The original recipe remains secret."}
,"Sauerbraten":{"name":"Sauerbraten","country":"Germany","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Sauerbraten.jpg/800px-Sauerbraten.jpg","description":"Germany's national pot roast — beef marinated for days in vinegar and wine, braised until tender in its own sweet-sour gravy.","prepTime":"30 mins plus 3 days","cookTime":"3 hrs","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1.5kg","item":"beef top round, tied"},{"amount":"500ml each","item":"red wine vinegar, red wine, water"},{"amount":"2 each","item":"onions, carrots, sliced"},{"amount":"10","item":"peppercorns, 4 bay leaves, 6 cloves"},{"amount":"50g","item":"gingerbread, crumbled"},{"amount":"2 tbsp","item":"sugar"}],"steps":["Combine vinegar, wine, water, vegetables and spices. Marinate beef 3-5 days.","Brown beef on all sides.","Strain marinade. Pour over beef. Add gingerbread.","Braise covered 160C 2.5-3 hours until tender.","Remove beef. Blend sauce. Add sugar and season."],"tip":"The gingerbread is essential — it thickens and sweetens the sauce giving sauerbraten its distinctive character.","story":"Dates to medieval Germany when vinegar marination was used to tenderise tough older cattle."}
,"Currywurst":{"name":"Currywurst","country":"Germany","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Currywurst_with_fries.jpg/800px-Currywurst_with_fries.jpg","description":"Berlin's iconic street food — steamed then fried pork sausage smothered in curried ketchup. The post-club food of a generation.","prepTime":"5 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"bratwurst or pork sausages"},{"amount":"300ml","item":"ketchup"},{"amount":"2 tsp","item":"curry powder"},{"amount":"1 tsp","item":"paprika"},{"amount":"half tsp","item":"cayenne"},{"amount":"chips","item":"to serve"}],"steps":["Steam sausages 5 minutes then fry in oil until golden and crispy.","Mix ketchup with curry powder, paprika and cayenne. Heat gently.","Slice sausages into bite-sized pieces. Pour hot curry sauce over.","Serve with chips."],"tip":"Steam before frying — this keeps it juicy inside while crisping the outside.","story":"Invented in Berlin in 1949 by Herta Heuwer using ketchup and curry powder from British soldiers. Berlin alone sells 70 million currywurst per year."}
,"Kartoffelsuppe":{"name":"Kartoffelsuppe","country":"Germany","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Kartoffelsuppe.jpg/800px-Kartoffelsuppe.jpg","description":"Germany's great potato soup — a thick warming soup of potatoes, leeks and celeriac with crispy bacon. Humble and deeply satisfying.","prepTime":"15 mins","cookTime":"35 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"800g","item":"floury potatoes, diced"},{"amount":"2","item":"leeks, sliced"},{"amount":"1 large","item":"onion, diced"},{"amount":"1.2L","item":"chicken or vegetable stock"},{"amount":"200g","item":"smoked bacon, diced"},{"amount":"150ml","item":"soured cream"},{"amount":"fresh chives","item":"to finish"}],"steps":["Fry bacon until crispy. Remove. Fry onion and leek in bacon fat 8 minutes.","Add potatoes and stock. Simmer 25 minutes.","Blend half the soup. Return for thick-but-textured consistency.","Stir in soured cream. Season generously.","Serve topped with crispy bacon and chives."],"tip":"Blending only half gives the ideal texture — creamy but with potato chunks remaining.","story":"Germany's most popular soup since potatoes were adopted as a staple crop in the 18th century."}
,"Schnitzel":{"name":"Wiener Schnitzel","country":"Germany","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Wiener_Schnitzel_01.jpg/800px-Wiener_Schnitzel_01.jpg","description":"The definitive breaded cutlet — veal pounded paper thin, breaded and pan-fried in clarified butter until golden. One of the world's perfect dishes.","prepTime":"15 mins","cookTime":"5 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"4","item":"veal escalopes (or pork loin chops)"},{"amount":"100g","item":"plain flour"},{"amount":"3","item":"eggs, beaten"},{"amount":"200g","item":"fine breadcrumbs"},{"amount":"150g","item":"clarified butter or lard"},{"amount":"lemon wedges and parsley","item":"to serve"}],"steps":["Pound veal to 3-4mm thickness.","Season. Coat in flour, egg then breadcrumbs.","Heat clarified butter. Fry 2 minutes per side — gently shaking the pan.","Drain briefly. Serve immediately with lemon and parsley."],"tip":"The schnitzel must float in butter and be kept moving — this creates the characteristic puffed breadcrumb texture.","story":"The definitive version is Austrian but Germany adopted it as its own. Now one of the world's most recognised dishes."}
,"Bratwurst":{"name":"Bratwurst","country":"Germany","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Grilled_bratwurst.jpg/800px-Grilled_bratwurst.jpg","description":"Germany's greatest sausage — pork and veal with marjoram and nutmeg, grilled until blistered and juicy. Eaten in a roll with mustard at the Christmas market.","prepTime":"5 mins","cookTime":"15 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"8","item":"fresh bratwurst sausages"},{"amount":"4","item":"crusty bread rolls"},{"amount":"German mustard","item":"to serve"}],"steps":["Grill bratwurst over medium charcoal or cast-iron pan with no added fat.","Turn every 2 minutes until evenly browned all over, about 12-15 minutes.","Do not pierce — all juices must remain inside.","Serve in a split roll with generous mustard."],"tip":"Never pierce a bratwurst before or during cooking — it releases all the juices.","story":"Made in Germany since the 14th century. Nuremberg and Thuringian versions are the most famous regional varieties."}
,"Black Forest Cake":{"name":"Black Forest Cake","country":"Germany","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Schwarzw%C3%A4lder_Kirschtorte_--_2021_--_0001.jpg/800px-Schwarzw%C3%A4lder_Kirschtorte_--_2021_--_0001.jpg","description":"Germany's most famous cake — layers of chocolate sponge soaked in Kirsch, sandwiched with cream and cherries, covered in chocolate shavings.","prepTime":"45 mins","cookTime":"35 mins","serves":12,"difficulty":"Medium","ingredients":[{"amount":"200g","item":"dark chocolate, melted"},{"amount":"200g","item":"caster sugar"},{"amount":"6","item":"eggs"},{"amount":"100g each","item":"plain flour and cocoa"},{"amount":"4 tbsp","item":"Kirsch"},{"amount":"400g","item":"tinned pitted cherries"},{"amount":"600ml","item":"double cream, whipped"},{"amount":"dark chocolate shavings","item":"to decorate"}],"steps":["Beat eggs and sugar until pale. Fold in flour, cocoa and chocolate.","Bake 23cm tin 180C 30-35 minutes. Cool and slice into 3 layers.","Soak each layer with Kirsch.","Sandwich with whipped cream and cherries.","Cover with cream. Decorate with cream rosettes, cherries and chocolate shavings."],"tip":"The Kirsch soak is non-negotiable — without it the cake is just chocolate layer cake.","story":"Takes its name from the Black Forest region of Baden-Württemberg and its famous Kirsch cherry brandy."}
,"Vegemite Toast":{"name":"Vegemite on Toast","country":"Australia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Vegemite_on_toast.jpg/800px-Vegemite_on_toast.jpg","description":"Australia's national breakfast — thick toast spread with butter and just enough Vegemite. The first food every Australian child loves and every visitor struggles with.","prepTime":"5 mins","cookTime":"2 mins","serves":2,"difficulty":"Easy","ingredients":[{"amount":"4 thick slices","item":"sourdough or white bread"},{"amount":"generous knob","item":"salted butter"},{"amount":"half to 1 tsp","item":"Vegemite per slice"}],"steps":["Toast bread until golden.","Spread with generous butter while hot — it must melt into the toast.","Spread a thin layer of Vegemite over the butter.","Eat immediately while hot."],"tip":"Vegemite must go on top of butter, never instead of it. Less is more.","story":"Created in Melbourne in 1922 using leftover brewer's yeast. Australia sells 22 million jars annually."}
,"Anzac Biscuits":{"name":"Anzac Biscuits","country":"Australia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Anzac_biscuits.jpg/800px-Anzac_biscuits.jpg","description":"Australia's most patriotic biscuit — oats, coconut and golden syrup baked until golden and chewy. Made to send to ANZACs during WWI.","prepTime":"15 mins","cookTime":"12 mins","serves":24,"difficulty":"Easy","ingredients":[{"amount":"100g","item":"rolled oats"},{"amount":"75g","item":"plain flour"},{"amount":"150g","item":"caster sugar"},{"amount":"60g","item":"desiccated coconut"},{"amount":"125g","item":"butter"},{"amount":"2 tbsp","item":"golden syrup"},{"amount":"1 tsp","item":"bicarbonate of soda"},{"amount":"2 tbsp","item":"boiling water"}],"steps":["Mix oats, flour, sugar and coconut.","Melt butter with golden syrup.","Mix bicarb with boiling water. Add to butter mixture — it foams.","Pour butter mixture into dry ingredients. Mix well.","Roll into balls. Flatten slightly. Bake 160C 10-12 minutes until golden.","They firm as they cool — remove while still soft."],"tip":"Remove while still soft and golden — overbaked Anzacs are hard, not chewy.","story":"Made by women and sent to soldiers during WWI. The recipe has not changed since 1915."}
,"Hawawshi":{"name":"Hawawshi","country":"Egypt","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Hawawshi.jpg/800px-Hawawshi.jpg","description":"Egypt's beloved spiced meat pastry — minced beef mixed with onions and spices, stuffed into bread and baked until crispy. Cairo street food.","prepTime":"20 mins","cookTime":"25 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"beef or lamb mince"},{"amount":"2 large","item":"onions, very finely diced"},{"amount":"2","item":"green peppers and 2 tomatoes, finely diced"},{"amount":"1 tsp each","item":"cumin, coriander, allspice, cayenne"},{"amount":"4","item":"small round bread rolls or pitta"}],"steps":["Mix mince with all vegetables, spices and parsley. Season generously.","Slit bread rolls open without cutting through.","Fill generously with meat mixture. Wrap in foil.","Bake 200C 20-25 minutes.","Open foil for last 5 minutes to crisp the bread."],"tip":"Vegetables must be very finely diced — large pieces stay raw inside the bread.","story":"Named after the butcher who first made it in Cairo. Now one of Egypt's most popular street foods."}
,"Om Ali":{"name":"Om Ali","country":"Egypt","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Om_Ali.jpg/800px-Om_Ali.jpg","description":"Egypt's national dessert — layers of flaky pastry and nuts baked in rich sweetened milk and cream until bubbling and golden. The Middle East's bread and butter pudding.","prepTime":"15 mins","cookTime":"20 mins","serves":8,"difficulty":"Easy","ingredients":[{"amount":"400g","item":"puff pastry, baked and broken into pieces"},{"amount":"500ml","item":"whole milk"},{"amount":"200ml","item":"double cream"},{"amount":"100g","item":"caster sugar"},{"amount":"50g each","item":"coconut, raisins, almonds, pistachios"},{"amount":"1 tsp","item":"vanilla"}],"steps":["Break baked pastry into rough pieces in a baking dish.","Scatter coconut, raisins and nuts over.","Heat milk, cream, sugar and vanilla until dissolved. Pour over pastry.","Bake 200C 15-20 minutes until top is golden and bubbling.","Serve hot."],"tip":"Pastry must already be baked and crispy before adding liquid — raw pastry won't produce the right texture.","story":"Named after a legendary Egyptian woman. Served at celebrations and funerals alike."}
,"Shashlik":{"name":"Shashlik","country":"Russia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Shashlik_on_skewers.jpg/800px-Shashlik_on_skewers.jpg","description":"Russia's summer ritual — lamb marinated in onion and vinegar, skewered and grilled over birch charcoal. The Soviet-era barbecue that united all republics.","prepTime":"20 mins plus overnight","cookTime":"15 mins","serves":6,"difficulty":"Easy","ingredients":[{"amount":"1.2kg","item":"lamb shoulder, cubed"},{"amount":"4 large","item":"onions (2 grated, 2 sliced into rings)"},{"amount":"4 tbsp","item":"red wine vinegar"},{"amount":"1 tsp each","item":"black pepper, coriander seeds"}],"steps":["Grate 2 onions. Mix with vinegar and spices. Marinate lamb overnight.","Thread onto flat metal skewers alternating with onion rings.","Grill over very hot charcoal 12-15 minutes, turning constantly.","Serve with lavash bread, raw onion and pomegranate seeds."],"tip":"The grated onion marinade tenderises the lamb without the harshness of lemon juice.","story":"Spread across the Soviet Union from the Caucasus. The smell of shashlik smoke in a summer park is an instantly recognisable Soviet memory."}
,"Boerewors":{"name":"Boerewors","country":"South Africa","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Boerewors.jpg/800px-Boerewors.jpg","description":"South Africa's iconic farmer's sausage — coarsely minced beef and pork with coriander and cloves in a long continuous coil. The centrepiece of every braai.","prepTime":"30 mins","cookTime":"15 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"700g","item":"beef mince (coarsely ground)"},{"amount":"300g","item":"pork belly mince"},{"amount":"2 tsp","item":"coriander, toasted"},{"amount":"half tsp each","item":"cloves, nutmeg, allspice"},{"amount":"2 tbsp","item":"red wine vinegar"},{"amount":"natural sausage casings","item":"soaked"}],"steps":["Mix beef and pork with all spices and vinegar. Refrigerate 1 hour.","Stuff into casings forming one long continuous coil.","Do not twist or separate — boerewors must remain in one coil.","Grill over medium charcoal 12-15 minutes, turning carefully."],"tip":"Do not pierce and keep as one coil — breaking it is bad braai etiquette.","story":"By South African law must contain at least 90% meat with specific spice requirements. No boerewors, no braai."}
,"Melktert":{"name":"Melktert","country":"South Africa","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Melktert.jpg/800px-Melktert.jpg","description":"South Africa's beloved milk tart — a silky smooth milk custard in sweet pastry, generously dusted with cinnamon. A national treasure.","prepTime":"20 mins","cookTime":"35 mins","serves":8,"difficulty":"Easy","ingredients":[{"amount":"200g","item":"plain flour and 100g butter (pastry)"},{"amount":"50g","item":"icing sugar"},{"amount":"500ml","item":"whole milk"},{"amount":"3 tbsp each","item":"caster sugar, cornflour"},{"amount":"2","item":"eggs"},{"amount":"1 tsp","item":"vanilla"},{"amount":"ground cinnamon","item":"for dusting"}],"steps":["Make pastry: rub butter into flour and sugar. Add egg yolk and water. Chill 30 minutes.","Press into 23cm tin. Blind bake 180C 15 minutes.","Heat milk with sugar. Whisk cornflour with eggs. Pour hot milk over egg mixture stirring. Return to heat until thick.","Pour into tart case. Cool. Dust with cinnamon."],"tip":"Strain filling through a sieve before pouring if needed — any lumps ruin the delicate texture.","story":"Brought to the Cape by Dutch settlers in the 17th century. One of South Africa's most universally loved desserts."}
,"Vetkoek":{"name":"Vetkoek","country":"South Africa","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Vetkoek.jpg/800px-Vetkoek.jpg","description":"South Africa's comforting fried bread — golden deep-fried dough balls split open and filled with spiced mince. Street food and school tuck shop staple.","prepTime":"1 hr","cookTime":"20 mins","serves":12,"difficulty":"Easy","ingredients":[{"amount":"500g","item":"plain flour"},{"amount":"10g","item":"instant yeast"},{"amount":"300ml","item":"warm water"},{"amount":"oil","item":"for deep frying"},{"amount":"400g","item":"beef mince"},{"amount":"1","item":"onion, diced"},{"amount":"2 tsp","item":"curry powder"},{"amount":"2 tbsp","item":"chutney"}],"steps":["Mix flour, yeast, salt and sugar. Add water and knead 10 minutes. Prove 1 hour.","Divide into 12 balls. Rest 10 minutes.","Deep fry at 175C until deep golden and cooked through, about 6 minutes.","Brown mince with onion, curry powder and chutney.","Split vetkoek. Fill with mince."],"tip":"Oil temperature is crucial — too hot burns outside before inside cooks.","story":"Vetkoek means fat cake in Afrikaans. Beloved as school tuck shop food and at markets across South Africa."}
,"Feteer Meshaltet":{"name":"Feteer Meshaltet","country":"Egypt","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Feteer_Meshaltet.jpg/800px-Feteer_Meshaltet.jpg","description":"Egypt's extraordinary layered pastry — thin sheets of dough folded and refolded with butter, baked until flaky and golden. Eaten sweet with honey or savoury with cheese.","prepTime":"45 mins","cookTime":"20 mins","serves":8,"difficulty":"Hard","ingredients":[{"amount":"500g","item":"plain flour"},{"amount":"1 tsp","item":"salt"},{"amount":"250ml","item":"warm water"},{"amount":"200g","item":"butter or ghee, melted"},{"amount":"honey or white cheese","item":"to serve"}],"steps":["Mix flour, salt and water to a very smooth, pliable dough. Rest 30 minutes.","Divide into 4 balls. On an oiled surface, stretch each ball as thin as possible — almost transparent.","Brush generously with melted butter. Fold into thirds, brush again. Fold into thirds again.","Stack two folded layers on a buttered baking tray. Repeat with remaining layers.","Bake 200C 20-25 minutes until deeply golden and crispy.","Tear apart and eat with honey or white cheese."],"tip":"The dough must be stretched as thin as possible — it should be almost see-through for maximum layers.","story":"Feteer meshaltet is Egypt's version of French mille-feuille, dating back centuries. Specialist feteer shops sell nothing else and pull and stretch the dough with extraordinary skill."}
,"Puff Puff":{"name":"Puff Puff","country":"Nigeria","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Puff_Puff.jpg/800px-Puff_Puff.jpg","description":"Nigeria's beloved fried dough balls — fluffy, slightly sweet and golden, eaten as street food, party snacks and children's treats across West Africa.","prepTime":"1 hr","cookTime":"15 mins","serves":30,"difficulty":"Easy","ingredients":[{"amount":"300g","item":"plain flour"},{"amount":"2 tsp","item":"instant yeast"},{"amount":"3 tbsp","item":"caster sugar"},{"amount":"pinch","item":"salt"},{"amount":"pinch","item":"ground nutmeg"},{"amount":"250ml","item":"warm water"},{"amount":"oil","item":"for deep frying"}],"steps":["Mix flour, yeast, sugar, salt and nutmeg. Add warm water and mix to thick batter.","Rest 45 minutes-1 hour until doubled and very bubbly.","Heat oil to 170C. Using wet hands or a spoon, drop golf-ball sized portions into oil.","Fry 3-4 minutes turning until dark golden on all sides.","Drain on paper and eat while warm."],"tip":"The batter must be well-risen and very bubbly before frying — under-proved puff puff are dense rather than fluffy.","story":"Puff puff is found across West Africa under various names. In Nigeria it is the first thing made at every celebration, from church gatherings to birthday parties."}
,"Banga Soup":{"name":"Banga Soup","country":"Nigeria","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Banga_soup.jpg/800px-Banga_soup.jpg","description":"Nigeria's rich palm nut soup — a thick, orangey broth made from palm nut extract with fresh fish, leafy greens and the distinctive banga spice. A Delta State classic.","prepTime":"30 mins","cookTime":"45 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"800g","item":"tinned palm nut cream or 400g fresh palm nuts"},{"amount":"400g","item":"fresh fish or smoked fish"},{"amount":"100g","item":"stockfish, soaked"},{"amount":"1","item":"onion, diced"},{"amount":"2","item":"scotch bonnet chillies"},{"amount":"2 tsp","item":"banga spice (oburunbebe stick, dried atariko)"},{"amount":"200g","item":"spinach or bitterleaf"},{"amount":"salt","item":"to taste"}],"steps":["If using fresh palm nuts, boil and pound to extract the creamy pulp. Strain.","Bring palm nut cream to boil in a pot.","Add fish, stockfish, onion and chillies. Simmer 20 minutes.","Add banga spice. Simmer 15 more minutes.","Add leafy greens and cook 5 minutes. Season with salt.","Serve with eba (pounded cassava) or white rice."],"tip":"The banga spice is essential — it gives the soup its distinctive aromatic character that distinguishes it from regular palm nut soup.","story":"Banga soup is the signature dish of the Urhobo and Isoko peoples of Delta State, Nigeria. It is traditionally served at important ceremonies and celebrations."}
,"Moi Moi":{"name":"Moi Moi","country":"Nigeria","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Moi_Moi.jpg/800px-Moi_Moi.jpg","description":"Nigeria's beloved steamed bean pudding — black-eyed peas blended smooth with peppers and spices, steamed in leaves or foil until firm and fragrant. Eaten at breakfast and celebrations.","prepTime":"30 mins","cookTime":"45 mins","serves":8,"difficulty":"Medium","ingredients":[{"amount":"400g","item":"dried black-eyed peas, soaked overnight"},{"amount":"1 large","item":"onion, roughly chopped"},{"amount":"2","item":"red peppers, roughly chopped"},{"amount":"2","item":"scotch bonnet chillies (adjust to taste)"},{"amount":"4 tbsp","item":"vegetable oil"},{"amount":"1 tsp","item":"salt"},{"amount":"2","item":"stock cubes"},{"amount":"3","item":"hard-boiled eggs, halved (optional)"},{"amount":"banana leaves or foil","item":"for wrapping"}],"steps":["Peel soaked black-eyed peas by rubbing between hands. Rinse off skins.","Blend peeled beans with onion, peppers, chillies and a little water until very smooth.","Stir in oil, salt and crumbled stock cubes. Mix well.","Pour into banana leaf parcels or greased foil cups. Add half a boiled egg if using.","Steam for 40-45 minutes until firm and set.","Serve warm or at room temperature."],"tip":"Removing the bean skins before blending is essential for the smooth, custard-like texture. Do not skip this step.","story":"Moi moi is one of Nigeria's most versatile dishes — eaten at breakfast with akamu (porridge), as a side dish, or on its own as a snack. Every family has their own version."},"Francesinha":{"name":"Francesinha","country":"Portugal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Francesinha.jpg/800px-Francesinha.jpg","description":"Porto's legendary sandwich — layers of cured meats and steak between bread, smothered in melted cheese and a fiery beer and tomato sauce. Porto's proudest creation.","prepTime":"20 mins","cookTime":"30 mins","serves":4,"difficulty":"Medium","ingredients":[{"amount":"8 slices","item":"thick white bread"},{"amount":"400g","item":"beef steak, thinly sliced"},{"amount":"200g","item":"linguiça or chorizo, sliced"},{"amount":"200g","item":"cured ham, sliced"},{"amount":"200g","item":"cheese (edam or gouda), sliced"},{"amount":"330ml","item":"beer (lager)"},{"amount":"400g","item":"tinned tomatoes, blended"},{"amount":"1 tbsp","item":"whisky or brandy"},{"amount":"1 tbsp","item":"piri piri sauce"},{"amount":"1 tbsp","item":"butter"}],"steps":["Make sauce: fry onion and garlic in butter. Add tomatoes, beer, whisky and piri piri. Simmer 20 minutes until rich and slightly thick. Season.","Grill or pan-fry steak slices. Season.","Layer between bread: ham, linguiça, steak. Press top slice on.","Place sandwiches in an oven dish. Pour hot sauce generously over.","Cover entirely with cheese slices. Grill until cheese is completely melted and bubbling.","Serve immediately in the sauce with chips alongside."],"tip":"The sauce must be very hot when poured over — this starts the cheese melting from below before it goes under the grill.","story":"The Francesinha was invented in Porto in the 1950s by Daniel da Silva who adapted the croque monsieur after returning from working in France and Belgium. Porto considers it their greatest culinary achievement."}
,"Sardinhas Assadas":{"name":"Sardinhas Assadas","country":"Portugal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Sardinhas_assadas_-_grilled_sardines.jpg/800px-Sardinhas_assadas_-_grilled_sardines.jpg","description":"Portugal's most iconic summer dish — fresh sardines grilled whole over charcoal until charred and smoky, eaten with bread and peppers. The smell of Lisbon in June.","prepTime":"10 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"12 large","item":"fresh sardines, gutted"},{"amount":"coarse sea salt","item":"generous seasoning"},{"amount":"good olive oil","item":"for drizzling"},{"amount":"crusty bread","item":"to serve"},{"amount":"2","item":"roasted red peppers, sliced"},{"amount":"1","item":"lemon, cut into wedges"}],"steps":["Rinse sardines and pat dry. Do not scale — the scales protect the flesh on the grill.","Season very generously with coarse sea salt on both sides.","Grill over very hot charcoal 4-5 minutes per side until skin is charred and crispy.","Place on bread slices — the bread soaks up the delicious juices.","Drizzle with olive oil. Serve with roasted peppers and lemon."],"tip":"Do not scale the sardines before grilling — the scales act as a natural barrier that keeps the flesh moist and pulls away easily when eating.","story":"Sardinhas assadas are eaten throughout Portugal every June for the Festas dos Santos Populares — the popular saints festivals. The smell of grilling sardines wafting through Lisbon's streets is one of Portugal's most evocative sensory memories."}
,"Arroz de Pato":{"name":"Arroz de Pato","country":"Portugal","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Arroz_de_pato.jpg/800px-Arroz_de_pato.jpg","description":"Portugal's elegant duck rice — duck cooked until tender in wine and aromatics, then baked with its cooking rice and topped with crispy slices of chouriço.","prepTime":"20 mins","cookTime":"2 hrs","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1","item":"whole duck, jointed"},{"amount":"400g","item":"long grain rice"},{"amount":"200ml","item":"white wine"},{"amount":"1 large","item":"onion, diced"},{"amount":"4","item":"garlic cloves"},{"amount":"2","item":"bay leaves"},{"amount":"1 tsp","item":"dried thyme"},{"amount":"200g","item":"chouriço, sliced"},{"amount":"1L","item":"chicken stock"}],"steps":["Brown duck pieces well on all sides. Remove.","Fry onion and garlic until golden. Add wine and reduce by half.","Return duck. Add stock, bay leaves and thyme. Simmer covered 1 hour until tender.","Remove duck and shred meat. Reserve cooking liquid — measure it.","Use 2 parts liquid to 1 part rice. Bring to boil, add rice and shredded duck.","Transfer to baking dish. Top with chouriço slices. Bake 180°C 20-25 minutes until golden."],"tip":"The ratio of cooking liquid to rice is crucial — use exactly twice as much liquid as rice for perfectly cooked grains.","story":"Arroz de pato is one of Portugal's great comfort dishes, found in every tasca (traditional tavern) across the country. The crispy chouriço topping is the defining element that makes it Portuguese."}
,"Blini":{"name":"Blini","country":"Russia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Blinis.jpg/800px-Blinis.jpg","description":"Russia's delicate yeasted buckwheat pancakes — small, golden and slightly sour, traditionally topped with soured cream, smoked salmon or caviar. Eaten at Maslenitsa.","prepTime":"1 hr 30 mins","cookTime":"20 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"150g","item":"buckwheat flour"},{"amount":"100g","item":"plain flour"},{"amount":"7g","item":"fast-action yeast"},{"amount":"500ml","item":"warm milk"},{"amount":"2","item":"eggs, separated"},{"amount":"1 tsp","item":"salt"},{"amount":"1 tsp","item":"sugar"},{"amount":"butter","item":"for frying"},{"amount":"soured cream, smoked salmon, caviar","item":"to serve"}],"steps":["Mix flours, yeast, salt and sugar. Whisk in warm milk and egg yolks until smooth.","Rest in a warm place 1 hour until batter is bubbly and doubled.","Beat egg whites to stiff peaks. Fold gently into batter.","Heat a small buttered pan over medium heat. Pour small amounts of batter.","Cook 2 minutes until bubbles appear, flip, cook 1 more minute.","Serve immediately with soured cream and toppings."],"tip":"Folding the beaten egg whites in at the end is what makes blini light and airy rather than dense — do not skip this step.","story":"Blini are one of Russia's oldest foods, predating Christianity. They were traditionally round to symbolise the sun at Maslenitsa (Pancake Week), the pagan festival marking the end of winter."}
,"Olivier Salad":{"name":"Olivier Salad","country":"Russia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Olivier_salad.jpg/800px-Olivier_salad.jpg","description":"Russia's most beloved salad — diced potatoes, carrots, eggs, peas, pickles and chicken or bologna bound in mayonnaise. On every Russian New Year table.","prepTime":"30 mins","cookTime":"30 mins","serves":8,"difficulty":"Easy","ingredients":[{"amount":"4 large","item":"potatoes, boiled and diced"},{"amount":"3","item":"carrots, boiled and diced"},{"amount":"4","item":"eggs, hard-boiled and diced"},{"amount":"200g","item":"cooked chicken or bologna sausage, diced"},{"amount":"4","item":"large dill pickles (gherkins), diced"},{"amount":"200g","item":"frozen peas, thawed"},{"amount":"1 small","item":"onion, very finely diced"},{"amount":"300g","item":"good quality mayonnaise"},{"amount":"salt and pepper","item":"to taste"}],"steps":["Boil potatoes and carrots separately until just tender — not soft. Cool completely.","Dice all ingredients into small even 1cm cubes — uniformity matters.","Combine potatoes, carrots, eggs, chicken, pickles, peas and onion.","Add mayonnaise and mix gently. Season generously.","Refrigerate at least 2 hours — overnight is better.","Serve cold, mounded in a bowl."],"tip":"All ingredients must be cold and the vegetables cooked only until just tender — the salad should have texture, not mush.","story":"Olivier salad was created in the 1860s by Lucien Olivier, the Belgian chef of Moscow's Hermitage restaurant. The original recipe with grouse and crayfish was kept secret. The Soviet version with potatoes and bologna became Russia's national New Year dish."}
,"Aguapanela":{"name":"Aguapanela","country":"Colombia","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Aguadepanela.jpg/800px-Aguadepanela.jpg","description":"Colombia's most comforting drink — raw cane sugar (panela) dissolved in hot water with lime juice. The drink of Colombian childhoods, cold mornings and long nights.","prepTime":"5 mins","cookTime":"10 mins","serves":4,"difficulty":"Easy","ingredients":[{"amount":"200g","item":"panela (raw cane sugar block), grated or broken"},{"amount":"1L","item":"water"},{"amount":"juice of 2","item":"limes"},{"amount":"fresh ginger slice","item":"optional"},{"amount":"cheese","item":"to dunk (optional — traditional)"}],"steps":["Bring water to boil in a saucepan.","Add grated panela and stir until completely dissolved.","Add lime juice. Taste and adjust sweetness.","Serve hot in mugs.","Traditionally served with a piece of fresh white cheese to dunk into the hot drink."],"tip":"Panela (raw unrefined cane sugar) has a distinctive molasses-like flavour that refined sugar cannot replicate. Find it at Latin American grocery stores.","story":"Aguapanela is Colombia's national drink, consumed from the Amazon to the Andes. It is drunk hot in the cold highlands and cold in the tropical coast. Colombian children grow up drinking it for breakfast, and it is the first thing offered to a visitor in any Colombian home."}
,"Żurek":{"name":"Żurek","country":"Poland","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Zurek_with_egg_and_sausage.jpg/800px-Zurek_with_egg_and_sausage.jpg","description":"Poland's distinctive sour rye soup — a uniquely tangy broth fermented from rye flour, with sausage, hard-boiled egg and potato. The taste of Easter in Poland.","prepTime":"5 days (fermenting)","cookTime":"30 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"100g","item":"rye flour"},{"amount":"500ml","item":"warm water"},{"amount":"3","item":"garlic cloves"},{"amount":"1L","item":"chicken or vegetable stock"},{"amount":"200g","item":"white kielbasa (biała kiełbasa), sliced"},{"amount":"4","item":"hard-boiled eggs, halved"},{"amount":"3","item":"medium potatoes, boiled and diced"},{"amount":"2 tbsp","item":"horseradish (fresh or jarred)"},{"amount":"1 tsp","item":"marjoram"}],"steps":["Make the kwas (fermented rye starter): mix rye flour with warm water and garlic in a jar. Cover with cloth and ferment at room temperature 3-5 days until sour and bubbly.","Bring stock to a simmer. Gradually whisk in the fermented rye liquid to taste — add more for more sourness.","Add kielbasa. Simmer 15 minutes.","Add marjoram and horseradish. Season with salt.","Ladle into bowls. Add diced potato and halved egg."],"tip":"The fermented rye starter can be kept in the fridge and used repeatedly — it gets better with age, like sourdough.","story":"Żurek is Poland's Easter soup, eaten on Holy Saturday and Sunday. Its distinctive sourness comes from the days-long fermentation of rye flour — a process unique to Polish cuisine. Served in a hollowed bread bowl, it is one of Poland's most ancient dishes."}
,"Gołąbki":{"name":"Gołąbki","country":"Poland","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Golabki.jpg/800px-Golabki.jpg","description":"Poland's beloved stuffed cabbage rolls — blanched cabbage leaves wrapped around a filling of pork mince and rice, braised in tomato sauce until tender.","prepTime":"45 mins","cookTime":"1 hr 30 mins","serves":6,"difficulty":"Medium","ingredients":[{"amount":"1 large","item":"white cabbage"},{"amount":"500g","item":"pork mince"},{"amount":"200g","item":"cooked rice"},{"amount":"1 large","item":"onion, finely diced"},{"amount":"2","item":"garlic cloves, minced"},{"amount":"1","item":"egg"},{"amount":"1 tsp","item":"marjoram"},{"amount":"salt and pepper","item":"to taste"},{"amount":"400g","item":"tinned tomatoes, blended"},{"amount":"400ml","item":"chicken stock"},{"amount":"2 tbsp","item":"tomato purée"}],"steps":["Carefully remove cabbage leaves by cutting around the core and blanching in boiling water until pliable. Pat dry.","Mix pork mince with cooked rice, fried onion, garlic, egg and marjoram. Season generously.","Place a heaped tablespoon of filling on each leaf. Fold sides in and roll tightly.","Pack rolls tightly into a heavy pot or baking dish, seam-side down.","Mix tomatoes, stock and tomato purée. Pour over rolls.","Cover and simmer on low heat or bake at 160°C for 1 hour 30 minutes."],"tip":"Packing the rolls tightly together in the pot stops them unrolling during the long braising.","story":"Gołąbki means little pigeons in Polish — named for their shape. They are eaten across Central and Eastern Europe under different names. In Poland they are a staple of Sunday dinners and family celebrations."}
};

