// ── RESPONSIVE AD UNIT ─────────────────────────────────────────────────
function AdUnit({ style }) {
  const [hover, setHover] = useState(false);
  const [mob, setMob] = useState(() => typeof window !== 'undefined' && window.innerWidth <= 768);
  useEffect(() => {
    const fn = () => setMob(window.innerWidth <= 768);
    window.addEventListener('resize', fn);
    fn();
    return () => window.removeEventListener('resize', fn);
  }, []);
  const h = mob ? 58 : 90;
  const divH = mob ? 26 : 38;
  return (
    <div onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}
      style={{ width:"100%", border:`1.5px dashed ${hover?"#c2622a":"#e0d8ce"}`, borderRadius:10, background:"#faf7f3", overflow:"hidden", cursor:"pointer", transition:"border-color .2s", marginBottom:8, ...style }}>
      <div style={{ fontSize:9, letterSpacing:".12em", color:"#c8bfb0", textTransform:"uppercase", textAlign:"center", padding:"5px 0 0", fontFamily:"monospace" }}>Advertisement</div>
      <div style={{ height:h, display:"flex", alignItems:"center", justifyContent:"center", gap:mob?10:14, padding:`0 ${mob?14:24}px`, position:"relative" }}>
        <div style={{ position:"absolute", top:0, left:0, right:0, height:1, background:`linear-gradient(90deg,transparent,#c2622a 40%,#c2622a 60%,transparent)`, opacity:hover?.2:.08, transition:"opacity .2s" }} />
        <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:3, flexShrink:0 }}>
          <span style={{ fontSize:mob?14:18, opacity:.25 }}>📢</span>
          <span style={{ fontFamily:"monospace", fontSize:10, color:"#c8bfb0" }}>{mob?"320 × 50":"728 × 90"}</span>
        </div>
        <div style={{ width:1, height:divH, background:"#e8e0d4", flexShrink:0 }} />
        <div style={{ display:"flex", flexDirection:"column", gap:3 }}>
          <span style={{ fontFamily:"monospace", fontSize:mob?9:10, color:"#c8bfb0" }}>{mob?"Mobile banner — insert ad tag here":"Leaderboard — insert ad tag here"}</span>
          <span style={{ fontFamily:"monospace", fontSize:9, color:"#ddd5c8" }}>Responsive · switches format by breakpoint</span>
        </div>
      </div>
    </div>
  );
}


// ── REGION MAP ─────────────────────────────────────────────────────────
function RegionMap({ onSelectRegion }) {
  const [hovered, setHovered] = useState(null);
  return (
    <div>
      <div style={{ textAlign:"center", marginBottom:16, paddingTop:8 }}>
        <div style={{ display:"inline-block", background:"#fdf3ed", borderRadius:100, padding:"6px 16px", fontSize:12, color:"#c2622a", fontWeight:600, letterSpacing:".06em", textTransform:"uppercase", marginBottom:14 }}>
          🌍 World Cuisine Explorer
        </div>
        <h1 style={{ fontFamily:"Fraunces", fontSize:"clamp(26px,4vw,48px)", fontWeight:700, color:"#1a1714", marginBottom:12, lineHeight:1.15 }}>
          What would you like to cook?
        </h1>
        <p style={{ fontSize:15, color:"#9a9088", maxWidth:460, margin:"0 auto", lineHeight:1.75 }}>
          Choose a region to explore its most beloved dishes and get the full recipe
        </p>
      </div>
      <AdUnit />
      <div className="region-grid" style={{ marginTop:24, display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(260px, 1fr))", gap:12, marginBottom:28 }}>
        {REGIONS.map(region => (
          <div key={region.id} onClick={() => onSelectRegion(region.id)}
            onMouseEnter={() => setHovered(region.id)}
            onMouseLeave={() => setHovered(null)}
            style={{
              background: hovered === region.id ? region.light : "#fff",
              border: `1.5px solid ${hovered === region.id ? region.color : "#ece6db"}`,
              borderRadius:16, padding:"20px 22px", cursor:"pointer",
              transition:"all .2s",
              transform: hovered === region.id ? "translateY(-3px)" : "none",
              boxShadow: hovered === region.id ? `0 8px 24px ${region.color}20` : "0 1px 4px rgba(0,0,0,.05)",
            }}>
            <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:8 }}>
              <div style={{ fontSize:28, lineHeight:1 }}>{region.emoji}</div>
              <div>
                <div style={{ fontFamily:"Fraunces", fontSize:17, fontWeight:700, color:"#1a1714" }}>{region.name}</div>
                <div style={{ fontSize:10, color:region.color, fontWeight:600, letterSpacing:".07em", textTransform:"uppercase", marginTop:1 }}>
                  {region.countries.length} {region.countries.length === 1 ? "cuisine" : "cuisines"}
                </div>
              </div>
            </div>
            <p style={{ fontSize:13, color:"#9a9088", lineHeight:1.6, marginBottom:10 }}>{region.description}</p>
            <div style={{ display:"flex", flexWrap:"wrap", gap:4 }}>
              {region.countries.slice(0,5).map(c => (
                <span key={c} style={{ fontSize:11, background:"#faf7f3", border:"1px solid #ece6db", borderRadius:6, padding:"2px 8px", color:"#9a9088" }}>
                  {COUNTRY_DISHES[c]?.flag} {c}
                </span>
              ))}
              {region.countries.length > 5 && <span style={{ fontSize:11, color:"#c8bfb0", padding:"2px 4px" }}>+{region.countries.length - 5} more</span>}
            </div>
          </div>
        ))}
      </div>
      <AdUnit />
    </div>
  );
}

// ── REGION VIEW ────────────────────────────────────────────────────────
function RegionView({ regionId, onBack, onSelectCountry }) {
  const region = REGIONS.find(r => r.id === regionId);
  if (!region) return null;
  return (
    <div style={{ maxWidth:720, margin:"0 auto" }}>
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom:24 }}>← All Regions</button>
      <div style={{ marginBottom:8 }}>
        <div style={{ fontSize:44, marginBottom:8 }}>{region.emoji}</div>
        <h1 style={{ fontFamily:"Fraunces", fontSize:32, fontWeight:700, color:"#1a1714", marginBottom:6 }}>{region.name}</h1>
        <p style={{ fontSize:14, color:"#9a9088", marginBottom:6 }}>{region.description}</p>
        <div style={{ height:3, width:40, background:region.color, borderRadius:2, marginBottom:24 }} />
      </div>
      <AdUnit />
      <div style={{ marginTop:24, marginBottom:28 }}>
        <p style={{ fontSize:11, color:"#b8b0a8", marginBottom:14, letterSpacing:".08em", textTransform:"uppercase", fontWeight:600 }}>Select a country</p>
        <div style={{ display:"flex", flexWrap:"wrap", gap:10 }}>
          {region.countries.map(country => (
            <button key={country} onClick={() => onSelectCountry(country)}
              style={{ display:"inline-flex", alignItems:"center", gap:10, background:"#fff", border:`1.5px solid #ece6db`, borderRadius:12, padding:"12px 18px", cursor:"pointer", fontSize:14, color:"#1a1714", fontFamily:"Plus Jakarta Sans", transition:"all .15s", boxShadow:"0 1px 4px rgba(0,0,0,.05)", fontWeight:500 }}
              onMouseEnter={e => { e.currentTarget.style.borderColor=region.color; e.currentTarget.style.background=region.light; e.currentTarget.style.boxShadow=`0 4px 14px ${region.color}20`; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor="#ece6db"; e.currentTarget.style.background="#fff"; e.currentTarget.style.boxShadow="0 1px 4px rgba(0,0,0,.05)"; }}>
              <span style={{ fontSize:24 }}>{COUNTRY_DISHES[country]?.flag || "🌍"}</span>
              <span>{country}</span>
            </button>
          ))}
        </div>
      </div>
      <AdUnit />
    </div>
  );
}

// ── COUNTRY VIEW ───────────────────────────────────────────────────────
function CountryView({ country, onBack, onSelectDish }) {
  const preset = COUNTRY_DISHES[country];
  const flag = preset?.flag || "🌍";
  const dishes = preset?.dishes || [];

  return (
    <div style={{ maxWidth:700, margin:"0 auto" }}>
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom:24 }}>← Back</button>
      <div style={{ marginBottom:8 }}>
        <div style={{ fontSize:44, marginBottom:8 }}>{flag}</div>
        <h1 style={{ fontFamily:"Fraunces", fontSize:30, fontWeight:700, color:"#1a1714", marginBottom:6 }}>{country}</h1>
        <p style={{ fontSize:14, color:"#9a9088", marginBottom:20 }}>Choose a dish to view the full recipe</p>
      </div>
      <AdUnit />
      <div style={{ marginTop:24, marginBottom:28 }}>
        <div className="dish-grid" style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
          {dishes.map((dish,i) => (
            <div key={i} className="dish-card" onClick={() => onSelectDish(dish)}>
              <div>
                <div style={{ fontSize:14, fontWeight:600, color:"#1a1714", marginBottom:3 }}>{dish}</div>
                <div style={{ fontSize:11, color:"#b8b0a8", fontWeight:500 }}>View recipe →</div>
              </div>
              <span style={{ fontSize:16, color:"#ddd5c8" }}>→</span>
            </div>
          ))}
        </div>
      </div>
      <AdUnit />
    </div>
  );
}

